{
  "name": "CivicTwin: Smart City Digital Twin",
  "description": "A comprehensive digital twin platform for cities and communities, integrating NIST Smart City frameworks with live GIS data and AI-driven urban insights.",
  "requestFramePermissions": [
    "geolocation"
  ]
}

export interface GeoLocation {
  lat: number;
  lng: number;
  displayName: string;
}

export interface TwinMetadata {
  name: string;
  address: string;
  location: GeoLocation | null;
  type: 'City' | 'Community' | 'Farm' | 'Special District';
}

export enum NISTLayer {
  ENERGY = 'Energy',
  WATER = 'Water',
  WASTE = 'Waste',
  TRANSPORTATION = 'Transportation',
  PUBLIC_SAFETY = 'Public Safety',
  HEALTHCARE = 'Healthcare'
}

export interface SmartCityInsight {
  layer: NISTLayer;
  status: 'optimal' | 'warning' | 'critical';
  value: string;
  summary: string;
  recommendations: string[];
}

export interface DashboardState {
  metadata: TwinMetadata;
  insights: SmartCityInsight[];
  isGenerating: boolean;
}

import { GoogleGenAI, Type } from "@google/genai";
import { TwinMetadata, SmartCityInsight, NISTLayer } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateDigitalTwinInsights = async (metadata: TwinMetadata): Promise<SmartCityInsight[]> => {
  const prompt = `
    Analyze the following entity for a Digital Twin application based on the NIST Smart Cities framework.
    Entity Name: ${metadata.name}
    Address: ${metadata.address}
    Type: ${metadata.type}
    Location: ${metadata.location?.lat}, ${metadata.location?.lng}

    Provide detailed, realistic (but simulated) data insights for the following layers:
    - Energy
    - Water
    - Waste
    - Transportation
    - Public Safety
    - Healthcare

    For each layer, provide a status (optimal, warning, critical), a current value/metric, a summary, and 2 key recommendations.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              layer: { type: Type.STRING },
              status: { type: Type.STRING },
              value: { type: Type.STRING },
              summary: { type: Type.STRING },
              recommendations: {
                type: Type.ARRAY,
                items: { type: Type.STRING }
              }
            },
            required: ["layer", "status", "value", "summary", "recommendations"]
          }
        }
      }
    });

    const results = JSON.parse(response.text || "[]");
    return results as SmartCityInsight[];
  } catch (error) {
    console.error("Error generating twin insights:", error);
    throw error;
  }
};

