export const DataLayerCard: React.FC<DataLayerCardProps> = ({ insight }) => {
  const getStatusColor = (status: string) => {
    switch (status.toLowerCase()) {
      case 'optimal': return 'text-emerald-600 bg-emerald-50 border-emerald-100';
      case 'warning': return 'text-amber-600 bg-amber-50 border-amber-100';
      case 'critical': return 'text-rose-600 bg-rose-50 border-rose-100';
      default: return 'text-slate-600 bg-slate-50 border-slate-100';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status.toLowerCase()) {
      case 'optimal': return '●';
      case 'warning': return '▲';
      case 'critical': return '✖';
      default: return '○';
    }
  };

  return (
    <div className="bg-white border border-slate-100 rounded-xl p-5 hover:shadow-md transition-shadow group">
      <div className="flex justify-between items-start mb-4">
        <div>
          <h3 className="text-sm font-bold text-slate-500 uppercase tracking-wider mb-1">{insight.layer}</h3>
          <p className="text-2xl font-bold text-slate-900">{insight.value}</p>
        </div>
        <div className={`px-2.5 py-1 rounded-full text-xs font-bold border flex items-center gap-1 ${getStatusColor(insight.status)}`}>
