}

export const DataLayerCard: React.FC<DataLayerCardProps> = ({ insight }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSimulating, setIsSimulating] = useState(false);

  const getStatusConfig = (status: string) => {
    switch (status.toLowerCase()) {
      case 'optimal': return { color: 'text-emerald-600 bg-emerald-50 border-emerald-100', icon: 'check_circle', glow: 'shadow-emerald-200/50' };
      case 'warning': return { color: 'text-amber-600 bg-amber-50 border-amber-100', icon: 'error_outline', glow: 'shadow-amber-200/50' };
      case 'critical': return { color: 'text-rose-600 bg-rose-50 border-rose-100', icon: 'report_problem', glow: 'shadow-rose-200/50' };
      default: return { color: 'text-slate-600 bg-slate-50 border-slate-100', icon: 'help_outline', glow: 'shadow-slate-200/50' };
    }
  };

  const config = getStatusConfig(insight.status);

  const handleRunSimulation = () => {
    setIsSimulating(true);
    setTimeout(() => setIsSimulating(false), 2000);
  };

  return (
    <>
      <div 
        onClick={() => setIsModalOpen(true)}
        className="bg-white border border-slate-200/60 rounded-[2rem] p-6 sm:p-8 hover:shadow-2xl hover:-translate-y-1.5 transition-all duration-300 group flex flex-col cursor-pointer h-full"
