          {insight.summary}
        </p>

        <div className="mt-auto pt-6 border-t border-slate-50 space-y-4">
          <div className="flex items-center justify-between">
            <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Digital Twin Guidance</h4>
            <span className="text-blue-500 text-xs font-bold group-hover:translate-x-1 transition-transform">Details →</span>
