        {isExpanded && (
          <div className="glass-panel px-3 py-2 rounded-xl text-[10px] font-black text-blue-600 shadow-xl border border-white/50 flex items-center gap-2 animate-in slide-in-from-left duration-500">
            <span className="w-1.5 h-1.5 bg-blue-500 rounded-full"></span>
