import { GoogleGenAI, Type } from "@google/genai";
import { TwinMetadata, SmartCityInsight, NISTLayer } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateDigitalTwinInsights = async (metadata: TwinMetadata): Promise<SmartCityInsight[]> => {
  const prompt = `
    Analyze the following entity for a Digital Twin application based on the NIST Smart Cities framework.
    Entity Name: ${metadata.name}
    Address: ${metadata.address}
    Type: ${metadata.type}
    Location: ${metadata.location?.lat}, ${metadata.location?.lng}
    Official Portal: ${metadata.officialUrl || 'Not provided'}

    Provide detailed, realistic (but simulated) data insights for the following layers:
    - Energy
    - Water
    - Waste
    - Transportation
    - Public Safety
    - Healthcare

    If an Official Portal is provided, tailor your analysis to typical data found on that city's/district's portal.
    For each layer, provide a status (optimal, warning, critical), a current value/metric (use units), a summary, and 2 key recommendations.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              layer: { type: Type.STRING },
              status: { type: Type.STRING },
              value: { type: Type.STRING },
              summary: { type: Type.STRING },
              recommendations: {
                type: Type.ARRAY,
                items: { type: Type.STRING }
              }
            },
            required: ["layer", "status", "value", "summary", "recommendations"]
          }
        }
      }
    });

    const results = JSON.parse(response.text || "[]");
    return results as SmartCityInsight[];
  } catch (error) {
    console.error("Error generating twin insights:", error);
    throw error;
  }
};

export const generatePRSummary = async (metadata: TwinMetadata, insights: SmartCityInsight[]): Promise<{title: string, body: string}> => {
  const prompt = `
    Write a GitHub Pull Request description for updating a Digital Twin model.
    The repository is "Civic-Twin-by-Angel-Sharks".
    Entity: ${metadata.name}
    Metrics summary: ${insights.map(i => `${i.layer}: ${i.value} (${i.status})`).join(', ')}

    The PR should be professional, technical, and follow a standard template:
    1. Summary of changes (GIS update, NIST layer calibration)
    2. Impact analysis
    3. Suggested follow-up actions

    Return JSON with "title" and "body" (Markdown) fields.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            body: { type: Type.STRING }
          },
          required: ["title", "body"]
        }
      }
    });

    return JSON.parse(response.text || '{"title": "Update Twin", "body": "Updating metrics."}');
  } catch (error) {
    console.error("Error generating PR summary:", error);
    return {
      title: `feat: Update Digital Twin metrics for ${metadata.name}`,
      body: "Manual update of NIST urban layers and GIS spatial core."
    };
  }
};

import React, { useState } from 'react';
import { TwinMetadata, SmartCityInsight } from '../types';

interface PRManagerProps {
  metadata: TwinMetadata;
  insights: SmartCityInsight[];
  prContent: { title: string; body: string } | null;
  onClose: () => void;
  isGenerating: boolean;
}

export const PRManager: React.FC<PRManagerProps> = ({ metadata, insights, prContent, onClose, isGenerating }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    if (!prContent) return;
    const fullText = `# ${prContent.title}\n\n${prContent.body}`;
    navigator.clipboard.writeText(fullText);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
