import { generatePRSummary } from '../services/geminiService';

interface DashboardProps {
  metadata: TwinMetadata;
  insights: SmartCityInsight[];
  isLoading: boolean;
  onRefresh: () => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ metadata, insights, isLoading, onRefresh }) => {
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMapExpanded, setIsMapExpanded] = useState(false);
  const [meshNodes, setMeshNodes] = useState<MeshNode[]>([]);
  const [tacticalAlerts, setTacticalAlerts] = useState<TacticalAlert[]>([]);

  // PR State
  const [isPRManagerOpen, setIsPRManagerOpen] = useState(false);
  const [prContent, setPrContent] = useState<{ title: string; body: string } | null>(null);
  const [isGeneratingPR, setIsGeneratingPR] = useState(false);
  const [hasChanges, setHasChanges] = useState(false);

  useEffect(() => {
    if (insights.length > 0) setHasChanges(true);
  }, [insights]);

  // Initialize B-lan simulated data
  useEffect(() => {
    if (metadata.isEmergencyMode) {
      setMeshNodes([
        { id: 'AS-PRIMARY', status: 'active', signal: 98, type: 'Fog' },
        { id: 'AS-RELAY-01', status: 'active', signal: 72, type: 'Static' },
        { id: 'AS-MOBILE-X', status: 'relay', signal: 45, type: 'Mobile' },
      ]);
      setTacticalAlerts([
        { timestamp: '14:22:01', sender: 'ANGEL-SHARK-LEAD', message: 'B-lan mesh established in Sector 4. IoT cloud bypassed.', priority: 'high' },
        { timestamp: '14:24:45', sender: 'FOG-NODE-PRIMARY', message: 'HOT FOG localized compute reaching 85% capacity. Offloading to AS-RELAY-01.', priority: 'low' },
        { timestamp: '14:30:12', sender: 'SYSTEM', message: 'CRITICAL: Water pressure drop detected in Zone B. Manual override requested.', priority: 'critical' },
      ]);
    }
  }, [metadata.isEmergencyMode]);

  const handleProposePR = async () => {
    setIsPRManagerOpen(true);
    setIsGeneratingPR(true);
    try {
      const summary = await generatePRSummary(metadata, insights);
      setPrContent(summary);
      setHasChanges(false);
    } catch (err) {
      console.error("PR Generation failed", err);
    } finally {
      setIsGeneratingPR(false);
    }
