      `}>
        <div className="h-full flex flex-col p-6 overflow-y-auto">
          <div className="flex items-center justify-between mb-8 lg:hidden">
            <span className="font-bold text-slate-400 text-xs tracking-widest uppercase">Twin Stats</span>
            <button onClick={() => setIsSidebarOpen(false)} className="text-slate-400 font-bold p-2">✕</button>
          </div>

          <div className="mb-8">
            <div className={`flex items-center gap-2 text-[10px] font-bold mb-2 uppercase tracking-widest ${metadata.isEmergencyMode ? 'text-rose-500' : 'text-emerald-600'}`}>
              <span className={`w-2.5 h-2.5 rounded-full animate-pulse ${metadata.isEmergencyMode ? 'bg-rose-500' : 'bg-emerald-500'}`}></span>
              {metadata.isEmergencyMode ? 'B-LAN TACTICAL LINK' : 'Synchronized'}
            </div>
            <h2 className={`text-2xl font-black leading-tight mb-2 break-words ${metadata.isEmergencyMode ? 'text-white' : 'text-slate-900'}`}>{metadata.name}</h2>
            <div className={`px-3 py-1 rounded-lg text-xs font-bold inline-block ${metadata.isEmergencyMode ? 'bg-rose-900/40 text-rose-300 shadow-lg shadow-rose-950/20' : 'bg-slate-100 text-slate-600'}`}>
              {metadata.isEmergencyMode ? 'ANGEL SHARK BACKUP' : `${metadata.type} Framework`}
            </div>
          </div>

          <nav className="space-y-6 flex-1">
            <section>
              <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Repo Management</h3>
              <div className="space-y-2">
                <a 
                  href="https://github.com/ADD12/Civic-Twin-by-Angel-Sharks"
                  target="_blank"
                  rel="noopener noreferrer"
                  className={`p-4 rounded-2xl border flex items-center gap-3 transition-all hover:scale-[1.02] active:scale-95 ${metadata.isEmergencyMode ? 'bg-slate-800 border-slate-700' : 'bg-slate-100/50 border-slate-100 shadow-sm'}`}
                >
                  <div className="text-xl">🐙</div>
                  <div>
                    <p className="text-[10px] font-black text-slate-400 uppercase">Civic Twin Repo</p>
