              </div>
            </section>

            <section>
              <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Core Telemetry</h3>
              <div className="space-y-4">
                <div className={`p-4 rounded-2xl border ${metadata.isEmergencyMode ? 'bg-slate-800 border-slate-700' : 'bg-slate-50 border-slate-100'}`}>
