                  <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">Coordinates</p>
                  <p className={`text-sm font-mono tracking-tighter ${metadata.isEmergencyMode ? 'text-slate-300' : 'text-slate-700'}`}>
                    {metadata.location?.lat.toFixed(4)}°N, {metadata.location?.lng.toFixed(4)}°W
