          <div className="mt-8 pt-6 border-t border-slate-100">
            <button
              onClick={onRefresh}
              disabled={isLoading}
              className={`w-full py-4 rounded-2xl font-bold text-sm shadow-xl active:scale-95 disabled:opacity-50 transition-all ${metadata.isEmergencyMode ? 'bg-rose-600 text-white shadow-rose-900/40' : 'bg-slate-900 text-white'}`}
            >
              {isLoading ? 'Re-Routing...' : 'Sync Layer Matrix'}
            </button>
          </div>
        </div>
      </aside>

      {/* Main Responsive Viewport */}
      <div className="flex-1 flex flex-col min-w-0 h-full relative">

        {/* Emergency Banner */}
