            onClick={() => setIsSidebarOpen(true)}
            className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold active:bg-slate-200 ${metadata.isEmergencyMode ? 'bg-slate-800 text-slate-300' : 'bg-slate-100 text-slate-600'}`}
          >
            <span>📊</span> Entity Stats
          </button>
          <div className="text-xs font-bold text-slate-400">Layer View: {metadata.isEmergencyMode ? 'Tactical' : 'Standard'}</div>
