import React, { useEffect, useRef, useState } from 'react';
import { GeoLocation } from '../types';

interface MapProps {
  location: GeoLocation;
  name: string;
  isExpanded?: boolean;
}

export const Map: React.FC<MapProps> = ({ location, name, isExpanded }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);

  // Simulated layer visibility states
  const [layers, setLayers] = useState({
    parcels: true,
    utilities: true,
    greenery: true
  });

  useEffect(() => {
    if (mapContainerRef.current && !mapRef.current) {
      // Initialize map
      mapRef.current = (window as any).L.map(mapContainerRef.current, {
        zoomControl: false // Custom controls look better
      }).setView([location.lat, location.lng], 15);

      (window as any).L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
      }).addTo(mapRef.current);

      (window as any).L.control.zoom({
        position: 'bottomleft'
      }).addTo(mapRef.current);

      (window as any).L.marker([location.lat, location.lng])
        .addTo(mapRef.current)
        .bindPopup(`<b>${name}</b><br/>Digital Twin Core`)
        .openPopup();
    }

    // Invalidate size when expanded state changes to prevent rendering issues
    if (mapRef.current) {
      setTimeout(() => {
        mapRef.current.invalidateSize();
        if (isExpanded) {
          mapRef.current.setZoom(17, { animate: true });
        } else {
          mapRef.current.setZoom(15, { animate: true });
        }
      }, 500); // Sync with CSS transition
    }
  }, [location, name, isExpanded]);

  const toggleLayer = (layer: keyof typeof layers) => {
    setLayers(prev => ({ ...prev, [layer]: !prev[layer] }));
  };

  return (
    <div className="w-full h-full relative bg-slate-200 transition-all duration-500">
      <div ref={mapContainerRef} className="w-full h-full" />

      {/* Floating GIS Info */}
      <div className="absolute top-4 left-4 z-[1000] flex flex-col gap-2">
        <div className="glass-panel px-4 py-2.5 rounded-2xl text-[10px] font-black text-slate-800 shadow-xl border border-white/60 flex items-center gap-2.5">
          <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.6)]"></span>
          OFFICIAL GIS DATA SOURCE
        </div>
        {isExpanded && (
          <div className="glass-panel px-4 py-2.5 rounded-2xl text-[10px] font-black text-blue-600 shadow-xl border border-white/60 flex items-center gap-2.5 animate-in slide-in-from-left duration-500">
            <span className="w-2 h-2 bg-blue-500 rounded-full shadow-[0_0_8px_rgba(59,130,246,0.6)]"></span>
            DETAILED BUILDING FOOTPRINTS ACTIVE
          </div>
        )}
      </div>

      {/* Enhanced Detail Overlay Legend (Visible when expanded) */}
      {isExpanded && (
        <div className="absolute bottom-6 right-6 z-[1000] glass-panel p-5 rounded-[2rem] border border-white/60 shadow-2xl animate-in slide-in-from-bottom duration-500 w-[280px]">
          <div className="flex items-center justify-between mb-4">
            <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest">Urban Layer Legend</h4>
            <div className="text-[9px] font-bold text-slate-400 bg-slate-100 px-2 py-0.5 rounded-full">LIVE</div>
          </div>

          <div className="space-y-4">
            {/* Parcel Boundaries */}
            <div className={`group flex items-start gap-3 p-2.5 rounded-2xl transition-all cursor-pointer ${layers.parcels ? 'bg-blue-50/50' : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer('parcels')}>
              <div className="w-5 h-5 bg-blue-500/20 border-2 border-blue-500 rounded-lg shrink-0 mt-0.5 group-hover:scale-110 transition-transform"></div>
              <div>
                <span className="text-xs font-black text-slate-800 block mb-0.5">Parcel Boundaries</span>
                <p className="text-[9px] font-medium text-slate-500 leading-tight">Property lines, zoning limits, and public right-of-way markers.</p>
              </div>
            </div>

            {/* Underground Utilities */}
            <div className={`group flex items-start gap-3 p-2.5 rounded-2xl transition-all cursor-pointer ${layers.utilities ? 'bg-rose-50/50' : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer('utilities')}>
              <div className="w-5 h-5 bg-rose-500/20 border-2 border-rose-500 rounded-lg shrink-0 mt-0.5 group-hover:scale-110 transition-transform"></div>
              <div>
                <span className="text-xs font-black text-slate-800 block mb-0.5">Underground Utilities</span>
                <p className="text-[9px] font-medium text-slate-500 leading-tight">Hydraulic pipes, high-voltage cables, and fiber-optic mesh.</p>
              </div>
            </div>

            {/* Public Green Space */}
            <div className={`group flex items-start gap-3 p-2.5 rounded-2xl transition-all cursor-pointer ${layers.greenery ? 'bg-emerald-50/50' : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer('greenery')}>
              <div className="w-5 h-5 bg-emerald-500/20 border-2 border-emerald-500 rounded-lg shrink-0 mt-0.5 group-hover:scale-110 transition-transform"></div>
              <div>
                <span className="text-xs font-black text-slate-800 block mb-0.5">Public Green Space</span>
                <p className="text-[9px] font-medium text-slate-500 leading-tight">Parks, conservation easements, and environmental buffer zones.</p>
              </div>
            </div>
          </div>

          <div className="mt-5 pt-4 border-t border-slate-100">
            <p className="text-[9px] font-bold text-slate-400 text-center italic">
              Click a layer card to toggle visibility in GIS view.
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

export interface GeoLocation {
  lat: number;
  lng: number;
  displayName: string;
}

export interface MeshNode {
  id: string;
  status: 'active' | 'relay' | 'failing';
  signal: number; // 0-100
  type: 'Static' | 'Mobile' | 'Fog' | 'Fiber' | 'Wi-Fi';
}

export interface TacticalAlert {
  timestamp: string;
  sender: string;
  message: string;
  priority: 'low' | 'high' | 'critical';
}

export interface TwinMetadata {
  name: string;
  address: string;
  location: GeoLocation | null;
  type: 'City' | 'Community' | 'Farm' | 'Special District';
  officialUrl?: string;
  isEmergencyMode?: boolean;
}

export enum NISTLayer {
  ENERGY = 'Energy',
  WATER = 'Water',
  WASTE = 'Waste',
  TRANSPORTATION = 'Transportation',
  PUBLIC_SAFETY = 'Public Safety',
  HEALTHCARE = 'Healthcare'
}

export interface SmartCityInsight {
  layer: NISTLayer;
  status: 'optimal' | 'warning' | 'critical';
  value: string;
  summary: string;
  recommendations: string[];
}

export type ViewType = 'dashboard' | 'gis-analysis';

export interface DashboardState {
  metadata: TwinMetadata;
  insights: SmartCityInsight[];
  isGenerating: boolean;
  currentView: ViewType;
}

