import React, { useState, useEffect } from 'react';
import { TwinMetadata, MeshNode, TacticalAlert } from '../types';
import { Map } from './Map';

interface GISAnalysisProps {
  metadata: TwinMetadata;
}

export const GISAnalysis: React.FC<GISAnalysisProps> = ({ metadata }) => {
  const [simulationActive, setSimulationActive] = useState(false);
  const [simulationStep, setSimulationStep] = useState(0);
  const [networkNodes, setNetworkNodes] = useState<MeshNode[]>([
    { id: 'FIBER-CORE-A', status: 'active', signal: 100, type: 'Fiber' },
    { id: 'WIFI-NODE-01', status: 'active', signal: 85, type: 'Wi-Fi' },
    { id: 'WIFI-NODE-02', status: 'active', signal: 92, type: 'Wi-Fi' },
    { id: 'FOG-RELAY-1', status: 'active', signal: 70, type: 'Fog' },
  ]);
  const [simLogs, setSimLogs] = useState<string[]>([]);

  const addLog = (msg: string) => {
    setSimLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev].slice(0, 10));
  };

  const startSimulation = () => {
    setSimulationActive(true);
    setSimulationStep(1);
    setSimLogs([]);
    addLog("INITIATING DISASTER RESILIENCE SIMULATION...");
  };

  useEffect(() => {
    if (!simulationActive) return;

    const timer = setTimeout(() => {
      switch (simulationStep) {
        case 1:
          addLog("STAGE 1: PRIMARY POWER GRID INTERRUPTION DETECTED.");
          setNetworkNodes(prev => prev.map(n => n.type === 'Fiber' ? { ...n, status: 'failing', signal: 10 } : n));
          setSimulationStep(2);
          break;
        case 2:
          addLog("STAGE 2: INTERNET BACKBONE OUTAGE. SWITCHING TO AD-HOC B-LAN.");
          setNetworkNodes(prev => prev.map(n => n.type === 'Wi-Fi' ? { ...n, status: 'relay', signal: 45 } : n));
          setSimulationStep(3);
          break;
        case 3:
          addLog("STAGE 3: ANGEL SHARK TACTICAL MESH ESTABLISHED.");
          setNetworkNodes(prev => [
            ...prev,
            { id: 'MOBILE-RESCUE-X', status: 'active', signal: 95, type: 'Mobile' }
          ]);
          setSimulationStep(4);
          break;
        case 4:
          addLog("SIMULATION COMPLETE. SYSTEM STABILIZED VIA MESH RELAY.");
          setSimulationActive(false);
          break;
      }
    }, 2500);

    return () => clearTimeout(timer);
  }, [simulationActive, simulationStep]);

  return (
    <div className="flex-1 flex flex-col lg:flex-row min-h-0 bg-slate-950 text-slate-200 overflow-hidden">
      {/* Control Panel */}
      <aside className="w-full lg:w-[400px] border-r border-slate-800 p-6 flex flex-col gap-6 overflow-y-auto">
        <div>
          <h2 className="text-2xl font-black tracking-tight text-white mb-1">Route Planning</h2>
          <p className="text-xs font-bold text-slate-500 uppercase tracking-widest">Fiber & Wi-Fi Analysis</p>
        </div>

        <section className="bg-slate-900 border border-slate-800 rounded-3xl p-6 space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-xs font-black text-blue-500 uppercase tracking-widest">Connectivity Core</h3>
            <span className={`w-2 h-2 rounded-full ${simulationActive ? 'bg-rose-500 animate-pulse' : 'bg-emerald-500'}`}></span>
          </div>

          <div className="space-y-3">
            {networkNodes.map(node => (
              <div key={node.id} className="flex items-center justify-between p-3 bg-slate-950 rounded-2xl border border-slate-800 transition-all">
                <div className="flex items-center gap-3">
                  <div className={`w-1 h-8 rounded-full ${node.status === 'active' ? 'bg-emerald-500' : node.status === 'relay' ? 'bg-amber-500' : 'bg-rose-500 animate-pulse'}`}></div>
                  <div>
                    <p className="text-[10px] font-black uppercase text-slate-300">{node.id}</p>
                    <p className="text-[9px] text-slate-500 font-bold">{node.type}</p>
                  </div>
                </div>
                <div className="text-right">
                  <span className={`text-[10px] font-mono ${node.signal > 70 ? 'text-emerald-500' : node.signal > 30 ? 'text-amber-500' : 'text-rose-500'}`}>{node.signal}%</span>
                </div>
              </div>
            ))}
          </div>
        </section>

        <section className="flex-1 flex flex-col gap-4">
          <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest">Disaster Simulation</h3>
          <button 
            onClick={startSimulation}
            disabled={simulationActive}
            className="w-full py-4 bg-rose-600 hover:bg-rose-500 disabled:bg-slate-800 text-white font-black rounded-2xl shadow-xl shadow-rose-900/10 transition-all active:scale-95 flex items-center justify-center gap-3"
          >
            {simulationActive ? (
              <>
                <div className="w-4 h-4 border-2 border-white/20 border-t-white rounded-full animate-spin"></div>
                SIMULATING OUTAGE...
              </>
            ) : (
              <>
                <span>🚀</span> RUN STRESS TEST
              </>
            )}
          </button>

          <div className="flex-1 bg-slate-950 border border-slate-800 rounded-3xl p-4 font-mono text-[10px] space-y-2 overflow-y-auto">
            {simLogs.length === 0 && <p className="text-slate-700 italic">Ready for simulation input...</p>}
            {simLogs.map((log, i) => (
              <div key={i} className={log.includes('COMPLETE') ? 'text-emerald-400' : log.includes('INTERRUPTION') ? 'text-rose-400' : 'text-slate-400'}>
                {log}
              </div>
            ))}
          </div>
        </section>
      </aside>

      {/* Map Viewport */}
      <div className="flex-1 relative">
        <div className={`absolute inset-0 transition-all duration-1000 ${simulationActive && simulationStep >= 1 ? 'brightness-[0.4] grayscale-[0.8]' : 'brightness-100'}`}>
          {metadata.location && (
            <Map 
              location={metadata.location} 
              name={`${metadata.name} - Connectivity View`} 
              isExpanded={true} 
            />
          )}
        </div>

        {/* HUD Overlay */}
        <div className="absolute top-6 left-6 z-[1000] space-y-3 pointer-events-none">
          <div className="bg-slate-900/80 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3">
            <span className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></span>
            <span className="text-[10px] font-black uppercase text-slate-300 tracking-widest">Fiber Routes: Synchronized</span>
          </div>
          {simulationActive && (
            <div className="bg-rose-600/90 backdrop-blur-md px-4 py-2 rounded-xl border border-rose-400/20 flex items-center gap-3 animate-bounce">
              <span className="text-[10px] font-black uppercase text-white tracking-widest">CRITICAL: GRID OFFLINE</span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Layout } from './components/Layout';
import { Onboarding } from './components/Onboarding';
import { Dashboard } from './components/Dashboard';
import { GISAnalysis } from './components/GISAnalysis';
import { TwinMetadata, SmartCityInsight, ViewType } from './types';
import { generateDigitalTwinInsights } from './services/geminiService';

const App: React.FC = () => {
  const [metadata, setMetadata] = useState<TwinMetadata | null>(null);
  const [insights, setInsights] = useState<SmartCityInsight[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const fetchInsights = useCallback(async (data: TwinMetadata) => {
    setIsLoading(true);
    try {
      const results = await generateDigitalTwinInsights(data);
      setInsights(results);
    } catch (err) {
      console.error("Failed to load twin insights", err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleOnboardingComplete = (data: TwinMetadata) => {
    setMetadata(data);
    fetchInsights(data);
  };

  const handleRefresh = () => {
    if (metadata) fetchInsights(metadata);
  };

  return (
    <Layout 
      currentView={currentView} 
      onViewChange={setCurrentView} 
      isMetadataSet={!!metadata}
    >
      {!metadata ? (
        <Onboarding onComplete={handleOnboardingComplete} />
      ) : currentView === 'dashboard' ? (
        <Dashboard 
          metadata={metadata} 
          insights={insights} 
          isLoading={isLoading} 
          onRefresh={handleRefresh}
        />
      ) : (
        <GISAnalysis metadata={metadata} />
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { TwinMetadata, MeshNode, NISTLayer } from '../types';
import { Map } from './Map';

interface GISAnalysisProps {
  metadata: TwinMetadata;
}

type AnalysisModule = 'connectivity' | 'water' | 'traffic';

export const GISAnalysis: React.FC<GISAnalysisProps> = ({ metadata }) => {
  const [activeModule, setActiveModule] = useState<AnalysisModule>('connectivity');
  const [simulationActive, setSimulationActive] = useState(false);
  const [simLogs, setSimLogs] = useState<string[]>([]);

  // State for Connectivity
  const [networkNodes, setNetworkNodes] = useState<MeshNode[]>([
    { id: 'FIBER-HUB-01', status: 'active', signal: 100, type: 'Fiber' },
    { id: 'WIFI-SECTOR-A', status: 'active', signal: 85, type: 'Wi-Fi' },
    { id: 'HOSPITAL-NODE-NORTH', status: 'active', signal: 95, type: 'Static' }, // Hospital Node
    { id: 'HOSPITAL-NODE-SOUTH', status: 'active', signal: 90, type: 'Static' }, // Hospital Node
  ]);

  // State for Water Deep Dive
  const [waterCauseData, setWaterCauseData] = useState([
    { label: 'Irrigation Inefficiency', value: 45, color: 'bg-rose-500' },
    { label: 'Aging Infrastructure (Leaks)', value: 30, color: 'bg-amber-500' },
    { label: 'Domestic Consumption', value: 25, color: 'bg-emerald-500' },
  ]);

  // State for Traffic Simulation
  const [trafficMetric, setTrafficMetric] = useState(12.4);

  const addLog = (msg: string) => {
    setSimLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev].slice(0, 15));
  };

  const runConnectivitySim = async () => {
    setSimulationActive(true);
    addLog("INITIATING DISASTER RESILIENCE SIMULATION...");
    await new Promise(r => setTimeout(r, 1500));
    addLog("STAGE 1: POWER GRID DOWN. FAILOVER TO B-LAN BATTERY NODES...");
    setNetworkNodes(prev => prev.map(n => ({ ...n, status: n.type === 'Fiber' ? 'failing' : 'relay', signal: Math.floor(Math.random() * 40) + 10 })));
    await new Promise(r => setTimeout(r, 1500));
    addLog("STAGE 2: FIBER BACKBONE CUT. MESH RELAY PROTOCOL ACTIVE.");
    addLog("HOSPITAL-NODE-NORTH: RE-ROUTING VIA EMERGENCY WI-FI LINK.");
    await new Promise(r => setTimeout(r, 1500));
    addLog("SIMULATION COMPLETE: Connectivity maintained at 45% capacity.");
    setSimulationActive(false);
  };

  const runTrafficMitigation = async () => {
    setSimulationActive(true);
    addLog("RUNNING PEAK HOUR TRAFFIC MITIGATION SCENARIO...");
    await new Promise(r => setTimeout(r, 1000));
    addLog("CALIBRATING SMART SIGNALS AT LAS VIRGENES RD & AGOURA RD...");
    for (let i = 12.4; i > 9.8; i -= 0.4) {
      setTrafficMetric(parseFloat(i.toFixed(1)));
      await new Promise(r => setTimeout(r, 400));
    }
    addLog("MITIGATION SUCCESS: Delay reduced to 9.8 mins (21% improvement).");
    setSimulationActive(false);
  };

  return (
    <div className="flex-1 flex flex-col lg:flex-row min-h-0 bg-slate-950 text-slate-200 overflow-hidden">
      {/* Research Sidebar */}
      <aside className="w-full lg:w-[420px] border-r border-slate-800 flex flex-col overflow-hidden">
        <header className="p-6 border-b border-slate-800 bg-slate-900/50">
          <h2 className="text-xl font-black text-white tracking-tight mb-1">GIS Layer Analysis</h2>
          <p className="text-[10px] font-bold text-rose-500 uppercase tracking-[0.2em]">Research Center | {metadata.name}</p>
        </header>

        {/* Module Switcher */}
        <nav className="flex border-b border-slate-800">
          {(['connectivity', 'water', 'traffic'] as AnalysisModule[]).map(mod => (
            <button
              key={mod}
              onClick={() => setActiveModule(mod)}
              className={`flex-1 py-4 text-[10px] font-black uppercase tracking-widest transition-all ${
                activeModule === mod ? 'text-white border-b-2 border-rose-500 bg-slate-900' : 'text-slate-500 hover:text-slate-300'
              }`}
            >
              {mod}
            </button>
          ))}
        </nav>

        <div className="flex-1 overflow-y-auto p-6 space-y-8 scrollbar-thin scrollbar-thumb-slate-800">

          {activeModule === 'connectivity' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-left duration-300">
              <section className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-xs font-black text-blue-500 uppercase tracking-widest">Network QA Verification</h3>
                  <span className="text-[9px] font-bold bg-blue-500/10 text-blue-400 px-2 py-0.5 rounded">FIBER+WIFI</span>
                </div>
                <div className="grid grid-cols-1 gap-2">
                  {networkNodes.map(node => (
                    <div key={node.id} className="p-3 bg-slate-900/50 border border-slate-800 rounded-xl flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <div className={`w-2 h-2 rounded-full ${node.status === 'active' ? 'bg-emerald-500 shadow-[0_0_8px_#10b981]' : node.status === 'relay' ? 'bg-amber-500' : 'bg-rose-500 animate-pulse'}`}></div>
                        <div>
                          <p className="text-[10px] font-black text-slate-200 uppercase">{node.id}</p>
                          <p className="text-[9px] text-slate-500 font-bold">{node.type}</p>
                        </div>
                      </div>
                      <span className="text-[10px] font-mono text-slate-400">{node.signal}%</span>
                    </div>
                  ))}
                </div>
              </section>

              <button 
                onClick={runConnectivitySim}
                disabled={simulationActive}
                className="w-full py-4 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white font-black rounded-2xl shadow-xl shadow-blue-900/20 transition-all flex items-center justify-center gap-2"
              >
                <span>📡</span> RUN DISASTER PLANNING SIM
              </button>
            </div>
          )}

          {activeModule === 'water' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-left duration-300">
              <section className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-xs font-black text-emerald-500 uppercase tracking-widest">Water GPCD Deep Dive</h3>
                  <span className="text-[10px] font-black text-rose-500">185 GPCD</span>
                </div>
                <div className="p-6 bg-slate-900 border border-slate-800 rounded-3xl space-y-6">
                  <p className="text-xs text-slate-400 leading-relaxed font-bold">
                    Investigation suggests high consumption is driven primarily by seasonal landscape irrigation in residential sectors.
                  </p>
                  <div className="space-y-4">
                    {waterCauseData.map(item => (
                      <div key={item.label} className="space-y-1">
                        <div className="flex justify-between text-[10px] font-black uppercase tracking-tighter">
                          <span className="text-slate-300">{item.label}</span>
                          <span className="text-slate-500">{item.value}%</span>
                        </div>
                        <div className="h-2 w-full bg-slate-800 rounded-full overflow-hidden">
                          <div className={`h-full ${item.color}`} style={{ width: `${item.value}%` }}></div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </section>
              <div className="p-4 bg-amber-500/10 border border-amber-500/20 rounded-2xl">
                <p className="text-[10px] font-black text-amber-500 uppercase mb-1">Recommendation</p>
                <p className="text-[11px] text-amber-200 leading-tight">Implement smart irrigation rebates and automated leak detection in Sector 7.</p>
              </div>
            </div>
          )}

          {activeModule === 'traffic' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-left duration-300">
              <section className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-xs font-black text-amber-500 uppercase tracking-widest">Peak Hour Stress Lab</h3>
                  <div className="flex items-baseline gap-1">
                    <span className="text-2xl font-black text-white">{trafficMetric}</span>
                    <span className="text-[10px] font-bold text-slate-500">MIN</span>
                  </div>
                </div>
                <div className="p-6 bg-slate-900 border border-slate-800 rounded-3xl">
                   <div className="flex items-center gap-4 mb-4">
                      <div className="w-12 h-12 bg-amber-500/20 rounded-2xl flex items-center justify-center text-2xl">🚦</div>
                      <div>
                        <p className="text-[10px] font-black text-slate-400 uppercase">Target Reduction</p>
                        <p className="text-xs font-bold text-white">20% Decrease in Gridlock</p>
                      </div>
                   </div>
                   <button 
