import React, { useEffect, useRef, useState } from 'react';
import { GeoLocation } from '../types';

interface MapProps {
  location: GeoLocation;
  name: string;
  isExpanded?: boolean;
}

export const Map: React.FC<MapProps> = ({ location, name, isExpanded }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);

  // Simulated layer visibility states
  const [layers, setLayers] = useState({
    parcels: true,
    utilities: true,
    greenery: true,
    health: true
  });

  useEffect(() => {
    if (mapContainerRef.current && !mapRef.current) {
      // Initialize map
      mapRef.current = (window as any).L.map(mapContainerRef.current, {
        zoomControl: false 
      }).setView([location.lat, location.lng], 15);

      (window as any).L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
      }).addTo(mapRef.current);

      (window as any).L.control.zoom({
        position: 'bottomleft'
      }).addTo(mapRef.current);

      // Core Marker
      (window as any).L.marker([location.lat, location.lng])
        .addTo(mapRef.current)
        .bindPopup(`<b>${name}</b><br/>Digital Twin Core`)
        .openPopup();

      // Simulated Hospital Nodes for QA
      (window as any).L.circle([location.lat + 0.005, location.lng + 0.005], {
        color: 'red',
        fillColor: '#f03',
        fillOpacity: 0.5,
        radius: 100
      }).addTo(mapRef.current).bindPopup('<b>Hospital Node North</b><br/>QA Verified');

      (window as any).L.circle([location.lat - 0.005, location.lng - 0.003], {
        color: 'red',
        fillColor: '#f03',
        fillOpacity: 0.5,
        radius: 100
      }).addTo(mapRef.current).bindPopup('<b>Hospital Node South</b><br/>QA Verified');
    }

    if (mapRef.current) {
      setTimeout(() => {
        mapRef.current.invalidateSize();
        if (isExpanded) {
          mapRef.current.setZoom(17, { animate: true });
        } else {
          mapRef.current.setZoom(15, { animate: true });
        }
      }, 500);
    }
  }, [location, name, isExpanded]);

  const toggleLayer = (layer: keyof typeof layers) => {
    setLayers(prev => ({ ...prev, [layer]: !prev[layer] }));
  };

  return (
    <div className="w-full h-full relative bg-slate-200 transition-all duration-500">
      <div ref={mapContainerRef} className="w-full h-full" />

      <div className="absolute top-4 left-4 z-[1000] flex flex-col gap-2">
        <div className="glass-panel px-4 py-2.5 rounded-2xl text-[10px] font-black text-slate-800 shadow-xl border border-white/60 flex items-center gap-2.5">
          <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.6)]"></span>
          OFFICIAL GIS DATA SOURCE
        </div>
      </div>

      {isExpanded && (
        <div className="absolute bottom-6 right-6 z-[1000] glass-panel p-5 rounded-[2rem] border border-white/60 shadow-2xl animate-in slide-in-from-bottom duration-500 w-[280px]">
          <div className="flex items-center justify-between mb-4">
            <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest">Urban Layer Legend</h4>
            <div className="text-[9px] font-bold text-slate-400 bg-slate-100 px-2 py-0.5 rounded-full">LIVE</div>
          </div>

          <div className="space-y-3">
            <div className={`group flex items-start gap-3 p-2.5 rounded-2xl transition-all cursor-pointer ${layers.parcels ? 'bg-blue-50/50' : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer('parcels')}>
              <div className="w-4 h-4 bg-blue-500/20 border-2 border-blue-500 rounded-md shrink-0 mt-0.5"></div>
              <div>
                <span className="text-[10px] font-black text-slate-800 block mb-0.5 uppercase">Parcels</span>
                <p className="text-[8px] font-medium text-slate-500 leading-tight">Property zoning limits.</p>
              </div>
            </div>

            <div className={`group flex items-start gap-3 p-2.5 rounded-2xl transition-all cursor-pointer ${layers.utilities ? 'bg-rose-50/50' : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer('utilities')}>
              <div className="w-4 h-4 bg-rose-500/20 border-2 border-rose-500 rounded-md shrink-0 mt-0.5"></div>
              <div>
                <span className="text-[10px] font-black text-slate-800 block mb-0.5 uppercase">Utilities</span>
                <p className="text-[8px] font-medium text-slate-500 leading-tight">Sub-surface infrastructure.</p>
              </div>
            </div>

            <div className={`group flex items-start gap-3 p-2.5 rounded-2xl transition-all cursor-pointer ${layers.health ? 'bg-rose-500/10' : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer('health')}>
              <div className="w-4 h-4 bg-rose-600/20 border-2 border-rose-600 rounded-md shrink-0 mt-0.5"></div>
