  const runTrafficMitigation = async () => {
    setSimulationActive(true);
    addLog(`RUNNING TRAFFIC SCENARIO (DENSITY: ${trafficDensity}%, TRANSIT: ${transportAvailability}%)...`);
    await new Promise(r => setTimeout(r, 800));

    // Calculate initial delay based on density
    const baseDelay = 10 + (trafficDensity * 0.1);
    setTrafficMetric(parseFloat(baseDelay.toFixed(1)));
    addLog(`BASELINE DELAY ESTABLISHED: ${baseDelay.toFixed(1)} MIN.`);

    await new Promise(r => setTimeout(r, 800));
    addLog("CALIBRATING SMART SIGNALS & REROUTING ALGORITHMS...");

    // Simulate traffic reduction influenced by public transport availability
    const efficiencyFactor = 0.1 + (transportAvailability * 0.002);
    const targetMetric = baseDelay * (1 - efficiencyFactor);

    let current = baseDelay;
    while (current > targetMetric) {
      current -= 0.3;
      if (current < targetMetric) current = targetMetric;
      setTrafficMetric(parseFloat(current.toFixed(1)));
      await new Promise(r => setTimeout(r, 200));
    }

    addLog("EMERGENCY VEHICLE PREEMPTION PROTOCOL (EVPP) ENGAGED.");
    await new Promise(r => setTimeout(r, 600));

    // Response time calculation
    const baseResponse = 8.5;
    const responseReduction = (efficiencyFactor * 10) + (transportAvailability * 0.02);
    const newResponse = baseResponse - responseReduction;

    addLog("ANALYZING PUBLIC SAFETY RESPONSE IMPACT...");
    await new Promise(r => setTimeout(r, 800));
    addLog(`IMPACT: Response time optimized to ${newResponse.toFixed(1)} min via adaptive transit corridors.`);

    await new Promise(r => setTimeout(r, 600));
    addLog(`SIMULATION SUCCESS: Gridlock reduced by ${((1 - targetMetric/baseDelay)*100).toFixed(0)}%.`);
    setSimulationActive(false);
  };

  return (
    <div className="flex-1 flex flex-col lg:flex-row min-h-0 bg-slate-950 text-slate-200 overflow-hidden">
      {/* Research Sidebar */}
      <aside className="w-full lg:w-[420px] border-r border-slate-800 flex flex-col overflow-hidden">
        <header className="p-6 border-b border-slate-800 bg-slate-900/50">
          <h2 className="text-xl font-black text-white tracking-tight mb-1">GIS Layer Analysis</h2>
          <p className="text-[10px] font-bold text-rose-500 uppercase tracking-[0.2em]">Research Center | {metadata.name}</p>
        </header>

        {/* Module Switcher */}
        <nav className="flex border-b border-slate-800">
          {(['connectivity', 'water', 'traffic'] as AnalysisModule[]).map(mod => (
            <button
              key={mod}
              onClick={() => setActiveModule(mod)}
              className={`flex-1 py-4 text-[10px] font-black uppercase tracking-widest transition-all ${
                activeModule === mod ? 'text-white border-b-2 border-rose-500 bg-slate-900' : 'text-slate-500 hover:text-slate-300'
              }`}
            >
              {mod}
            </button>
          ))}
        </nav>

        <div className="flex-1 overflow-y-auto p-6 space-y-8 scrollbar-thin scrollbar-thumb-slate-800">

          {activeModule === 'connectivity' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-left duration-300">
              <section className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-xs font-black text-blue-500 uppercase tracking-widest">Network QA Verification</h3>
                  <span className="text-[9px] font-bold bg-blue-500/10 text-blue-400 px-2 py-0.5 rounded">FIBER+WIFI</span>
                </div>
                <div className="grid grid-cols-1 gap-2">
                  {networkNodes.map(node => (
                    <div key={node.id} className="p-3 bg-slate-900/50 border border-slate-800 rounded-xl flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <div className={`w-2 h-2 rounded-full ${node.status === 'active' ? 'bg-emerald-500 shadow-[0_0_8px_#10b981]' : node.status === 'relay' ? 'bg-amber-500' : 'bg-rose-500 animate-pulse'}`}></div>
                        <div>
                          <p className="text-[10px] font-black text-slate-200 uppercase">{node.id}</p>
                          <p className="text-[9px] text-slate-500 font-bold">{node.type}</p>
                        </div>
                      </div>
                      <span className="text-[10px] font-mono text-slate-400">{node.signal}%</span>
                    </div>
                  ))}
                </div>
              </section>

              <button 
                onClick={runConnectivitySim}
                disabled={simulationActive}
                className="w-full py-4 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white font-black rounded-2xl shadow-xl shadow-blue-900/20 transition-all flex items-center justify-center gap-2"
              >
                <span>📡</span> RUN DISASTER PLANNING SIM
              </button>
            </div>
          )}

          {activeModule === 'water' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-left duration-300">
              <section className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-xs font-black text-emerald-500 uppercase tracking-widest">Water GPCD Deep Dive</h3>
                  <span className="text-[10px] font-black text-rose-500">185 GPCD</span>
                </div>
                <div className="p-6 bg-slate-900 border border-slate-800 rounded-3xl space-y-6">
                  <p className="text-xs text-slate-400 leading-relaxed font-bold">
                    Investigation suggests high consumption is driven primarily by seasonal landscape irrigation in residential sectors.
                  </p>
                  <div className="space-y-4">
                    {waterCauseData.map(item => (
                      <div key={item.label} className="space-y-1">
                        <div className="flex justify-between text-[10px] font-black uppercase tracking-tighter">
                          <span className="text-slate-300">{item.label}</span>
                          <span className="text-slate-500">{item.value}%</span>
                        </div>
                        <div className="h-2 w-full bg-slate-800 rounded-full overflow-hidden">
                          <div className={`h-full ${item.color}`} style={{ width: `${item.value}%` }}></div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </section>
              <div className="p-4 bg-amber-500/10 border border-amber-500/20 rounded-2xl">
                <p className="text-[10px] font-black text-amber-500 uppercase mb-1">Recommendation</p>
                <p className="text-[11px] text-amber-200 leading-tight">Implement smart irrigation rebates and automated leak detection in Sector 7.</p>
              </div>
            </div>
          )}

          {activeModule === 'traffic' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-left duration-300">
              <section className="space-y-6">
                <div className="flex items-center justify-between">
                  <h3 className="text-xs font-black text-amber-500 uppercase tracking-widest">Scenario Parameters</h3>
                </div>

                <div className="space-y-5 p-5 bg-slate-900 rounded-3xl border border-slate-800">
                  {/* Traffic Density Control */}
                  <div className="space-y-2">
                    <div className="flex justify-between items-center">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Traffic Density</label>
                      <span className="text-xs font-mono text-amber-500 font-bold">{trafficDensity}%</span>
                    </div>
                    <input 
                      type="range" 
                      min="10" max="100" 
                      value={trafficDensity} 
                      onChange={(e) => setTrafficDensity(parseInt(e.target.value))}
                      className="w-full accent-amber-600 bg-slate-800 h-1.5 rounded-full appearance-none cursor-pointer"
                    />
                  </div>

                  {/* Public Transport Control */}
                  <div className="space-y-2">
                    <div className="flex justify-between items-center">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Public Transport</label>
                      <span className="text-xs font-mono text-blue-500 font-bold">{transportAvailability}%</span>
                    </div>
                    <input 
                      type="range" 
                      min="0" max="100" 
                      value={transportAvailability} 
                      onChange={(e) => setTransportAvailability(parseInt(e.target.value))}
                      className="w-full accent-blue-600 bg-slate-800 h-1.5 rounded-full appearance-none cursor-pointer"
                    />
                  </div>
                </div>

                <div className="flex items-center justify-between">
                  <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest">Stress Lab Metrics</h3>
                  <div className="flex items-baseline gap-1">
                    <span className="text-2xl font-black text-white">{trafficMetric}</span>
                    <span className="text-[10px] font-bold text-slate-500">MIN DELAY</span>
                  </div>
                </div>

                <div className="p-6 bg-slate-900 border border-slate-800 rounded-3xl">
                   <div className="flex items-center gap-4 mb-4">
                      <div className="w-12 h-12 bg-amber-500/20 rounded-2xl flex items-center justify-center text-2xl">🚦</div>
                      <div>
                        <p className="text-[10px] font-black text-slate-400 uppercase">Action Protocol</p>
                        <p className="text-xs font-bold text-white">Adaptive Mitigation Simulation</p>
                      </div>
                   </div>
                   <button 
                    onClick={runTrafficMitigation}
                    disabled={simulationActive}
                    className="w-full py-4 bg-amber-600 hover:bg-amber-500 disabled:opacity-50 text-white font-black rounded-2xl shadow-xl transition-all flex items-center justify-center gap-2"
                  >
                    {simulationActive ? 'CALIBRATING...' : '🚀 RUN MITIGATION SIM'}
                  </button>
                </div>
              </section>
            </div>
          )}

          {/* Logs Section */}
          <section className="pt-6 border-t border-slate-800 space-y-4">
            <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Simulation Log Output</h4>
            <div className="h-[250px] bg-slate-950 border border-slate-800 rounded-2xl p-4 font-mono text-[9px] space-y-2 overflow-y-auto">
              {simLogs.length === 0 && <p className="text-slate-700 italic">Standby for input...</p>}
              {simLogs.map((log, i) => (
                <div key={i} className={`leading-relaxed ${
                  log.includes('SUCCESS') || log.includes('COMPLETE') ? 'text-emerald-500' : 
                  log.includes('CRITICAL') || log.includes('EVPP') ? 'text-amber-400' :
                  log.includes('IMPACT') ? 'text-blue-400 font-bold' : 
                  log.includes('CUT') ? 'text-rose-500 animate-pulse' : 'text-slate-400'
                }`}>
                  {log}
                </div>
              ))}
            </div>
          </section>
        </div>
      </aside>

      {/* Dynamic Map Interface */}
      <div className="flex-1 relative overflow-hidden">
        <div className={`absolute inset-0 transition-all duration-1000 ${simulationActive ? 'brightness-[0.3] grayscale-[0.8]' : 'brightness-100'}`}>
          <Map 
            location={metadata.location!} 
            name={`${metadata.name} | GIS Research View`} 
            isExpanded={true}
          />
        </div>

        {/* HUD Data Overlays */}
        <div className="absolute top-8 left-8 z-[1000] flex flex-col gap-4 pointer-events-none">
          <div className="glass-panel px-5 py-3 rounded-2xl border border-white/10 shadow-2xl flex items-center gap-4 bg-slate-900/80 backdrop-blur-xl">
             <div className="w-10 h-10 bg-rose-600/20 rounded-full flex items-center justify-center text-rose-500 animate-pulse">
               🏥
             </div>
             <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Healthcare Node Status</p>
                <p className="text-sm font-bold text-white">Hospital QA Verified</p>
             </div>
          </div>

          <div className="glass-panel px-5 py-3 rounded-2xl border border-white/10 shadow-2xl flex items-center gap-4 bg-slate-900/80 backdrop-blur-xl">
             <div className="w-10 h-10 bg-blue-600/20 rounded-full flex items-center justify-center text-blue-500">
               📶
             </div>
             <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Connectivity Core</p>
                <p className="text-sm font-bold text-white">Route Planning Active</p>
             </div>
          </div>
        </div>

        {simulationActive && (
          <div className="absolute inset-0 z-[2000] flex items-center justify-center pointer-events-none">
            <div className="p-8 rounded-[3rem] border-4 border-rose-500/40 bg-rose-950/20 backdrop-blur-md animate-pulse">
               <h3 className="text-4xl font-black text-rose-500 text-center uppercase tracking-tighter">Stress Test Active</h3>
               <p className="text-rose-400/60 text-center font-bold mt-2">Simulating multi-layer failure and mitigation</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export interface GeoLocation {
  lat: number;
  lng: number;
  displayName: string;
}

export interface MeshNode {
  id: string;
  status: 'active' | 'relay' | 'failing';
  signal: number; // 0-100
  type: 'Static' | 'Mobile' | 'Fog' | 'Fiber' | 'Wi-Fi';
}

export interface TacticalAlert {
  timestamp: string;
  sender: string;
  message: string;
  priority: 'low' | 'high' | 'critical';
}

export interface NeighborhoodBLan {
  name: string;
  nodes: number;
  health: number; // 0-100
  status: 'stable' | 'degraded' | 'isolated';
}

export interface ResidentPing {
  householdId: string;
  neighborhood: string;
  needs: string[];
  powerStatus: 'on' | 'battery' | 'off';
  timestamp: string;
}

export interface TwinMetadata {
  name: string;
  address: string;
  location: GeoLocation | null;
  type: 'City' | 'Community' | 'Farm' | 'Special District';
  officialUrl?: string;
  isEmergencyMode?: boolean;
}

export enum NISTLayer {
  ENERGY = 'Energy',
  WATER = 'Water',
  WASTE = 'Waste',
  TRANSPORTATION = 'Transportation',
  PUBLIC_SAFETY = 'Public Safety',
  HEALTHCARE = 'Healthcare'
}

export interface SmartCityInsight {
  layer: NISTLayer;
  status: 'optimal' | 'warning' | 'critical';
  value: string;
  summary: string;
  recommendations: string[];
}

export type ViewType = 'dashboard' | 'gis-analysis';

export interface DashboardState {
  metadata: TwinMetadata;
  insights: SmartCityInsight[];
  isGenerating: boolean;
  currentView: ViewType;
}

import React, { useState, useEffect } from 'react';
import { TwinMetadata, MeshNode, NISTLayer, NeighborhoodBLan, ResidentPing, TacticalAlert } from '../types';
import { Map } from './Map';

interface GISAnalysisProps {
  metadata: TwinMetadata;
}

type AnalysisModule = 'connectivity' | 'water' | 'traffic' | 'emergency';

export const GISAnalysis: React.FC<GISAnalysisProps> = ({ metadata }) => {
  const [activeModule, setActiveModule] = useState<AnalysisModule>('connectivity');
  const [simulationActive, setSimulationActive] = useState(false);
  const [simLogs, setSimLogs] = useState<string[]>([]);

  // State for Connectivity
  const [networkNodes, setNetworkNodes] = useState<MeshNode[]>([
    { id: 'FIBER-HUB-01', status: 'active', signal: 100, type: 'Fiber' },
    { id: 'WIFI-SECTOR-A', status: 'active', signal: 85, type: 'Wi-Fi' },
    { id: 'HOSPITAL-NODE-NORTH', status: 'active', signal: 95, type: 'Static' }, 
    { id: 'HOSPITAL-NODE-SOUTH', status: 'active', signal: 90, type: 'Static' }, 
  ]);

  // Emergency Module States
  const [neighborhoods, setNeighborhoods] = useState<NeighborhoodBLan[]>([
    { name: 'Calabasas Highlands', nodes: 142, health: 94, status: 'stable' },
    { name: 'Mulholland Heights', nodes: 88, health: 62, status: 'degraded' },
    { name: 'Saratoga Hills', nodes: 215, health: 98, status: 'stable' },
    { name: 'Hidden Hills Gate', nodes: 34, health: 12, status: 'isolated' },
  ]);

  const [residentPings, setResidentPings] = useState<ResidentPing[]>([
    { householdId: 'H-402', neighborhood: 'Saratoga Hills', needs: [], powerStatus: 'on', timestamp: 'Now' },
    { householdId: 'H-912', neighborhood: 'Mulholland Heights', needs: ['Water'], powerStatus: 'battery', timestamp: '2m ago' },
  ]);

  const [utilityAlerts, setUtilityAlerts] = useState<TacticalAlert[]>([
    { timestamp: '10:05', sender: 'SCE Utility', message: 'Transformer 4A Offline. Grid sector 9 entering Stage 1 Load Shedding.', priority: 'high' },
    { timestamp: '10:12', sender: 'LASD Dispatch', message: 'Evacuation corridor Alpha established via Mureau Rd.', priority: 'critical' },
  ]);

  // State for Water Deep Dive
  const [waterCauseData, setWaterCauseData] = useState([
    { label: 'Irrigation Inefficiency', value: 45, color: 'bg-rose-500' },
    { label: 'Aging Infrastructure (Leaks)', value: 30, color: 'bg-amber-500' },
    { label: 'Domestic Consumption', value: 25, color: 'bg-emerald-500' },
  ]);

  // State for Traffic Simulation
  const [trafficMetric, setTrafficMetric] = useState(12.4);
  const [trafficDensity, setTrafficDensity] = useState(70);
  const [transportAvailability, setTransportAvailability] = useState(30);

  const addLog = (msg: string) => {
    setSimLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev].slice(0, 18));
  };

  const runEmergencySync = async () => {
    setSimulationActive(true);
    addLog("POLLING NEIGHBORHOOD B-LAN HUBS...");
    await new Promise(r => setTimeout(r, 1000));
    addLog("INGESTING HOUSEHOLD RESIDENT TELEMETRY...");

    // Simulate some new pings
    const newPing: ResidentPing = {
      householdId: `H-${Math.floor(Math.random() * 900) + 100}`,
      neighborhood: neighborhoods[Math.floor(Math.random() * neighborhoods.length)].name,
      needs: Math.random() > 0.7 ? ['First Aid'] : [],
      powerStatus: Math.random() > 0.5 ? 'battery' : 'off',
      timestamp: 'Just now'
    };
    setResidentPings(prev => [newPing, ...prev].slice(0, 5));

    await new Promise(r => setTimeout(r, 1500));
    addLog("SYNC COMPLETE: 479 HOUSEHOLDS REPORTING VIA MESH.");
    setSimulationActive(false);
  };

  const runConnectivitySim = async () => {
    setSimulationActive(true);
    addLog("INITIATING DISASTER RESILIENCE SIMULATION...");
    await new Promise(r => setTimeout(r, 1500));
    addLog("STAGE 1: POWER GRID DOWN. FAILOVER TO B-LAN BATTERY NODES...");
    setNetworkNodes(prev => prev.map(n => ({ ...n, status: n.type === 'Fiber' ? 'failing' : 'relay', signal: Math.floor(Math.random() * 40) + 10 })));
    await new Promise(r => setTimeout(r, 1500));
    addLog("STAGE 2: FIBER BACKBONE CUT. MESH RELAY PROTOCOL ACTIVE.");
    addLog("HOSPITAL-NODE-NORTH: RE-ROUTING VIA EMERGENCY WI-FI LINK.");
    await new Promise(r => setTimeout(r, 1500));
    addLog("SIMULATION COMPLETE: Connectivity maintained at 45% capacity.");
    setSimulationActive(false);
  };

  const runTrafficMitigation = async () => {
    setSimulationActive(true);
    addLog(`RUNNING TRAFFIC SCENARIO (DENSITY: ${trafficDensity}%, TRANSIT: ${transportAvailability}%)...`);
    await new Promise(r => setTimeout(r, 800));
    const baseDelay = 10 + (trafficDensity * 0.1);
    setTrafficMetric(parseFloat(baseDelay.toFixed(1)));
    addLog(`BASELINE DELAY ESTABLISHED: ${baseDelay.toFixed(1)} MIN.`);
    await new Promise(r => setTimeout(r, 800));
    addLog("CALIBRATING SMART SIGNALS & REROUTING ALGORITHMS...");
    const efficiencyFactor = 0.1 + (transportAvailability * 0.002);
    const targetMetric = baseDelay * (1 - efficiencyFactor);
    let current = baseDelay;
    while (current > targetMetric) {
      current -= 0.3;
      if (current < targetMetric) current = targetMetric;
      setTrafficMetric(parseFloat(current.toFixed(1)));
      await new Promise(r => setTimeout(r, 200));
    }
    addLog("EMERGENCY VEHICLE PREEMPTION PROTOCOL (EVPP) ENGAGED.");
    await new Promise(r => setTimeout(r, 600));
    addLog("ANALYZING PUBLIC SAFETY RESPONSE IMPACT...");
    await new Promise(r => setTimeout(r, 800));
    addLog("SIMULATION SUCCESS: Response metrics optimized.");
    setSimulationActive(false);
  };

  return (
    <div className="flex-1 flex flex-col lg:flex-row min-h-0 bg-slate-950 text-slate-200 overflow-hidden">
      {/* Research Sidebar */}
      <aside className="w-full lg:w-[420px] border-r border-slate-800 flex flex-col overflow-hidden">
        <header className="p-6 border-b border-slate-800 bg-slate-900/50">
          <h2 className="text-xl font-black text-white tracking-tight mb-1">GIS Layer Analysis</h2>
          <p className="text-[10px] font-bold text-rose-500 uppercase tracking-[0.2em]">Research Center | {metadata.name}</p>
        </header>

        {/* Module Switcher */}
        <nav className="flex border-b border-slate-800 overflow-x-auto no-scrollbar">
          {(['connectivity', 'water', 'traffic', 'emergency'] as AnalysisModule[]).map(mod => (
            <button
              key={mod}
              onClick={() => setActiveModule(mod)}
              className={`flex-1 min-w-[100px] py-4 text-[10px] font-black uppercase tracking-widest transition-all ${
                activeModule === mod ? 'text-white border-b-2 border-rose-500 bg-slate-900' : 'text-slate-500 hover:text-slate-300'
              }`}
            >
              {mod}
            </button>
          ))}
        </nav>

        <div className="flex-1 overflow-y-auto p-6 space-y-8 scrollbar-thin scrollbar-thumb-slate-800">

          {activeModule === 'emergency' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-left duration-300">
              <section className="space-y-4">
                <h3 className="text-xs font-black text-rose-500 uppercase tracking-widest">Neighborhood B-lan Pulse</h3>
                <div className="grid grid-cols-1 gap-2">
                  {neighborhoods.map(n => (
                    <div key={n.name} className="p-3 bg-slate-900/50 border border-slate-800 rounded-xl flex flex-col gap-2">
                      <div className="flex justify-between items-center">
                        <span className="text-[10px] font-black text-slate-200 uppercase">{n.name}</span>
                        <span className={`text-[8px] px-1.5 py-0.5 rounded font-black uppercase ${
                          n.status === 'stable' ? 'bg-emerald-500/10 text-emerald-500' : 
                          n.status === 'degraded' ? 'bg-amber-500/10 text-amber-500' : 'bg-rose-500/10 text-rose-500 animate-pulse'
                        }`}>{n.status}</span>
                      </div>
                      <div className="flex items-center gap-3">
                        <div className="flex-1 h-1 bg-slate-800 rounded-full overflow-hidden">
                          <div className={`h-full ${n.health > 70 ? 'bg-emerald-500' : n.health > 30 ? 'bg-amber-500' : 'bg-rose-500'}`} style={{ width: `${n.health}%` }}></div>
                        </div>
                        <span className="text-[9px] font-mono text-slate-500">{n.nodes} nodes</span>
                      </div>
                    </div>
                  ))}
                </div>
              </section>

              <section className="space-y-4">
                <h3 className="text-xs font-black text-blue-500 uppercase tracking-widest">Resident Household Feed</h3>
                <div className="space-y-2 max-h-[160px] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-slate-800">
                  {residentPings.map((p, i) => (
                    <div key={i} className="p-2.5 bg-slate-950 border border-slate-800 rounded-lg text-[9px] flex justify-between items-center">
                      <div>
                        <span className="font-black text-slate-400">{p.householdId}</span>
                        <span className="mx-2 text-slate-600">|</span>
                        <span className="text-slate-500">{p.neighborhood}</span>
                      </div>
                      <div className="flex items-center gap-2">
                        {p.needs.length > 0 && <span className="bg-rose-500/20 text-rose-400 px-1 rounded font-black uppercase">Need: {p.needs[0]}</span>}
                        <span className={`w-1.5 h-1.5 rounded-full ${p.powerStatus === 'on' ? 'bg-emerald-500' : p.powerStatus === 'battery' ? 'bg-amber-500' : 'bg-rose-500'}`}></span>
                      </div>
                    </div>
                  ))}
                </div>
              </section>

              <button 
                onClick={runEmergencySync}
                disabled={simulationActive}
                className="w-full py-4 bg-rose-600 hover:bg-rose-500 disabled:opacity-50 text-white font-black rounded-2xl shadow-xl transition-all flex items-center justify-center gap-2"
              >
