            </div>

            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Spatial Log Output</h4>
            <div className="h-[200px] bg-slate-950 border border-slate-800 rounded-2xl p-4 font-mono text-[9px] space-y-2 overflow-y-auto">
              {simLogs.length === 0 && <p className="text-slate-700 italic">Standby...</p>}
