      </aside>

      {/* Dynamic Map Interface */}
      <div className="flex-1 relative overflow-hidden">
        <div className={`absolute inset-0 transition-all duration-1000 ${simulationActive ? 'brightness-[0.3] grayscale-[0.8]' : 'brightness-100'}`}>
          <Map 
            location={metadata.location!} 
            name={`${metadata.name} | GIS Research View`} 
            isExpanded={true}
          />
        </div>

        {/* HUD Data Overlays */}
        <div className="absolute top-8 left-8 z-[1000] flex flex-col gap-4 pointer-events-none">
          <div className="glass-panel px-5 py-3 rounded-2xl border border-white/10 shadow-2xl flex items-center gap-4 bg-slate-900/80 backdrop-blur-xl">
             <div className="w-10 h-10 bg-rose-600/20 rounded-full flex items-center justify-center text-rose-500 animate-pulse">🏥</div>
             <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Active Sector</p>
                <p className="text-sm font-bold text-white">GIS Core Synchronized</p>
             </div>
          </div>
          <div className="glass-panel px-5 py-3 rounded-2xl border border-white/10 shadow-2xl flex items-center gap-4 bg-slate-900/80 backdrop-blur-xl">
             <div className="w-10 h-10 bg-blue-600/20 rounded-full flex items-center justify-center text-blue-500">📶</div>
             <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Neighborhood Mesh</p>
                <p className="text-sm font-bold text-white">{neighborhoods.filter(n => n.status === 'stable').length} Sectors Optimal</p>
             </div>
