        </div>

        {simulationActive && (
          <div className="absolute inset-0 z-[2000] flex items-center justify-center pointer-events-none">
            <div className="p-8 rounded-[3rem] border-4 border-rose-500/40 bg-rose-950/20 backdrop-blur-md animate-pulse">
               <h3 className="text-4xl font-black text-rose-500 text-center uppercase tracking-tighter">Simulation Active</h3>
               <p className="text-rose-400/60 text-center font-bold mt-2">Updating GIS Layers and Tactical Pulse</p>
