};

import React, { useState, useEffect } from 'react';
import { TwinMetadata, MeshNode, NISTLayer, NeighborhoodBLan, ResidentPing, TacticalAlert } from '../types';
import { Map } from './Map';

interface GISAnalysisProps {
  metadata: TwinMetadata;
}

type AnalysisModule = 'connectivity' | 'water' | 'traffic' | 'emergency';

export const GISAnalysis: React.FC<GISAnalysisProps> = ({ metadata }) => {
  const [activeModule, setActiveModule] = useState<AnalysisModule>('connectivity');
  const [simulationActive, setSimulationActive] = useState(false);
  const [simLogs, setSimLogs] = useState<string[]>([]);

  // Dynamic Neighborhoods derived strictly from City Metadata
  const [neighborhoods, setNeighborhoods] = useState<NeighborhoodBLan[]>([]);

  useEffect(() => {
    // Generate simulated GIS neighborhood sectors based on the provided entity name
    // This ensures no hardcoded cities like Calabasas appear for other users
    const sectors = ['North Quadrant', 'Central Core', 'Highland Sector', 'Western Corridor', 'Eastern District'];
    const generated = sectors.map(s => ({
      name: `${metadata.name} ${s}`,
      nodes: Math.floor(Math.random() * 200) + 50,
      health: Math.floor(Math.random() * 40) + 60,
      status: (Math.random() > 0.8 ? 'degraded' : 'stable') as NeighborhoodBLan['status']
    }));
    setNeighborhoods(generated);
  }, [metadata.name]);

  // State for Connectivity
  const [networkNodes, setNetworkNodes] = useState<MeshNode[]>([
    { id: 'CORE-HUB-01', status: 'active', signal: 100, type: 'Fiber' },
    { id: 'RELAY-SECTOR-ALPHA', status: 'active', signal: 85, type: 'Wi-Fi' },
    { id: 'EMERGENCY-AP-01', status: 'active', signal: 95, type: 'Static' }, 
    { id: 'EMERGENCY-AP-02', status: 'active', signal: 90, type: 'Static' }, 
  ]);

  // Emergency Module States
  const [residentPings, setResidentPings] = useState<ResidentPing[]>([]);
  const [utilityAlerts, setUtilityAlerts] = useState<TacticalAlert[]>([]);

  useEffect(() => {
    if (neighborhoods.length > 0) {
      setResidentPings([
        { householdId: 'HH-772', neighborhood: neighborhoods[0].name, needs: [], powerStatus: 'on', timestamp: 'Now' },
        { householdId: 'HH-104', neighborhood: neighborhoods[1].name, needs: ['First Aid'], powerStatus: 'battery', timestamp: '3m ago' },
        { householdId: 'HH-882', neighborhood: neighborhoods[2].name, needs: [], powerStatus: 'on', timestamp: '5m ago' },
      ]);
      setUtilityAlerts([
        { timestamp: '11:15', sender: 'Regional Grid', message: `Load balancing initiated for ${metadata.name} regional sectors.`, priority: 'high' },
        { timestamp: '11:22', sender: 'Emergency Services', message: `Tactical B-LAN active across all ${metadata.name} quadrants.`, priority: 'critical' },
      ]);
    }
  }, [neighborhoods, metadata.name]);

  // State for Water Deep Dive
  const [waterCauseData, setWaterCauseData] = useState([
    { label: 'Irrigation Pattern', value: 45, color: 'bg-rose-500' },
    { label: 'Network Leakage', value: 30, color: 'bg-amber-500' },
    { label: 'Residential Use', value: 25, color: 'bg-emerald-500' },
  ]);

  // State for Traffic Simulation
  const [trafficMetric, setTrafficMetric] = useState(12.4);
  const [trafficDensity, setTrafficDensity] = useState(70);
  const [transportAvailability, setTransportAvailability] = useState(30);

  const addLog = (msg: string) => {
    setSimLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev].slice(0, 18));
  };

  const runEmergencySync = async () => {
    setSimulationActive(true);
    addLog(`POLLING ${metadata.name.toUpperCase()} TACTICAL HUBS...`);
    await new Promise(r => setTimeout(r, 1000));
    const dataSource = metadata.officialUrl ? `Official GIS: ${metadata.officialUrl}` : "Simulated Spatial Core";
    addLog(`INGESTING HOUSEHOLD DATA FROM ${dataSource}`);

    // Simulate dynamic ingestion of resident data
    const newPing: ResidentPing = {
      householdId: `HH-${Math.floor(Math.random() * 900) + 100}`,
      neighborhood: neighborhoods[Math.floor(Math.random() * neighborhoods.length)].name,
      needs: Math.random() > 0.8 ? ['Medical Supply'] : [],
      powerStatus: Math.random() > 0.5 ? 'battery' : 'on',
      timestamp: 'Just now'
    };
    setResidentPings(prev => [newPing, ...prev].slice(0, 6));

    await new Promise(r => setTimeout(r, 1500));
    addLog(`SYNC COMPLETE: ${neighborhoods.length} Sectors reported via mesh.`);
    setSimulationActive(false);
  };

  const runConnectivitySim = async () => {
    setSimulationActive(true);
    addLog(`INITIATING ${metadata.name.toUpperCase()} FAILOVER TEST...`);
    await new Promise(r => setTimeout(r, 1500));
    addLog("STAGE 1: SIMULATING FIBER DISRUPTION. ACTIVATING B-LAN...");
    setNetworkNodes(prev => prev.map(n => ({ ...n, status: n.type === 'Fiber' ? 'failing' : 'relay', signal: Math.floor(Math.random() * 50) + 20 })));
    await new Promise(r => setTimeout(r, 1500));
    addLog(`RE-ROUTING ${metadata.name} CORE SERVICES VIA NEIGHBORHOOD MESH...`);
    await new Promise(r => setTimeout(r, 1500));
    addLog("SIMULATION COMPLETE: Critical nodes maintained.");
    setSimulationActive(false);
  };

  const runTrafficMitigation = async () => {
    setSimulationActive(true);
    addLog(`CALCULATING TRAFFIC FLOW FOR ${metadata.name}...`);
    await new Promise(r => setTimeout(r, 800));
    const baseDelay = 10 + (trafficDensity * 0.1);
    setTrafficMetric(parseFloat(baseDelay.toFixed(1)));
    addLog(`BASELINE DELAY: ${baseDelay.toFixed(1)} MIN.`);
    await new Promise(r => setTimeout(r, 1000));
    addLog(`OPTIMIZING ARTERIAL SIGNAL PHASING...`);
    const efficiencyFactor = 0.1 + (transportAvailability * 0.002);
    const targetMetric = baseDelay * (1 - efficiencyFactor);
    let current = baseDelay;
    while (current > targetMetric) {
      current -= 0.3;
      if (current < targetMetric) current = targetMetric;
      setTrafficMetric(parseFloat(current.toFixed(1)));
      await new Promise(r => setTimeout(r, 200));
    }
    addLog("EVPP PROTOCOL ACTIVE: Emergency vehicles prioritized.");
    await new Promise(r => setTimeout(r, 800));
    addLog("SUCCESS: Spatial core traffic reduction achieved.");
    setSimulationActive(false);
  };

  return (
    <div className="flex-1 flex flex-col lg:flex-row min-h-0 bg-slate-950 text-slate-200 overflow-hidden">
      {/* Research Sidebar */}
      <aside className="w-full lg:w-[420px] border-r border-slate-800 flex flex-col overflow-hidden">
        <header className="p-6 border-b border-slate-800 bg-slate-900/50">
          <div className="flex items-center justify-between mb-1">
             <h2 className="text-xl font-black text-white tracking-tight">GIS Layer Analysis</h2>
             <span className="text-[8px] font-black bg-blue-500/10 text-blue-400 px-2 py-0.5 rounded border border-blue-500/20">
               {metadata.officialUrl ? "OFFICIAL" : "SIMULATED"}
             </span>
          </div>
          <p className="text-[10px] font-bold text-rose-500 uppercase tracking-[0.2em]">Research Center | {metadata.name}</p>
          {metadata.officialUrl && (
            <p className="text-[9px] text-slate-500 font-mono mt-2 truncate">Source: {metadata.officialUrl}</p>
          )}
        </header>

        {/* Module Switcher */}
        <nav className="flex border-b border-slate-800 overflow-x-auto no-scrollbar">
          {(['connectivity', 'water', 'traffic', 'emergency'] as AnalysisModule[]).map(mod => (
            <button
              key={mod}
              onClick={() => setActiveModule(mod)}
              className={`flex-1 min-w-[100px] py-4 text-[10px] font-black uppercase tracking-widest transition-all ${
                activeModule === mod ? 'text-white border-b-2 border-rose-500 bg-slate-900' : 'text-slate-500 hover:text-slate-300'
              }`}
            >
              {mod}
            </button>
          ))}
        </nav>

        <div className="flex-1 overflow-y-auto p-6 space-y-8 scrollbar-thin scrollbar-thumb-slate-800">

          {activeModule === 'emergency' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-left duration-300">
              <section className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-xs font-black text-rose-500 uppercase tracking-widest">Neighborhood B-LAN Pulse</h3>
                  <span className="text-[9px] text-slate-500 font-bold uppercase">{neighborhoods.length} Sectors Active</span>
                </div>
                <div className="grid grid-cols-1 gap-2">
                  {neighborhoods.map(n => (
                    <div key={n.name} className="p-3 bg-slate-900/50 border border-slate-800 rounded-xl flex flex-col gap-2">
                      <div className="flex justify-between items-center">
                        <span className="text-[10px] font-black text-slate-200 uppercase">{n.name}</span>
                        <span className={`text-[8px] px-1.5 py-0.5 rounded font-black uppercase ${
                          n.status === 'stable' ? 'bg-emerald-500/10 text-emerald-500' : 
                          n.status === 'degraded' ? 'bg-amber-500/10 text-amber-500' : 'bg-rose-500/10 text-rose-500 animate-pulse'
                        }`}>{n.status}</span>
                      </div>
                      <div className="flex items-center gap-3">
                        <div className="flex-1 h-1 bg-slate-800 rounded-full overflow-hidden">
                          <div className={`h-full ${n.health > 70 ? 'bg-emerald-500' : n.health > 30 ? 'bg-amber-500' : 'bg-rose-500'}`} style={{ width: `${n.health}%` }}></div>
                        </div>
                        <span className="text-[9px] font-mono text-slate-500">{n.nodes} nodes</span>
                      </div>
                    </div>
                  ))}
                </div>
              </section>

              <section className="space-y-4">
                <h3 className="text-xs font-black text-blue-500 uppercase tracking-widest">Resident Ping Data (Household)</h3>
                <div className="space-y-2 max-h-[160px] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-slate-800">
                  {residentPings.length === 0 && <p className="text-[10px] text-slate-600 italic">No household data synchronized yet...</p>}
                  {residentPings.map((p, i) => (
                    <div key={i} className="p-2.5 bg-slate-950 border border-slate-800 rounded-lg text-[9px] flex justify-between items-center transition-all hover:border-blue-500/30">
                      <div>
                        <span className="font-black text-slate-400">{p.householdId}</span>
                        <span className="mx-2 text-slate-600">|</span>
                        <span className="text-slate-500">{p.neighborhood}</span>
                      </div>
                      <div className="flex items-center gap-2">
                        {p.needs.length > 0 && <span className="bg-rose-500/20 text-rose-400 px-1 rounded font-black uppercase">Need: {p.needs[0]}</span>}
                        <span className={`w-1.5 h-1.5 rounded-full ${p.powerStatus === 'on' ? 'bg-emerald-500' : p.powerStatus === 'battery' ? 'bg-amber-500' : 'bg-rose-500'}`}></span>
                      </div>
                    </div>
                  ))}
                </div>
              </section>

              <button 
                onClick={runEmergencySync}
                disabled={simulationActive}
                className="w-full py-4 bg-rose-600 hover:bg-rose-500 disabled:opacity-50 text-white font-black rounded-2xl shadow-xl transition-all flex items-center justify-center gap-2"
              >
                <span>📡</span> COLLECT B-LAN TACTICAL DATA
              </button>
            </div>
          )}

          {activeModule === 'connectivity' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-left duration-300">
              <section className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-xs font-black text-blue-500 uppercase tracking-widest">Network Verification</h3>
                  <span className="text-[9px] font-bold bg-blue-500/10 text-blue-400 px-2 py-0.5 rounded">HYBRID TOPOLOGY</span>
                </div>
                <div className="grid grid-cols-1 gap-2">
                  {networkNodes.map(node => (
                    <div key={node.id} className="p-3 bg-slate-900/50 border border-slate-800 rounded-xl flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <div className={`w-2 h-2 rounded-full ${node.status === 'active' ? 'bg-emerald-500 shadow-[0_0_8px_#10b981]' : node.status === 'relay' ? 'bg-amber-500' : 'bg-rose-500 animate-pulse'}`}></div>
                        <div>
                          <p className="text-[10px] font-black text-slate-200 uppercase">{node.id}</p>
                          <p className="text-[9px] text-slate-500 font-bold">{node.type}</p>
                        </div>
                      </div>
                      <span className="text-[10px] font-mono text-slate-400">{node.signal}%</span>
                    </div>
                  ))}
                </div>
              </section>

              <button 
                onClick={runConnectivitySim}
                disabled={simulationActive}
                className="w-full py-4 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white font-black rounded-2xl shadow-xl transition-all flex items-center justify-center gap-2"
              >
                <span>📡</span> RUN INFRASTRUCTURE STRESS TEST
              </button>
            </div>
          )}

          {activeModule === 'water' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-left duration-300">
              <section className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-xs font-black text-emerald-500 uppercase tracking-widest">Utility Consumption</h3>
                  <span className="text-[10px] font-black text-rose-500">Live GIS Data</span>
                </div>
                <div className="p-6 bg-slate-900 border border-slate-800 rounded-3xl space-y-6">
                  <p className="text-xs text-slate-400 leading-relaxed font-bold">
                    Spatial analysis for {metadata.name} identifies localized consumption surges. Data is calibrated against portal historical metrics.
                  </p>
                  <div className="space-y-4">
                    {waterCauseData.map(item => (
                      <div key={item.label} className="space-y-1">
                        <div className="flex justify-between text-[10px] font-black uppercase tracking-tighter">
                          <span className="text-slate-300">{item.label}</span>
                          <span className="text-slate-500">{item.value}%</span>
                        </div>
                        <div className="h-2 w-full bg-slate-800 rounded-full overflow-hidden">
                          <div className={`h-full ${item.color}`} style={{ width: `${item.value}%` }}></div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </section>
            </div>
          )}

          {activeModule === 'traffic' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-left duration-300">
              <section className="space-y-6">
                <div className="space-y-5 p-5 bg-slate-900 rounded-3xl border border-slate-800">
                  <div className="space-y-2">
                    <div className="flex justify-between items-center">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Traffic Density</label>
                      <span className="text-xs font-mono text-amber-500 font-bold">{trafficDensity}%</span>
                    </div>
                    <input type="range" min="10" max="100" value={trafficDensity} onChange={(e) => setTrafficDensity(parseInt(e.target.value))} className="w-full accent-amber-600 bg-slate-800 h-1.5 rounded-full appearance-none cursor-pointer" />
                  </div>
                  <div className="space-y-2">
                    <div className="flex justify-between items-center">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Transit Availability</label>
                      <span className="text-xs font-mono text-blue-500 font-bold">{transportAvailability}%</span>
                    </div>
                    <input type="range" min="0" max="100" value={transportAvailability} onChange={(e) => setTransportAvailability(parseInt(e.target.value))} className="w-full accent-blue-600 bg-slate-800 h-1.5 rounded-full appearance-none cursor-pointer" />
                  </div>
                </div>
                <div className="flex items-center justify-between">
                  <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest">Simulation Metrics</h3>
                  <div className="flex items-baseline gap-1">
                    <span className="text-2xl font-black text-white">{trafficMetric}</span>
                    <span className="text-[10px] font-bold text-slate-500">MIN DELAY</span>
                  </div>
                </div>
                <button onClick={runTrafficMitigation} disabled={simulationActive} className="w-full py-4 bg-amber-600 hover:bg-amber-500 disabled:opacity-50 text-white font-black rounded-2xl shadow-xl transition-all flex items-center justify-center gap-2">
                  {simulationActive ? 'SYNCHRONIZING...' : '🚀 RUN MITIGATION SIM'}
                </button>
              </section>
            </div>
          )}

          {/* Logs & Utility Alerts */}
          <section className="pt-6 border-t border-slate-800 space-y-4">
            <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Emergency & Utility Stream</h4>
            <div className="space-y-2 mb-4">
              {utilityAlerts.map((a, i) => (
                <div key={i} className={`p-3 rounded-xl border-l-4 text-[10px] font-bold ${a.priority === 'critical' ? 'bg-rose-500/10 border-rose-600 text-rose-200' : 'bg-amber-500/10 border-amber-600 text-amber-200'}`}>
                  <span className="block text-[8px] opacity-60 uppercase mb-1">{a.sender} • {a.timestamp}</span>
                  {a.message}
                </div>
              ))}
            </div>

            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Digital Twin Logs</h4>
            <div className="h-[200px] bg-slate-950 border border-slate-800 rounded-2xl p-4 font-mono text-[9px] space-y-2 overflow-y-auto">
              {simLogs.length === 0 && <p className="text-slate-700 italic">Standby for simulation data...</p>}
              {simLogs.map((log, i) => (
                <div key={i} className={`leading-relaxed ${
                  log.includes('SUCCESS') || log.includes('COMPLETE') ? 'text-emerald-500' : 
                  log.includes('CRITICAL') || log.includes('EMERGENCY') || log.includes('TACTICAL') ? 'text-amber-400 font-bold' :
                  log.includes('INGESTING') || log.includes('SOURCE') ? 'text-blue-400' : 'text-slate-400'
                }`}>
                  {log}
                </div>
              ))}
            </div>
          </section>
        </div>
      </aside>

      {/* Dynamic Map Interface */}
      <div className="flex-1 relative overflow-hidden">
        <div className={`absolute inset-0 transition-all duration-1000 ${simulationActive ? 'brightness-[0.3] grayscale-[0.8]' : 'brightness-100'}`}>
          <Map 
            location={metadata.location!} 
            name={`${metadata.name} | GIS Tactical View`} 
            isExpanded={true}
          />
        </div>

        {/* HUD Data Overlays */}
        <div className="absolute top-8 left-8 z-[1000] flex flex-col gap-4 pointer-events-none">
          <div className="glass-panel px-5 py-3 rounded-2xl border border-white/10 shadow-2xl flex items-center gap-4 bg-slate-900/80 backdrop-blur-xl">
             <div className="w-10 h-10 bg-rose-600/20 rounded-full flex items-center justify-center text-rose-500 animate-pulse">🏛️</div>
             <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Regional Core</p>
                <p className="text-sm font-bold text-white">GIS Integrated</p>
             </div>
          </div>
          <div className="glass-panel px-5 py-3 rounded-2xl border border-white/10 shadow-2xl flex items-center gap-4 bg-slate-900/80 backdrop-blur-xl">
             <div className="w-10 h-10 bg-blue-600/20 rounded-full flex items-center justify-center text-blue-500">📶</div>
