import React, { useState } from 'react';
import { TwinMetadata, GISLayerEndpoints } from '../types';

interface OnboardingProps {
  onComplete: (metadata: TwinMetadata) => void;
}

export const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [formData, setFormData] = useState({
    name: '',
    address: '',
    type: 'City' as TwinMetadata['type'],
    officialUrl: ''
  });
  const [gisLayers, setGisLayers] = useState<GISLayerEndpoints>({
    parcels: '',
    utilities: '',
    infrastructure: '',
    safety: ''
  });
  const [tempLocation, setTempLocation] = useState<TwinMetadata['location']>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleStep1Submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    try {
      const encodedAddress = encodeURIComponent(formData.address);
      const response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodedAddress}&limit=1`);
      const data = await response.json();

      if (data && data.length > 0) {
        setTempLocation({
          lat: parseFloat(data[0].lat),
          lng: parseFloat(data[0].lon),
          displayName: data[0].display_name
        });
        setStep(2);
      } else {
        setError("Location not found. Try a street address or city name.");
      }
    } catch (err) {
      setError("Connectivity issue. Please check your network.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleStep2Submit = (e: React.FormEvent) => {
    e.preventDefault();
    setStep(3);
  };

  const handleFinalSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onComplete({
      name: formData.name,
      address: formData.address,
      type: formData.type,
      location: tempLocation,
      officialUrl: formData.officialUrl,
      gisLayers: gisLayers,
      isEmergencyMode: false
    });
  };

  const handleCIMLogin = () => {
    onComplete({
      name: 'Emergency Command Center',
      address: 'Classified / Backup B-lan',
      type: 'Special District',
      location: tempLocation || { lat: 0, lng: 0, displayName: 'Emergency Sector' },
      officialUrl: '',
      isEmergencyMode: true
    });
  };

  if (step === 3) {
    return (
      <div className="flex-1 flex items-center justify-center p-4 sm:p-6 lg:p-12">
        <div className="w-full max-w-2xl bg-white rounded-[2.5rem] shadow-2xl shadow-slate-200/50 border border-slate-100 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="p-8 sm:p-12 text-center bg-emerald-50/50 border-b border-emerald-100">
            <div className="inline-flex items-center justify-center w-14 h-14 bg-emerald-600 text-white rounded-[1.5rem] mb-6 shadow-lg rotate-3">
              <span className="text-2xl">🗺️</span>
            </div>
            <h2 className="text-3xl font-black text-slate-900 mb-2">Configure GIS Layers</h2>
            <p className="text-sm sm:text-base text-slate-500 max-w-md mx-auto">
              Provide specific spatial data endpoints for your digital twin to enable precise urban modeling.
            </p>
          </div>

          <form onSubmit={handleFinalSubmit} className="p-8 sm:p-12 space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {[
                { label: 'Parcel GIS URL', key: 'parcels', placeholder: 'REST/WFS Endpoint', icon: '📦' },
                { label: 'Utilities Layer', key: 'utilities', placeholder: 'Water/Electric Grid', icon: '⚡' },
                { label: 'Infrastructure', key: 'infrastructure', placeholder: 'Roads/Bridges', icon: '🛣️' },
                { label: 'Public Safety', key: 'safety', placeholder: 'Emergency Sectors', icon: '🛡️' }
              ].map((layer) => (
                <div key={layer.key} className="space-y-1.5">
                  <label className="flex items-center gap-2 text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">
                    <span>{layer.icon}</span> {layer.label}
                  </label>
                  <input
                    type="url"
                    className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 transition-all outline-none text-sm placeholder:text-slate-400"
                    placeholder={layer.placeholder}
                    value={(gisLayers as any)[layer.key]}
                    onChange={(e) => setGisLayers({ ...gisLayers, [layer.key]: e.target.value })}
                  />
                </div>
              ))}
            </div>

            <div className="pt-4 flex flex-col sm:flex-row gap-4">
              <button
                type="button"
                onClick={() => setStep(2)}
                className="flex-1 px-8 py-5 border-2 border-slate-100 text-slate-500 font-black rounded-2xl hover:bg-slate-50 transition-all active:scale-95 uppercase text-xs tracking-widest"
              >
                Back
              </button>
              <button
                type="submit"
                className="flex-[2] bg-slate-900 text-white font-black py-5 rounded-2xl shadow-2xl shadow-slate-900/20 transition-all active:scale-[0.97] hover:bg-slate-800 uppercase text-xs tracking-[0.2em]"
              >
                Launch Digital Twin
              </button>
            </div>
          </form>
        </div>
      </div>
    );
  }

  if (step === 2) {
    return (
      <div className="flex-1 flex items-center justify-center p-4 sm:p-6 lg:p-12">
        <div className="w-full max-w-xl bg-white rounded-3xl shadow-2xl shadow-slate-200/50 border border-slate-100 overflow-hidden transition-all animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="p-6 sm:p-10 text-center bg-blue-50/50 border-b border-blue-100">
            <div className="inline-flex items-center justify-center w-12 h-12 bg-blue-600 text-white rounded-full mb-4 shadow-lg">
              <span className="text-xl">🔗</span>
            </div>
            <h2 className="text-2xl sm:text-3xl font-extrabold text-slate-900 mb-2">Connect Resources</h2>
            <p className="text-sm sm:text-base text-slate-500 max-w-sm mx-auto">
              Spatial core initialized for <b>{formData.name}</b>. Now, provide your city's official portal URL.
            </p>
          </div>

          <form onSubmit={handleStep2Submit} className="p-6 sm:p-10 space-y-6">
            <div className="space-y-1">
              <label className="block text-xs sm:text-sm font-bold text-slate-600 uppercase tracking-wider ml-1">Official City/District Website</label>
              <div className="relative">
                <input
                  type="url"
                  required
                  className="w-full pl-11 pr-4 py-3 sm:py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 transition-all outline-none text-base touch-manipulation"
                  placeholder="https://www.cityname.gov"
                  value={formData.officialUrl}
                  onChange={(e) => setFormData({ ...formData, officialUrl: e.target.value })}
                />
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">🌐</span>
              </div>
            </div>

            <div className="flex flex-col sm:flex-row gap-3">
              <button
                type="button"
                onClick={() => setStep(1)}
                className="flex-1 px-4 py-4 sm:py-5 border-2 border-slate-100 text-slate-500 font-bold rounded-2xl hover:bg-slate-50 transition-all active:scale-95"
              >
                Back
              </button>
              <button
                type="submit"
                className="flex-[2] bg-blue-600 text-white font-bold py-4 sm:py-5 rounded-2xl shadow-xl shadow-blue-200 transition-all active:scale-[0.97] hover:bg-blue-700"
              >
                Next: GIS Layers
              </button>
            </div>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex-1 flex items-center justify-center p-4 sm:p-6 lg:p-12">
      <div className="w-full max-w-xl flex flex-col gap-6">
        <div className="bg-white rounded-3xl shadow-2xl shadow-slate-200/50 border border-slate-100 overflow-hidden transition-all">
          <div className="p-6 sm:p-10 text-center bg-slate-50/50 border-b border-slate-100">
            <h2 className="text-2xl sm:text-3xl font-extrabold text-slate-900 mb-2">Initialize Digital Twin</h2>
            <p className="text-sm sm:text-base text-slate-500 max-w-sm mx-auto">
              Connect your physical entity to our spatial simulation engine using NIST standards.
            </p>
          </div>

          <form onSubmit={handleStep1Submit} className="p-6 sm:p-10 space-y-6">
            <div className="space-y-1">
              <label className="block text-xs sm:text-sm font-bold text-slate-600 uppercase tracking-wider ml-1">Entity Name</label>
              <input
                type="text"
                required
                className="w-full px-4 py-3 sm:py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 transition-all outline-none text-base touch-manipulation"
                placeholder="e.g., Downtown Metro Core"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
              <div className="space-y-1">
                <label className="block text-xs sm:text-sm font-bold text-slate-600 uppercase tracking-wider ml-1">Category</label>
                <select
                  className="w-full px-4 py-3 sm:py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 outline-none text-base appearance-none cursor-pointer"
                  value={formData.type}
                  onChange={(e) => setFormData({ ...formData, type: e.target.value as any })}
                >
                  <option value="City">Municipality</option>
                  <option value="Community">Community</option>
                  <option value="Farm">Agricultural</option>
                  <option value="Special District">Utility District</option>
                </select>
              </div>

              <div className="space-y-1">
                <label className="block text-xs sm:text-sm font-bold text-slate-600 uppercase tracking-wider ml-1">Official Address</label>
                <input
                  type="text"
                  required
                  className="w-full px-4 py-3 sm:py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 transition-all outline-none text-base touch-manipulation"
                  placeholder="City, State or Country"
                  value={formData.address}
                  onChange={(e) => setFormData({ ...formData, address: e.target.value })}
                />
              </div>
            </div>

            {error && (
              <div className="flex items-center gap-3 p-4 bg-rose-50 border border-rose-100 text-rose-700 rounded-2xl text-sm font-medium animate-pulse">
                <span>⚠️</span> {error}
              </div>
            )}

            <button
              type="submit"
              disabled={isLoading}
              className="group relative w-full bg-slate-900 text-white font-bold py-4 sm:py-5 rounded-2xl shadow-xl shadow-slate-200 transition-all active:scale-[0.97] hover:bg-slate-800 disabled:opacity-50 overflow-hidden"
            >
              <div className="flex items-center justify-center gap-3">
                {isLoading ? (
                  <>
                    <svg className="animate-spin h-5 w-5 text-white" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    <span>Calibrating GIS...</span>
                  </>
                ) : (
                  <>
                    <span>Next: Configure Links</span>
                    <span className="transition-transform group-hover:translate-x-1">→</span>
                  </>
                )}
              </div>
            </button>
          </form>
        </div>

        {/* Tactical CIM Login Option */}
        <div className="bg-slate-900 text-white p-6 rounded-3xl border border-slate-800 shadow-xl flex flex-col sm:flex-row items-center justify-between gap-6 transition-all hover:border-rose-500/30 group">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-rose-600 rounded-xl flex items-center justify-center text-xl shadow-lg group-hover:rotate-12 transition-transform">
              📡
            </div>
            <div>
              <p className="text-xs font-black text-rose-500 uppercase tracking-widest mb-1">Backup B-lan</p>
              <h4 className="text-sm font-bold text-slate-100">Emergency Command & Control</h4>
            </div>
          </div>
          <button 
            onClick={handleCIMLogin}
            className="w-full sm:w-auto px-6 py-3 bg-rose-600 hover:bg-rose-700 text-white text-xs font-black rounded-xl transition-all shadow-lg active:scale-95 uppercase tracking-tighter"
          >
            Log in with CIM
          </button>
        </div>
      </div>
    </div>
  );
};

