import React, { useState, useEffect, useCallback } from 'react';
import { Layout } from './components/Layout';
import { Onboarding } from './components/Onboarding';
import { Dashboard } from './components/Dashboard';
import { GISAnalysis } from './components/GISAnalysis';
import { AdminSettings } from './components/AdminSettings';
import { TwinMetadata, SmartCityInsight, ViewType } from './types';
import { generateDigitalTwinInsights } from './services/geminiService';

const App: React.FC = () => {
  const [metadata, setMetadata] = useState<TwinMetadata | null>(null);
  const [insights, setInsights] = useState<SmartCityInsight[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const fetchInsights = useCallback(async (data: TwinMetadata) => {
    setIsLoading(true);
    try {
      const results = await generateDigitalTwinInsights(data);
      setInsights(results);
    } catch (err) {
      console.error("Failed to load twin insights", err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleOnboardingComplete = (data: TwinMetadata) => {
    setMetadata(data);
    fetchInsights(data);
  };

  const handleRefresh = () => {
    if (metadata) fetchInsights(metadata);
  };

  return (
    <Layout 
      currentView={currentView} 
      onViewChange={setCurrentView} 
      isMetadataSet={!!metadata}
    >
      {currentView === 'admin' ? (
        <AdminSettings metadata={metadata} />
      ) : !metadata ? (
        <Onboarding onComplete={handleOnboardingComplete} />
      ) : currentView === 'dashboard' ? (
        <Dashboard 
          metadata={metadata} 
          insights={insights} 
          isLoading={isLoading} 
          onRefresh={handleRefresh}
        />
      ) : (
        <GISAnalysis metadata={metadata} />
      )}
    </Layout>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { TwinMetadata, SmartCityInsight, BranchSuggestion } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateDigitalTwinInsights = async (metadata: TwinMetadata): Promise<SmartCityInsight[]> => {
  const prompt = `
    Analyze the following entity for a Digital Twin application based on the NIST Smart Cities framework.
    Entity Name: ${metadata.name}
    Address: ${metadata.address}
    Type: ${metadata.type}
    Location: ${metadata.location?.lat}, ${metadata.location?.lng}
    Official Portal: ${metadata.officialUrl || 'Not provided'}

    Provide detailed, realistic (but simulated) data insights for the following layers:
    - Energy
    - Water
    - Waste
    - Transportation
    - Public Safety
    - Healthcare

    If an Official Portal is provided, tailor your analysis to typical data found on that city's/district's portal.
    For each layer, provide a status (optimal, warning, critical), a current value/metric (use units), a summary, and 2 key recommendations.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              layer: { type: Type.STRING },
              status: { type: Type.STRING },
              value: { type: Type.STRING },
              summary: { type: Type.STRING },
              recommendations: {
                type: Type.ARRAY,
                items: { type: Type.STRING }
              }
            },
            required: ["layer", "status", "value", "summary", "recommendations"]
          }
        }
      }
    });

    const results = JSON.parse(response.text || "[]");
    return results as SmartCityInsight[];
  } catch (error) {
    console.error("Error generating twin insights:", error);
    throw error;
  }
};

