import React, { useState, useEffect, useCallback } from 'react';
import { Layout } from './components/Layout';
import { Onboarding } from './components/Onboarding';
import { Dashboard } from './components/Dashboard';
import { GISAnalysis } from './components/GISAnalysis';
import { AdminSettings } from './components/AdminSettings';
import { Documentation } from './components/Documentation';
import { TwinMetadata, SmartCityInsight, ViewType } from './types';
import { generateDigitalTwinInsights } from './services/geminiService';

const App: React.FC = () => {
  const [metadata, setMetadata] = useState<TwinMetadata | null>(null);
  const [insights, setInsights] = useState<SmartCityInsight[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const fetchInsights = useCallback(async (data: TwinMetadata) => {
    setIsLoading(true);
    try {
      const results = await generateDigitalTwinInsights(data);
      setInsights(results);
    } catch (err) {
      console.error("Failed to load twin insights", err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleOnboardingComplete = (data: TwinMetadata) => {
    setMetadata(data);
    fetchInsights(data);
  };

  const handleRefresh = () => {
    if (metadata) fetchInsights(metadata);
  };

  const renderContent = () => {
    if (currentView === 'documentation') {
      return <Documentation />;
    }

    if (currentView === 'admin') {
      return <AdminSettings metadata={metadata} />;
    }

    if (!metadata) {
      return <Onboarding onComplete={handleOnboardingComplete} />;
    }

    switch (currentView) {
      case 'dashboard':
        return (
          <Dashboard 
            metadata={metadata} 
            insights={insights} 
            isLoading={isLoading} 
            onRefresh={handleRefresh}
          />
        );
      case 'gis-analysis':
        return <GISAnalysis metadata={metadata} />;
      default:
        return null;
    }
  };

  return (
    <Layout 
      currentView={currentView} 
      onViewChange={setCurrentView} 
      isMetadataSet={!!metadata}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';
import { GeoLocation } from '../types';

interface MapProps {
  location: GeoLocation;
  name: string;
  isExpanded?: boolean;
}

export const Map: React.FC<MapProps> = ({ location, name, isExpanded }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const [streetViewCoords, setStreetViewCoords] = useState<{lat: number, lng: number} | null>(null);

  // Simulated layer visibility states
  const [layers, setLayers] = useState({
    parcels: true,
    utilities: true,
    greenery: true,
    health: true,
    households: true
  });

  useEffect(() => {
    if (mapContainerRef.current && !mapRef.current) {
      // Initialize map
      mapRef.current = (window as any).L.map(mapContainerRef.current, {
        zoomControl: false 
      }).setView([location.lat, location.lng], 15);

      (window as any).L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
      }).addTo(mapRef.current);

      (window as any).L.control.zoom({
        position: 'bottomleft'
      }).addTo(mapRef.current);

      const addMarkerWithStreetView = (pos: [number, number], title: string, subtitle: string) => {
        const marker = (window as any).L.marker(pos).addTo(mapRef.current);
        const popupContent = document.createElement('div');
        popupContent.className = 'p-1';
        popupContent.innerHTML = `
          <div class="mb-2">
            <b class="text-slate-900 block text-sm">${title}</b>
            <span class="text-slate-500 text-[10px] font-bold uppercase">${subtitle}</span>
          </div>
          <button class="street-view-btn w-full bg-blue-600 text-white text-[10px] font-black py-2 rounded-lg hover:bg-blue-700 transition-colors uppercase tracking-widest">
            Street View
          </button>
        `;

        const btn = popupContent.querySelector('.street-view-btn');
        btn?.addEventListener('click', () => {
          setStreetViewCoords({ lat: pos[0], lng: pos[1] });
          marker.closePopup();
        });

        marker.bindPopup(popupContent);
      };

      // Core Marker
      addMarkerWithStreetView([location.lat, location.lng], name, 'Digital Twin Core');

      // Simulated Infrastructure Nodes
      addMarkerWithStreetView([location.lat + 0.005, location.lng + 0.005], `${name} Health Alpha`, 'Primary Health Node');
      addMarkerWithStreetView([location.lat - 0.005, location.lng - 0.003], `${name} Health Beta`, 'Secondary Health Node');

      // Household Pings (Simulated)
      const pings: [number, number][] = [
        [location.lat + 0.002, location.lng + 0.002],
        [location.lat - 0.002, location.lng + 0.004],
        [location.lat + 0.003, location.lng - 0.001],
      ];
      pings.forEach((pos, i) => {
        addMarkerWithStreetView(pos, `Relay #${i+102}`, 'Resident B-LAN Relay');
      });
    }

    if (mapRef.current) {
      setTimeout(() => {
        mapRef.current.invalidateSize();
        if (isExpanded) {
          mapRef.current.setZoom(17, { animate: true });
        } else {
          mapRef.current.setZoom(15, { animate: true });
        }
      }, 500);
    }
  }, [location, name, isExpanded]);

  const toggleLayer = (layer: keyof typeof layers) => {
    setLayers(prev => ({ ...prev, [layer]: !prev[layer] }));
  };

  return (
    <div className="w-full h-full relative bg-slate-200 transition-all duration-500">
      <div ref={mapContainerRef} className="w-full h-full" />

      {/* HUD Overlays */}
      <div className="absolute top-4 left-4 z-[1000] flex flex-col gap-2 pointer-events-none">
        <div className="glass-panel px-4 py-2.5 rounded-2xl text-[10px] font-black text-slate-800 shadow-xl border border-white/60 flex items-center gap-2.5 pointer-events-auto">
          <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.6)]"></span>
          OFFICIAL GIS DATA SOURCE
        </div>
      </div>

      {/* Street View Embed Overlay */}
      {streetViewCoords && (
        <div className="absolute inset-0 z-[3000] bg-slate-900 animate-in fade-in zoom-in-95 duration-300">
          <header className="absolute top-4 left-4 right-4 z-[3100] flex justify-between items-center px-6 py-3 bg-white/90 backdrop-blur-md rounded-2xl border border-white/50 shadow-2xl">
            <div>
              <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Spatial Immersion</p>
              <h4 className="text-xs font-bold text-slate-900">Street View Analysis Mode</h4>
            </div>
            <button 
              onClick={() => setStreetViewCoords(null)}
              className="w-8 h-8 flex items-center justify-center bg-slate-100 hover:bg-slate-200 text-slate-900 rounded-full font-black text-sm transition-all"
            >
              ✕
            </button>
          </header>

          <iframe
            className="w-full h-full border-0"
            loading="lazy"
            allowFullScreen
            src={`https://www.google.com/maps/embed/v1/streetview?key=${process.env.API_KEY}&location=${streetViewCoords.lat},${streetViewCoords.lng}&heading=210&pitch=10&fov=35`}
          ></iframe>

          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-[3100] px-4 py-2 bg-slate-900/80 backdrop-blur-md border border-slate-700 rounded-xl text-[9px] font-mono text-slate-400">
            LAT: {streetViewCoords.lat.toFixed(6)} | LNG: {streetViewCoords.lng.toFixed(6)}
          </div>
        </div>
      )}

      {isExpanded && !streetViewCoords && (
        <div className="absolute bottom-6 right-6 z-[1000] glass-panel p-5 rounded-[2rem] border border-white/60 shadow-2xl animate-in slide-in-from-bottom duration-500 w-[280px]">
          <div className="flex items-center justify-between mb-4">
            <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest">Urban Layer Legend</h4>
            <div className="text-[9px] font-bold text-slate-400 bg-slate-100 px-2 py-0.5 rounded-full uppercase">Live Feed</div>
          </div>

          <div className="space-y-3">
            <div className={`group flex items-start gap-3 p-2.5 rounded-2xl transition-all cursor-pointer ${layers.parcels ? 'bg-blue-50/50' : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer('parcels')}>
              <div className="w-4 h-4 bg-blue-500/20 border-2 border-blue-500 rounded-md shrink-0 mt-0.5"></div>
              <div>
                <span className="text-[10px] font-black text-slate-800 block mb-0.5 uppercase">Parcels</span>
              </div>
            </div>

            <div className={`group flex items-start gap-3 p-2.5 rounded-2xl transition-all cursor-pointer ${layers.health ? 'bg-rose-500/10' : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer('health')}>
              <div className="w-4 h-4 bg-rose-600/20 border-2 border-rose-600 rounded-md shrink-0 mt-0.5"></div>
              <div>
                <span className="text-[10px] font-black text-slate-800 block mb-0.5 uppercase">Health Nodes</span>
              </div>
            </div>

            <div className={`group flex items-start gap-3 p-2.5 rounded-2xl transition-all cursor-pointer ${layers.households ? 'bg-blue-600/10' : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer('households')}>
              <div className="w-4 h-4 bg-blue-600/20 border-2 border-blue-600 rounded-md shrink-0 mt-0.5"></div>
              <div>
                <span className="text-[10px] font-black text-slate-800 block mb-0.5 uppercase">Resident B-LAN</span>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

