                  onChange={(e) => setUsername(e.target.value)}
                  className={`w-full px-6 py-4 bg-slate-950 border rounded-2xl text-white outline-none transition-all ${loginError ? 'border-rose-500 animate-shake' : 'border-slate-800 focus:border-rose-500'}`}
                  placeholder="username"
                  required
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Access Token</label>
