                  type="password" 
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className={`w-full px-6 py-4 bg-slate-950 border rounded-2xl text-white outline-none transition-all ${loginError ? 'border-rose-500 animate-shake' : 'border-slate-800 focus:border-rose-500'}`}
                  placeholder="••••••••••••"
                  required
                />
              </div>

              <button className="w-full py-4 bg-rose-600 hover:bg-rose-500 text-white font-black rounded-2xl shadow-xl shadow-rose-950/20 transition-all active:scale-95 mt-4 flex items-center justify-center gap-2">
                INITIATE A-LAN HANDSHAKE
              </button>

              {loginError && (
                <p className="text-rose-500 text-[10px] font-black uppercase text-center mt-2 animate-pulse">Connection Failed: Invalid Node Credentials</p>
              )}
            </form>
