import React, { useEffect, useRef, useState } from 'react';
import { GeoLocation } from '../types';

interface MapProps {
  location: GeoLocation;
  name: string;
  isExpanded?: boolean;
}

interface WeatherInfo {
  temp: number;
  windSpeed: number;
  conditionCode: number;
  conditionText: string;
}

export const Map: React.FC<MapProps> = ({ location, name, isExpanded }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const radarLayerRef = useRef<any>(null);
  const [streetViewCoords, setStreetViewCoords] = useState<{lat: number, lng: number} | null>(null);
  const [weatherInfo, setWeatherInfo] = useState<WeatherInfo | null>(null);

  // Simulated and real layer visibility states
  const [layers, setLayers] = useState({
    parcels: true,
    utilities: true,
    greenery: true,
    health: true,
    households: true,
    weather: false
  });

  const getWeatherText = (code: number) => {
    if (code === 0) return 'Clear Sky';
    if (code <= 3) return 'Partly Cloudy';
    if (code <= 48) return 'Foggy';
    if (code <= 67) return 'Rain / Drizzle';
    if (code <= 77) return 'Snow';
    if (code <= 99) return 'Thunderstorm';
    return 'Overcast';
  };

  const fetchWeatherData = async () => {
    try {
      const response = await fetch(
        `https://api.open-meteo.com/v1/forecast?latitude=${location.lat}&longitude=${location.lng}&current_weather=true`
      );
      const data = await response.json();
      if (data.current_weather) {
        setWeatherInfo({
          temp: data.current_weather.temperature,
          windSpeed: data.current_weather.windspeed,
          conditionCode: data.current_weather.weathercode,
          conditionText: getWeatherText(data.current_weather.weathercode)
        });
      }
    } catch (err) {
      console.error("Weather sync failed", err);
    }
  };

  const updateRadarLayer = async () => {
    if (!mapRef.current) return;

    // Remove existing radar layer if any
    if (radarLayerRef.current) {
      mapRef.current.removeLayer(radarLayerRef.current);
      radarLayerRef.current = null;
    }

    if (layers.weather) {
      try {
        // Fetch latest radar timestamps from RainViewer
        const rvResponse = await fetch('https://api.rainviewer.com/public/maps.json');
        const rvData = await rvResponse.json();
        const latestTs = rvData[rvData.length - 1];

        const radarUrl = `https://tilecache.rainviewer.com/v2/radar/${latestTs}/256/{z}/{x}/{y}/2/1_1.png`;
        radarLayerRef.current = (window as any).L.tileLayer(radarUrl, {
          opacity: 0.6,
          zIndex: 1000
        }).addTo(mapRef.current);
      } catch (err) {
        console.error("Radar sync failed", err);
      }
    }
  };

  useEffect(() => {
    fetchWeatherData();
  }, [location]);

  useEffect(() => {
    updateRadarLayer();
  }, [layers.weather]);

  useEffect(() => {
    if (mapContainerRef.current && !mapRef.current) {
      // Initialize map
      mapRef.current = (window as any).L.map(mapContainerRef.current, {
        zoomControl: false 
      }).setView([location.lat, location.lng], 15);

      (window as any).L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
      }).addTo(mapRef.current);

      (window as any).L.control.zoom({
        position: 'bottomleft'
      }).addTo(mapRef.current);

      const addMarkerWithStreetView = (pos: [number, number], title: string, subtitle: string) => {
        const marker = (window as any).L.marker(pos).addTo(mapRef.current);
        const popupContent = document.createElement('div');
        popupContent.className = 'p-1';
        popupContent.innerHTML = `
          <div class="mb-2">
            <b class="text-slate-900 block text-sm">${title}</b>
            <span class="text-slate-500 text-[10px] font-bold uppercase">${subtitle}</span>
          </div>
          <button class="street-view-btn w-full bg-blue-600 text-white text-[10px] font-black py-2 rounded-lg hover:bg-blue-700 transition-colors uppercase tracking-widest">
            Street View
          </button>
        `;

        const btn = popupContent.querySelector('.street-view-btn');
        btn?.addEventListener('click', () => {
          setStreetViewCoords({ lat: pos[0], lng: pos[1] });
          marker.closePopup();
        });

        marker.bindPopup(popupContent);
      };

      // Core Marker
      addMarkerWithStreetView([location.lat, location.lng], name, 'Digital Twin Core');

      // Simulated Infrastructure Nodes
      addMarkerWithStreetView([location.lat + 0.005, location.lng + 0.005], `${name} Health Alpha`, 'Primary Health Node');
      addMarkerWithStreetView([location.lat - 0.005, location.lng - 0.003], `${name} Health Beta`, 'Secondary Health Node');

      // Household Pings (Simulated)
      const pings: [number, number][] = [
        [location.lat + 0.002, location.lng + 0.002],
        [location.lat - 0.002, location.lng + 0.004],
        [location.lat + 0.003, location.lng - 0.001],
      ];
      pings.forEach((pos, i) => {
        addMarkerWithStreetView(pos, `Relay #${i+102}`, 'Resident B-LAN Relay');
      });
    }

    if (mapRef.current) {
      setTimeout(() => {
        mapRef.current.invalidateSize();
        if (isExpanded) {
          mapRef.current.setZoom(17, { animate: true });
        } else {
          mapRef.current.setZoom(15, { animate: true });
        }
      }, 500);
    }
  }, [location, name, isExpanded]);

  const toggleLayer = (layer: keyof typeof layers) => {
    setLayers(prev => ({ ...prev, [layer]: !prev[layer] }));
  };

  return (
    <div className="w-full h-full relative bg-slate-200 transition-all duration-500">
      <div ref={mapContainerRef} className="w-full h-full" />

      {/* HUD Overlays */}
      <div className="absolute top-4 left-4 z-[1000] flex flex-col gap-2 pointer-events-none">
        <div className="glass-panel px-4 py-2.5 rounded-2xl text-[10px] font-black text-slate-800 shadow-xl border border-white/60 flex items-center gap-2.5 pointer-events-auto">
          <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.6)]"></span>
          OFFICIAL GIS DATA SOURCE
        </div>

        {weatherInfo && (
          <div className="glass-panel px-4 py-3 rounded-2xl shadow-xl border border-white/60 flex flex-col gap-1 pointer-events-auto bg-slate-900/10 backdrop-blur-md">
            <div className="flex items-center gap-3">
              <span className="text-xl">
                {weatherInfo.conditionCode < 3 ? '☀️' : weatherInfo.conditionCode < 50 ? '☁️' : '🌧️'}
              </span>
              <div>
                <p className="text-[10px] font-black text-slate-900 uppercase tracking-widest">{weatherInfo.conditionText}</p>
                <div className="flex items-baseline gap-1">
                  <span className="text-lg font-black text-slate-900 leading-none">{weatherInfo.temp}°C</span>
                  <span className="text-[8px] font-bold text-slate-500 uppercase tracking-tighter">Local Temp</span>
                </div>
              </div>
            </div>
            <div className="mt-1 pt-1 border-t border-slate-200/50 flex justify-between items-center">
               <span className="text-[8px] font-black text-slate-400 uppercase">Wind Velocity</span>
               <span className="text-[8px] font-mono font-bold text-slate-700">{weatherInfo.windSpeed} km/h</span>
            </div>
          </div>
        )}
      </div>

      {/* Street View Embed Overlay */}
      {streetViewCoords && (
        <div className="absolute inset-0 z-[3000] bg-slate-900 animate-in fade-in zoom-in-95 duration-300">
          <header className="absolute top-4 left-4 right-4 z-[3100] flex justify-between items-center px-6 py-3 bg-white/90 backdrop-blur-md rounded-2xl border border-white/50 shadow-2xl">
            <div>
              <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Spatial Immersion</p>
              <h4 className="text-xs font-bold text-slate-900">Street View Analysis Mode</h4>
            </div>
            <button 
              onClick={() => setStreetViewCoords(null)}
              className="w-8 h-8 flex items-center justify-center bg-slate-100 hover:bg-slate-200 text-slate-900 rounded-full font-black text-sm transition-all"
            >
              ✕
            </button>
          </header>

          <iframe
            className="w-full h-full border-0"
            loading="lazy"
            allowFullScreen
            src={`https://www.google.com/maps/embed/v1/streetview?key=${process.env.API_KEY}&location=${streetViewCoords.lat},${streetViewCoords.lng}&heading=210&pitch=10&fov=35`}
          ></iframe>

          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-[3100] px-4 py-2 bg-slate-900/80 backdrop-blur-md border border-slate-700 rounded-xl text-[9px] font-mono text-slate-400">
            LAT: {streetViewCoords.lat.toFixed(6)} | LNG: {streetViewCoords.lng.toFixed(6)}
          </div>
        </div>
      )}

      {isExpanded && !streetViewCoords && (
        <div className="absolute bottom-6 right-6 z-[1000] glass-panel p-5 rounded-[2rem] border border-white/60 shadow-2xl animate-in slide-in-from-bottom duration-500 w-[280px]">
          <div className="flex items-center justify-between mb-4">
            <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest">Urban Layer Legend</h4>
            <div className="text-[9px] font-bold text-slate-400 bg-slate-100 px-2 py-0.5 rounded-full uppercase">Live Feed</div>
          </div>

          <div className="space-y-3">
            <div className={`group flex items-start gap-3 p-2.5 rounded-2xl transition-all cursor-pointer ${layers.parcels ? 'bg-blue-50/50' : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer('parcels')}>
              <div className="w-4 h-4 bg-blue-500/20 border-2 border-blue-500 rounded-md shrink-0 mt-0.5"></div>
              <div>
                <span className="text-[10px] font-black text-slate-800 block mb-0.5 uppercase">Parcels</span>
              </div>
            </div>

            <div className={`group flex items-start gap-3 p-2.5 rounded-2xl transition-all cursor-pointer ${layers.weather ? 'bg-amber-500/10' : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer('weather')}>
              <div className="w-4 h-4 bg-amber-500/20 border-2 border-amber-600 rounded-md shrink-0 mt-0.5"></div>
              <div>
                <span className="text-[10px] font-black text-slate-800 block mb-0.5 uppercase">Tactical Radar</span>
              </div>
            </div>

            <div className={`group flex items-start gap-3 p-2.5 rounded-2xl transition-all cursor-pointer ${layers.health ? 'bg-rose-500/10' : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer('health')}>
              <div className="w-4 h-4 bg-rose-600/20 border-2 border-rose-600 rounded-md shrink-0 mt-0.5"></div>
              <div>
                <span className="text-[10px] font-black text-slate-800 block mb-0.5 uppercase">Health Nodes</span>
              </div>
            </div>

            <div className={`group flex items-start gap-3 p-2.5 rounded-2xl transition-all cursor-pointer ${layers.households ? 'bg-blue-600/10' : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer('households')}>
              <div className="w-4 h-4 bg-blue-600/20 border-2 border-blue-600 rounded-md shrink-0 mt-0.5"></div>
              <div>
                <span className="text-[10px] font-black text-slate-800 block mb-0.5 uppercase">Resident B-LAN</span>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { TwinMetadata, MeshNode, NISTLayer, NeighborhoodBLan, ResidentPing, TacticalAlert } from '../types';
import { Map } from './Map';

interface GISAnalysisProps {
  metadata: TwinMetadata;
}

type AnalysisModule = 'connectivity' | 'water' | 'traffic' | 'emergency';

export const GISAnalysis: React.FC<GISAnalysisProps> = ({ metadata }) => {
  const [activeModule, setActiveModule] = useState<AnalysisModule>('connectivity');
  const [simulationActive, setSimulationActive] = useState(false);
  const [simLogs, setSimLogs] = useState<string[]>([]);

  // Dynamic Neighborhoods derived strictly from City Metadata
  const [neighborhoods, setNeighborhoods] = useState<NeighborhoodBLan[]>([]);

  useEffect(() => {
    // Generate simulated GIS neighborhood sectors based on the provided entity name
    const sectors = ['North Quadrant', 'Central Core', 'Highland Sector', 'Western Corridor', 'Eastern District'];
    const generated = sectors.map(s => ({
      name: `${metadata.name} ${s}`,
      nodes: Math.floor(Math.random() * 200) + 50,
      health: Math.floor(Math.random() * 40) + 60,
      status: (Math.random() > 0.8 ? 'degraded' : 'stable') as NeighborhoodBLan['status']
    }));
    setNeighborhoods(generated);
  }, [metadata.name]);

  // State for Connectivity
  const [networkNodes, setNetworkNodes] = useState<MeshNode[]>([
    { id: 'CORE-HUB-01', status: 'active', signal: 100, type: 'Fiber' },
    { id: 'RELAY-SECTOR-ALPHA', status: 'active', signal: 85, type: 'Wi-Fi' },
    { id: 'EMERGENCY-AP-01', status: 'active', signal: 95, type: 'Static' }, 
    { id: 'EMERGENCY-AP-02', status: 'active', signal: 90, type: 'Static' }, 
  ]);

  // Emergency Module States
  const [residentPings, setResidentPings] = useState<ResidentPing[]>([]);
  const [utilityAlerts, setUtilityAlerts] = useState<TacticalAlert[]>([]);

  useEffect(() => {
    if (neighborhoods.length > 0) {
      setResidentPings([
        { householdId: 'HH-772', neighborhood: neighborhoods[0].name, needs: [], powerStatus: 'on', timestamp: 'Now' },
        { householdId: 'HH-104', neighborhood: neighborhoods[1].name, needs: ['First Aid'], powerStatus: 'battery', timestamp: '3m ago' },
        { householdId: 'HH-882', neighborhood: neighborhoods[2].name, needs: [], powerStatus: 'on', timestamp: '5m ago' },
      ]);
      setUtilityAlerts([
        { timestamp: '11:15', sender: 'Regional Grid', message: `Load balancing initiated for ${metadata.name} regional sectors.`, priority: 'high' },
        { timestamp: '11:22', sender: 'Emergency Services', message: `Tactical B-LAN active across all ${metadata.name} quadrants.`, priority: 'critical' },
      ]);
    }
  }, [neighborhoods, metadata.name]);

  // State for Water Deep Dive
  const [waterCauseData, setWaterCauseData] = useState([
    { label: 'Irrigation Pattern', value: 45, color: 'bg-rose-500' },
    { label: 'Network Leakage', value: 30, color: 'bg-amber-500' },
    { label: 'Residential Use', value: 25, color: 'bg-emerald-500' },
  ]);

  // State for Traffic Simulation
  const [trafficMetric, setTrafficMetric] = useState(12.4);
  const [trafficDensity, setTrafficDensity] = useState(70);
  const [transportAvailability, setTransportAvailability] = useState(30);

  // Real-time Traffic Impact Calculation
  useEffect(() => {
    if (!simulationActive) {
      const baseDelay = 8 + (trafficDensity * 0.18); 
      const efficiencyFactor = (transportAvailability * 0.006); 
      const currentDelay = baseDelay * (1 - efficiencyFactor);
      setTrafficMetric(parseFloat(Math.max(1.5, currentDelay).toFixed(1)));
    }
  }, [trafficDensity, transportAvailability, simulationActive]);

  const addLog = (msg: string) => {
    setSimLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev].slice(0, 18));
  };

  const runEmergencySync = async () => {
    setSimulationActive(true);
    addLog(`POLLING ${metadata.name.toUpperCase()} TACTICAL HUBS...`);
    await new Promise(r => setTimeout(r, 1000));
    const dataSource = metadata.officialUrl ? `Official GIS: ${metadata.officialUrl}` : "Simulated Spatial Core";
    addLog(`INGESTING HOUSEHOLD DATA FROM ${dataSource}`);

    const newPing: ResidentPing = {
      householdId: `HH-${Math.floor(Math.random() * 900) + 100}`,
      neighborhood: neighborhoods[Math.floor(Math.random() * neighborhoods.length)].name,
      needs: Math.random() > 0.8 ? ['Medical Supply'] : [],
      powerStatus: Math.random() > 0.5 ? 'battery' : 'on',
      timestamp: 'Just now'
    };
    setResidentPings(prev => [newPing, ...prev].slice(0, 6));

    await new Promise(r => setTimeout(r, 1500));
    addLog(`SYNC COMPLETE: ${neighborhoods.length} Sectors reported via mesh.`);
    setSimulationActive(false);
  };

  const runConnectivitySim = async () => {
    setSimulationActive(true);
    addLog(`INITIATING ${metadata.name.toUpperCase()} FAILOVER TEST...`);
    await new Promise(r => setTimeout(r, 1500));
    addLog("STAGE 1: SIMULATING FIBER DISRUPTION. ACTIVATING B-LAN...");
    setNetworkNodes(prev => prev.map(n => ({ ...n, status: n.type === 'Fiber' ? 'failing' : 'relay', signal: Math.floor(Math.random() * 50) + 20 })));
    await new Promise(r => setTimeout(r, 1500));
    addLog(`RE-ROUTING ${metadata.name} CORE SERVICES VIA NEIGHBORHOOD MESH...`);
    await new Promise(r => setTimeout(r, 1500));
    addLog("SIMULATION COMPLETE: Critical nodes maintained.");
    setSimulationActive(false);
  };

  const runTrafficMitigation = async () => {
    setSimulationActive(true);
    addLog(`CALCULATING TRAFFIC FLOW FOR ${metadata.name}...`);
    await new Promise(r => setTimeout(r, 800));
    const currentBase = trafficMetric;
    addLog(`BASELINE DELAY: ${currentBase} MIN.`);
    await new Promise(r => setTimeout(r, 1000));
    addLog(`OPTIMIZING ARTERIAL SIGNAL PHASING...`);
    const targetMetric = currentBase * 0.75;
    let current = currentBase;
    while (current > targetMetric) {
      current -= 0.2;
      if (current < targetMetric) current = targetMetric;
      setTrafficMetric(parseFloat(current.toFixed(1)));
      await new Promise(r => setTimeout(r, 100));
    }
    addLog("EVPP PROTOCOL ACTIVE: Emergency vehicles prioritized.");
    await new Promise(r => setTimeout(r, 800));
    addLog("SUCCESS: Spatial core traffic reduction achieved.");
    setSimulationActive(false);
  };

  const runEmergencyReroute = async () => {
    setSimulationActive(true);
    addLog(`INITIATING EMERGENCY REROUTE PROTOCOL FOR ${metadata.name.toUpperCase()}...`);
    await new Promise(r => setTimeout(r, 800));
    addLog(`CALCULATING OPTIMAL RESPONSE PATHS (ORP) ACROSS ${neighborhoods.length} SECTORS...`);
    await new Promise(r => setTimeout(r, 1000));
    addLog(`TRIGGERING DYNAMIC TRAFFIC SIGNAL PREEMPTION (DTSP)...`);
    await new Promise(r => setTimeout(r, 1200));
    const reduction = (Math.random() * 3 + 2).toFixed(1);
    addLog(`PUBLIC SAFETY IMPACT: Average response time reduced by ${reduction} minutes.`);
    await new Promise(r => setTimeout(r, 800));
    addLog(`SUCCESS: Emergency corridor established via Central Axis.`);
    setSimulationActive(false);
  };

  return (
    <div className="flex-1 flex flex-col lg:flex-row min-h-0 bg-slate-950 text-slate-200 overflow-hidden">
      {/* Research Sidebar */}
      <aside className="w-full lg:w-[420px] border-r border-slate-800 flex flex-col overflow-hidden">
        <header className="p-6 border-b border-slate-800 bg-slate-900/50">
          <div className="flex items-center justify-between mb-1">
             <h2 className="text-xl font-black text-white tracking-tight">GIS Layer Analysis</h2>
             <span className="text-[8px] font-black bg-blue-500/10 text-blue-400 px-2 py-0.5 rounded border border-blue-500/20">
               {metadata.officialUrl ? "OFFICIAL" : "SIMULATED"}
             </span>
          </div>
          <p className="text-[10px] font-bold text-rose-500 uppercase tracking-[0.2em]">Research Center | {metadata.name}</p>
          {metadata.officialUrl && (
            <p className="text-[9px] text-slate-500 font-mono mt-2 truncate">Source: {metadata.officialUrl}</p>
          )}
        </header>

        {/* Module Switcher */}
        <nav className="flex border-b border-slate-800 overflow-x-auto no-scrollbar">
          {(['connectivity', 'water', 'traffic', 'emergency'] as AnalysisModule[]).map(mod => (
            <button
              key={mod}
              onClick={() => setActiveModule(mod)}
              className={`flex-1 min-w-[100px] py-4 text-[10px] font-black uppercase tracking-widest transition-all ${
                activeModule === mod ? 'text-white border-b-2 border-rose-500 bg-slate-900' : 'text-slate-500 hover:text-slate-300'
              }`}
            >
              {mod}
            </button>
          ))}
        </nav>

        <div className="flex-1 overflow-y-auto p-6 space-y-8 scrollbar-thin scrollbar-thumb-slate-800">

          {activeModule === 'emergency' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-left duration-300">
              <section className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-xs font-black text-rose-500 uppercase tracking-widest">Neighborhood B-LAN Pulse</h3>
                  <span className="text-[9px] text-slate-500 font-bold uppercase">{neighborhoods.length} Sectors Active</span>
                </div>
                <div className="grid grid-cols-1 gap-2">
                  {neighborhoods.map(n => (
                    <div key={n.name} className="p-3 bg-slate-900/50 border border-slate-800 rounded-xl flex flex-col gap-2">
                      <div className="flex justify-between items-center">
                        <span className="text-[10px] font-black text-slate-200 uppercase">{n.name}</span>
                        <span className={`text-[8px] px-1.5 py-0.5 rounded font-black uppercase ${
                          n.status === 'stable' ? 'bg-emerald-500/10 text-emerald-500' : 
                          n.status === 'degraded' ? 'bg-amber-500/10 text-amber-500' : 'bg-rose-500/10 text-rose-500 animate-pulse'
