             <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Regional Core</p>
                <p className="text-sm font-bold text-white">GIS Integrated</p>
             </div>
          </div>
          <div className="glass-panel px-5 py-3 rounded-2xl border border-white/10 shadow-2xl flex items-center gap-4 bg-slate-900/80 backdrop-blur-xl">
             <div className="w-10 h-10 bg-blue-600/20 rounded-full flex items-center justify-center text-blue-500">📶</div>
             <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Tactical B-LAN</p>
                <p className="text-sm font-bold text-white">{neighborhoods.filter(n => n.status === 'stable').length} Sectors Optimal</p>
             </div>
          </div>
        </div>

        {simulationActive && (
          <div className="absolute inset-0 z-[2000] flex items-center justify-center pointer-events-none">
            <div className="p-8 rounded-[3rem] border-4 border-rose-500/40 bg-rose-950/20 backdrop-blur-md animate-pulse">
               <h3 className="text-4xl font-black text-rose-500 text-center uppercase tracking-tighter">Syncing Tactical Grid</h3>
               <p className="text-rose-400/60 text-center font-bold mt-2">Aggregating Household and Resident B-LAN Data</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { GeoLocation } from '../types';

interface MapProps {
  location: GeoLocation;
  name: string;
  isExpanded?: boolean;
}

interface WeatherInfo {
  temp: number;
  windSpeed: number;
  conditionCode: number;
  conditionText: string;
}

export const Map: React.FC<MapProps> = ({ location, name, isExpanded }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const radarLayerRef = useRef<any>(null);
  const [streetViewCoords, setStreetViewCoords] = useState<{lat: number, lng: number} | null>(null);
  const [weatherInfo, setWeatherInfo] = useState<WeatherInfo | null>(null);

  // Simulated and real layer visibility states
  const [layers, setLayers] = useState({
    parcels: true,
    utilities: true,
    greenery: true,
    health: true,
    households: true,
    weather: false
  });

  const getWeatherText = (code: number) => {
    if (code === 0) return 'Clear Sky';
    if (code <= 3) return 'Partly Cloudy';
    if (code <= 48) return 'Foggy';
    if (code <= 67) return 'Rain / Drizzle';
    if (code <= 77) return 'Snow';
    if (code <= 99) return 'Thunderstorm';
    return 'Overcast';
  };

  const fetchWeatherData = async () => {
    try {
      const response = await fetch(
        `https://api.open-meteo.com/v1/forecast?latitude=${location.lat}&longitude=${location.lng}&current_weather=true`
      );
      const data = await response.json();
      if (data.current_weather) {
        setWeatherInfo({
          temp: data.current_weather.temperature,
          windSpeed: data.current_weather.windspeed,
          conditionCode: data.current_weather.weathercode,
          conditionText: getWeatherText(data.current_weather.weathercode)
        });
      }
    } catch (err) {
      console.error("Weather sync failed", err);
    }
  };

  const updateRadarLayer = async () => {
    if (!mapRef.current) return;

    // Remove existing radar layer if any
    if (radarLayerRef.current) {
      mapRef.current.removeLayer(radarLayerRef.current);
      radarLayerRef.current = null;
    }

    if (layers.weather) {
      try {
        // Fetch latest radar timestamps from RainViewer
        const rvResponse = await fetch('https://api.rainviewer.com/public/maps.json');
        const rvData = await rvResponse.json();
        const latestTs = rvData[rvData.length - 1];

        const radarUrl = `https://tilecache.rainviewer.com/v2/radar/${latestTs}/256/{z}/{x}/{y}/2/1_1.png`;
        radarLayerRef.current = (window as any).L.tileLayer(radarUrl, {
          opacity: 0.6,
          zIndex: 1000
        }).addTo(mapRef.current);
      } catch (err) {
        console.error("Radar sync failed", err);
      }
    }
  };

  useEffect(() => {
    fetchWeatherData();
  }, [location]);

  useEffect(() => {
    updateRadarLayer();
  }, [layers.weather]);

  useEffect(() => {
    if (mapContainerRef.current && !mapRef.current) {
      // Initialize map
      mapRef.current = (window as any).L.map(mapContainerRef.current, {
        zoomControl: false 
      }).setView([location.lat, location.lng], 15);

      (window as any).L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
      }).addTo(mapRef.current);

      (window as any).L.control.zoom({
        position: 'bottomleft'
      }).addTo(mapRef.current);

      const addMarkerWithStreetView = (pos: [number, number], title: string, subtitle: string) => {
        const marker = (window as any).L.marker(pos).addTo(mapRef.current);
        const popupContent = document.createElement('div');
        popupContent.className = 'p-1';
        popupContent.innerHTML = `
          <div class="mb-2">
            <b class="text-slate-900 block text-sm">${title}</b>
            <span class="text-slate-500 text-[10px] font-bold uppercase">${subtitle}</span>
          </div>
          <button class="street-view-btn w-full bg-blue-600 text-white text-[10px] font-black py-2 rounded-lg hover:bg-blue-700 transition-colors uppercase tracking-widest">
            Street View
          </button>
        `;

        const btn = popupContent.querySelector('.street-view-btn');
        btn?.addEventListener('click', () => {
          setStreetViewCoords({ lat: pos[0], lng: pos[1] });
          marker.closePopup();
        });

        marker.bindPopup(popupContent);
      };

      // Core Marker
      addMarkerWithStreetView([location.lat, location.lng], name, 'Digital Twin Core');

      // Simulated Infrastructure Nodes
      addMarkerWithStreetView([location.lat + 0.005, location.lng + 0.005], `${name} Health Alpha`, 'Primary Health Node');
      addMarkerWithStreetView([location.lat - 0.005, location.lng - 0.003], `${name} Health Beta`, 'Secondary Health Node');

      // Household Pings (Simulated)
      const pings: [number, number][] = [
        [location.lat + 0.002, location.lng + 0.002],
        [location.lat - 0.002, location.lng + 0.004],
        [location.lat + 0.003, location.lng - 0.001],
      ];
      pings.forEach((pos, i) => {
