            <a 
              href="https://angelsharks.net/" 
              target="_blank" 
              rel="noopener noreferrer" 
              className="text-[9px] font-black text-slate-600 hover:text-rose-500 uppercase tracking-[0.2em] transition-colors"
            >
              Civic Twin by Angel Sharks
            </a>
            <span className="text-[8px] font-bold text-blue-400 uppercase tracking-[0.2em]">
              Copyright 2026
            </span>
          </div>
