import React, { useEffect, useRef, useState } from 'react';
import { GeoLocation } from '../types';

interface MapProps {
  location: GeoLocation;
  name: string;
  isExpanded?: boolean;
}

interface WeatherInfo {
  temp: number;
  windSpeed: number;
  conditionCode: number;
  conditionText: string;
}

export const Map: React.FC<MapProps> = ({ location, name, isExpanded }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const radarLayerRef = useRef<any>(null);

  // GIS Layer Refs
  const parcelsLayerRef = useRef<any>(null);
  const utilitiesLayerRef = useRef<any>(null);
  const greeneryLayerRef = useRef<any>(null);
  const householdLayerRef = useRef<any>(null);

  const [streetViewCoords, setStreetViewCoords] = useState<{lat: number, lng: number} | null>(null);
  const [weatherInfo, setWeatherInfo] = useState<WeatherInfo | null>(null);

  // Simulated and real layer visibility states
  const [layers, setLayers] = useState({
    parcels: true,
    utilities: true,
    greenery: true,
    health: true,
    households: true,
    weather: false
  });

  const getWeatherText = (code: number) => {
    if (code === 0) return 'Clear Sky';
    if (code <= 3) return 'Partly Cloudy';
    if (code <= 48) return 'Foggy';
    if (code <= 67) return 'Rain / Drizzle';
    if (code <= 77) return 'Snow';
    if (code <= 99) return 'Thunderstorm';
    return 'Overcast';
  };

  const fetchWeatherData = async () => {
    try {
      const response = await fetch(
        `https://api.open-meteo.com/v1/forecast?latitude=${location.lat}&longitude=${location.lng}&current_weather=true`
      );
      const data = await response.json();
      if (data.current_weather) {
        setWeatherInfo({
          temp: data.current_weather.temperature,
          windSpeed: data.current_weather.windspeed,
          conditionCode: data.current_weather.weathercode,
          conditionText: getWeatherText(data.current_weather.weathercode)
        });
      }
    } catch (err) {
      console.error("Weather sync failed", err);
    }
  };

  const updateRadarLayer = async () => {
    if (!mapRef.current) return;

    // Remove existing radar layer if any
    if (radarLayerRef.current) {
      mapRef.current.removeLayer(radarLayerRef.current);
      radarLayerRef.current = null;
    }

    if (layers.weather) {
      try {
        const rvResponse = await fetch('https://api.rainviewer.com/public/maps.json');
        const rvData = await rvResponse.json();
        const latestTs = rvData[rvData.length - 1];

        const radarUrl = `https://tilecache.rainviewer.com/v2/radar/${latestTs}/256/{z}/{x}/{y}/2/1_1.png`;
        radarLayerRef.current = (window as any).L.tileLayer(radarUrl, {
          opacity: 0.6,
          zIndex: 1000
        }).addTo(mapRef.current);
      } catch (err) {
        console.error("Radar sync failed", err);
      }
    }
  };

  // Logic to manage Leaflet LayerGroups visibility based on state
  useEffect(() => {
    if (!mapRef.current) return;

    const L = (window as any).L;

    const handleLayerToggle = (layerRef: React.MutableRefObject<any>, visible: boolean) => {
      if (layerRef.current) {
        if (visible) {
          if (!mapRef.current.hasLayer(layerRef.current)) {
            layerRef.current.addTo(mapRef.current);
          }
        } else {
          if (mapRef.current.hasLayer(layerRef.current)) {
            mapRef.current.removeLayer(layerRef.current);
          }
        }
      }
    };

    handleLayerToggle(parcelsLayerRef, layers.parcels);
    handleLayerToggle(utilitiesLayerRef, layers.utilities);
    handleLayerToggle(greeneryLayerRef, layers.greenery);
    handleLayerToggle(householdLayerRef, layers.households);
  }, [layers, location]);

  useEffect(() => {
    fetchWeatherData();
  }, [location]);

  useEffect(() => {
    updateRadarLayer();
  }, [layers.weather]);

  useEffect(() => {
    if (mapContainerRef.current && !mapRef.current) {
      const L = (window as any).L;

      // Initialize map
      mapRef.current = L.map(mapContainerRef.current, {
        zoomControl: false 
      }).setView([location.lat, location.lng], 15);

      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
      }).addTo(mapRef.current);

      L.control.zoom({
        position: 'bottomleft'
      }).addTo(mapRef.current);

      // Create Layer Groups
      parcelsLayerRef.current = L.layerGroup();
      utilitiesLayerRef.current = L.layerGroup();
      greeneryLayerRef.current = L.layerGroup();
      householdLayerRef.current = L.layerGroup();

      // Add default visible layers
      if (layers.parcels) parcelsLayerRef.current.addTo(mapRef.current);
      if (layers.utilities) utilitiesLayerRef.current.addTo(mapRef.current);
      if (layers.greenery) greeneryLayerRef.current.addTo(mapRef.current);
      if (layers.households) householdLayerRef.current.addTo(mapRef.current);

      const addMarkerWithStreetView = (pos: [number, number], title: string, subtitle: string, group?: any) => {
        const marker = L.marker(pos);
        if (group) marker.addTo(group);
        else marker.addTo(mapRef.current);

        const popupContent = document.createElement('div');
        popupContent.className = 'p-1';
        popupContent.innerHTML = `
          <div class="mb-2">
            <b class="text-slate-900 block text-sm">${title}</b>
            <span class="text-slate-500 text-[10px] font-bold uppercase">${subtitle}</span>
          </div>
          <button class="street-view-btn w-full bg-blue-600 text-white text-[10px] font-black py-2 rounded-lg hover:bg-blue-700 transition-colors uppercase tracking-widest">
            Street View
          </button>
        `;

        const btn = popupContent.querySelector('.street-view-btn');
        btn?.addEventListener('click', () => {
          setStreetViewCoords({ lat: pos[0], lng: pos[1] });
          marker.closePopup();
        });

        marker.bindPopup(popupContent);
      };

      // Core Marker
      addMarkerWithStreetView([location.lat, location.lng], name, 'Digital Twin Core');

      // --- SIMULATED GIS GEOMETRY ---

      // Simulated Parcels (Blue outlines)
      const parcelStyle = { color: '#2563eb', weight: 1.5, fillOpacity: 0.1, fillColor: '#3b82f6' };
      const latOffset = 0.001;
      const lngOffset = 0.0015;
      for (let i = -2; i <= 2; i++) {
        for (let j = -2; j <= 2; j++) {
          const bounds = [
            [location.lat + i * latOffset, location.lng + j * lngOffset],
            [location.lat + (i + 1) * latOffset, location.lng + (j + 1) * lngOffset]
          ];
          L.rectangle(bounds as any, parcelStyle).addTo(parcelsLayerRef.current);
        }
      }

      // Simulated Utilities (Amber dashed lines)
      const utilityStyle = { color: '#f59e0b', weight: 3, dashArray: '5, 10', opacity: 0.8 };
      L.polyline([
        [location.lat - 0.005, location.lng],
        [location.lat + 0.005, location.lng]
      ], utilityStyle).addTo(utilitiesLayerRef.current);
      L.polyline([
        [location.lat, location.lng - 0.008],
        [location.lat, location.lng + 0.008]
      ], utilityStyle).addTo(utilitiesLayerRef.current);

      // Simulated Green Space (Emerald polygons)
      const greeneryStyle = { color: '#059669', weight: 0, fillOpacity: 0.4, fillColor: '#10b981' };
      L.circle([location.lat + 0.004, location.lng + 0.004], { radius: 150, ...greeneryStyle }).addTo(greeneryLayerRef.current);
      L.circle([location.lat - 0.003, location.lng - 0.005], { radius: 200, ...greeneryStyle }).addTo(greeneryLayerRef.current);

      // Simulated Infrastructure Nodes
      addMarkerWithStreetView([location.lat + 0.005, location.lng + 0.005], `${name} Health Alpha`, 'Primary Health Node');
      addMarkerWithStreetView([location.lat - 0.005, location.lng - 0.003], `${name} Health Beta`, 'Secondary Health Node');

      // Household Pings (Simulated)
      const pings: [number, number][] = [
        [location.lat + 0.002, location.lng + 0.002],
        [location.lat - 0.002, location.lng + 0.004],
        [location.lat + 0.003, location.lng - 0.001],
      ];
      pings.forEach((pos, i) => {
        addMarkerWithStreetView(pos, `Relay #${i+102}`, 'Resident B-LAN Relay', householdLayerRef.current);
      });
    }

    if (mapRef.current) {
      setTimeout(() => {
        mapRef.current.invalidateSize();
        if (isExpanded) {
          mapRef.current.setZoom(17, { animate: true });
        } else {
          mapRef.current.setZoom(15, { animate: true });
        }
      }, 500);
    }
  }, [location, name, isExpanded]);

  const toggleLayer = (layer: keyof typeof layers) => {
    setLayers(prev => ({ ...prev, [layer]: !prev[layer] }));
  };

  const getStreetViewConfig = (coords: {lat: number, lng: number}) => {
    const y = location.lat - coords.lat;
    const x = location.lng - coords.lng;
    let heading = Math.atan2(x, y) * (180 / Math.PI);
    if (heading < 0) heading += 360;

    if (Math.abs(y) < 0.00001 && Math.abs(x) < 0.00001) {
      heading = 315;
    }

    const pitch = (coords.lat % 0.01) * 2000 - 10;

    return { 
      heading: Math.round(heading), 
      pitch: Math.round(pitch),
      fov: 40
    };
  };

  const streetViewConfig = streetViewCoords ? getStreetViewConfig(streetViewCoords) : null;

  return (
    <div className="w-full h-full relative bg-slate-200 transition-all duration-500">
      <div ref={mapContainerRef} className="w-full h-full" />

      {/* HUD Overlays */}
      <div className="absolute top-4 left-4 z-[1000] flex flex-col gap-2 pointer-events-none">
        <div className="glass-panel px-4 py-2.5 rounded-2xl text-[10px] font-black text-slate-800 shadow-xl border border-white/60 flex items-center gap-2.5 pointer-events-auto">
          <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.6)]"></span>
          OFFICIAL GIS DATA SOURCE
        </div>

        {weatherInfo && (
          <div className="glass-panel px-4 py-3 rounded-2xl shadow-xl border border-white/60 flex flex-col gap-1 pointer-events-auto bg-slate-900/10 backdrop-blur-md">
            <div className="flex items-center gap-3">
              <span className="text-xl">
                {weatherInfo.conditionCode < 3 ? '☀️' : weatherInfo.conditionCode < 50 ? '☁️' : '🌧️'}
              </span>
              <div>
                <p className="text-[10px] font-black text-slate-900 uppercase tracking-widest">{weatherInfo.conditionText}</p>
                <div className="flex items-baseline gap-1">
                  <span className="text-lg font-black text-slate-900 leading-none">{weatherInfo.temp}°C</span>
                  <span className="text-[8px] font-bold text-slate-500 uppercase tracking-tighter">Local Temp</span>
                </div>
              </div>
            </div>
            <div className="mt-1 pt-1 border-t border-slate-200/50 flex justify-between items-center">
               <span className="text-[8px] font-black text-slate-400 uppercase">Wind Velocity</span>
               <span className="text-[8px] font-mono font-bold text-slate-700">{weatherInfo.windSpeed} km/h</span>
            </div>
          </div>
        )}
      </div>

      {/* Street View Embed Overlay */}
      {streetViewCoords && streetViewConfig && (
        <div className="absolute inset-0 z-[3000] bg-slate-900 animate-in fade-in zoom-in-95 duration-300">
          <header className="absolute top-4 left-4 right-4 z-[3100] flex justify-between items-center px-6 py-3 bg-white/90 backdrop-blur-md rounded-2xl border border-white/50 shadow-2xl">
            <div className="flex items-center gap-4">
              <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white text-sm">👁️</div>
              <div>
                <p className="text-[9px] font-black text-blue-600 uppercase tracking-[0.2em]">Spatial Immersion</p>
                <h4 className="text-[11px] font-bold text-slate-900">Digital Street Analysis Mode</h4>
              </div>
            </div>
            <div className="flex items-center gap-4">
              <div className="hidden sm:flex flex-col text-right">
                <span className="text-[9px] font-black text-slate-400 uppercase">View Delta</span>
                <span className="text-[10px] font-mono font-bold text-slate-700">H: {streetViewConfig.heading}° | P: {streetViewConfig.pitch}°</span>
              </div>
              <button 
                onClick={() => setStreetViewCoords(null)}
                className="w-8 h-8 flex items-center justify-center bg-slate-100 hover:bg-slate-200 text-slate-900 rounded-full font-black text-sm transition-all"
              >
                ✕
              </button>
            </div>
          </header>

          <iframe
            className="w-full h-full border-0"
            loading="lazy"
            allowFullScreen
            src={`https://www.google.com/maps/embed/v1/streetview?key=${process.env.API_KEY}&location=${streetViewCoords.lat},${streetViewCoords.lng}&heading=${streetViewConfig.heading}&pitch=${streetViewConfig.pitch}&fov=${streetViewConfig.fov}`}
          ></iframe>

          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-[3100] px-6 py-2 bg-slate-900/80 backdrop-blur-md border border-white/10 rounded-2xl text-[9px] font-mono text-white/60 shadow-2xl flex items-center gap-4">
            <div className="flex items-center gap-2">
              <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-pulse"></span>
              LIVE PERSPECTIVE CALIBRATED
            </div>
            <div className="w-px h-3 bg-white/10"></div>
            <span>LAT: {streetViewCoords.lat.toFixed(6)}</span>
            <span>LNG: {streetViewCoords.lng.toFixed(6)}</span>
          </div>
        </div>
      )}

      {isExpanded && !streetViewCoords && (
        <div className="absolute bottom-6 right-6 z-[1000] glass-panel p-5 rounded-[2rem] border border-white/60 shadow-2xl animate-in slide-in-from-bottom duration-500 w-[280px]">
          <div className="flex items-center justify-between mb-4">
            <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest">Urban Layer Legend</h4>
            <div className="text-[9px] font-bold text-slate-400 bg-slate-100 px-2 py-0.5 rounded-full uppercase tracking-tighter">Official GIS</div>
          </div>

          <div className="space-y-2.5">
            <div className={`group flex items-start gap-3 p-2.5 rounded-2xl transition-all cursor-pointer ${layers.parcels ? 'bg-blue-600/5' : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer('parcels')}>
              <div className="w-4 h-4 bg-blue-500/10 border-2 border-blue-600 rounded-md shrink-0 mt-0.5"></div>
              <div>
                <span className="text-[10px] font-black text-slate-800 block mb-0.5 uppercase tracking-tight">Parcel Boundaries</span>
              </div>
            </div>

            <div className={`group flex items-start gap-3 p-2.5 rounded-2xl transition-all cursor-pointer ${layers.utilities ? 'bg-amber-600/5' : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer('utilities')}>
              <div className="w-4 h-4 bg-amber-500/10 border-2 border-amber-600 rounded-md shrink-0 mt-0.5"></div>
              <div>
                <span className="text-[10px] font-black text-slate-800 block mb-0.5 uppercase tracking-tight">Underground Utilities</span>
              </div>
            </div>

            <div className={`group flex items-start gap-3 p-2.5 rounded-2xl transition-all cursor-pointer ${layers.greenery ? 'bg-emerald-600/5' : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer('greenery')}>
              <div className="w-4 h-4 bg-emerald-500/10 border-2 border-emerald-600 rounded-md shrink-0 mt-0.5"></div>
              <div>
                <span className="text-[10px] font-black text-slate-800 block mb-0.5 uppercase tracking-tight">Public Green Space</span>
              </div>
            </div>

            <div className="h-px bg-slate-100 my-1 mx-2"></div>

            <div className={`group flex items-start gap-3 p-2.5 rounded-2xl transition-all cursor-pointer ${layers.weather ? 'bg-rose-600/5' : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer('weather')}>
              <div className="w-4 h-4 bg-rose-500/10 border-2 border-rose-600 rounded-md shrink-0 mt-0.5"></div>
              <div>
                <span className="text-[10px] font-black text-slate-800 block mb-0.5 uppercase tracking-tight">Tactical Radar</span>
              </div>
            </div>

            <div className={`group flex items-start gap-3 p-2.5 rounded-2xl transition-all cursor-pointer ${layers.households ? 'bg-slate-900/5' : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer('households')}>
              <div className="w-4 h-4 bg-slate-900/10 border-2 border-slate-900 rounded-md shrink-0 mt-0.5"></div>
              <div>
                <span className="text-[10px] font-black text-slate-800 block mb-0.5 uppercase tracking-tight">Resident B-LAN</span>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { TwinMetadata, GISLayerEndpoints } from '../types';

interface OnboardingProps {
  onComplete: (metadata: TwinMetadata) => void;
}

export const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState<1 | 2 | 3 | 4>(1);
  const [formData, setFormData] = useState({
    name: '',
    address: '',
    type: 'City' as TwinMetadata['type'],
    officialUrl: ''
  });
  const [gisLayers, setGisLayers] = useState<GISLayerEndpoints>({
    parcels: '',
    utilities: '',
    infrastructure: '',
    safety: ''
  });
  const [tempLocation, setTempLocation] = useState<TwinMetadata['location']>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleStep1Submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    try {
      const encodedAddress = encodeURIComponent(formData.address);
      const response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodedAddress}&limit=1`);
      const data = await response.json();

      if (data && data.length > 0) {
        setTempLocation({
          lat: parseFloat(data[0].lat),
          lng: parseFloat(data[0].lon),
          displayName: data[0].display_name
        });
        setStep(2);
      } else {
        setError("Location not found. Try a street address or city name.");
      }
    } catch (err) {
      setError("Connectivity issue. Please check your network.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleStep2Submit = (e: React.FormEvent) => {
    e.preventDefault();
    setStep(3); // Decision step
  };

  const finalizeOnboarding = (layers?: GISLayerEndpoints) => {
    onComplete({
      name: formData.name,
      address: formData.address,
      type: formData.type,
      location: tempLocation,
      officialUrl: formData.officialUrl,
      gisLayers: layers || {},
      isEmergencyMode: false
    });
  };

  const handleFinalSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    finalizeOnboarding(gisLayers);
  };

  const handleCIMLogin = () => {
    onComplete({
      name: 'Emergency Command Center',
      address: 'Classified / Backup B-lan',
      type: 'Special District',
      location: tempLocation || { lat: 0, lng: 0, displayName: 'Emergency Sector' },
      officialUrl: '',
      isEmergencyMode: true
    });
  };

  // Step 4: Actual GIS Input
  if (step === 4) {
    return (
      <div className="flex-1 flex items-center justify-center p-4 sm:p-6 lg:p-12">
        <div className="w-full max-w-2xl bg-white rounded-[2.5rem] shadow-2xl shadow-slate-200/50 border border-slate-200 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="p-8 sm:p-12 text-center bg-emerald-50 border-b border-emerald-200">
            <div className="inline-flex items-center justify-center w-14 h-14 bg-emerald-600 text-white rounded-[1.5rem] mb-6 shadow-lg rotate-3" aria-hidden="true">
              <span className="text-2xl">🗺️</span>
            </div>
            <h2 className="text-3xl font-black text-slate-900 mb-2">Configure GIS Layers</h2>
            <p className="text-sm sm:text-base text-slate-700 max-w-md mx-auto font-medium">
              Provide specific spatial data endpoints for your digital twin to enable precise urban modeling.
            </p>
          </div>

          <form onSubmit={handleFinalSubmit} className="p-8 sm:p-12 space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {[
                { label: 'Parcel GIS URL', key: 'parcels', placeholder: 'REST/WFS Endpoint', icon: '📦' },
                { label: 'Utilities Layer', key: 'utilities', placeholder: 'Water/Electric Grid', icon: '⚡' },
                { label: 'Infrastructure', key: 'infrastructure', placeholder: 'Roads/Bridges', icon: '🛣️' },
                { label: 'Public Safety', key: 'safety', placeholder: 'Emergency Sectors', icon: '🛡️' }
              ].map((layer) => (
                <div key={layer.key} className="space-y-1.5">
                  <label htmlFor={`gis-${layer.key}`} className="flex items-center gap-2 text-xs font-black text-slate-700 uppercase tracking-widest ml-1">
                    <span aria-hidden="true">{layer.icon}</span> {layer.label}
                  </label>
                  <input
                    id={`gis-${layer.key}`}
                    type="url"
                    className="w-full px-5 py-4 bg-slate-50 border border-slate-300 rounded-2xl focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-600 transition-all outline-none text-sm placeholder:text-slate-500 font-medium"
                    placeholder={layer.placeholder}
                    value={(gisLayers as any)[layer.key]}
                    onChange={(e) => setGisLayers({ ...gisLayers, [layer.key as keyof GISLayerEndpoints]: e.target.value })}
                  />
                </div>
              ))}
            </div>

            <div className="pt-4 flex flex-col sm:flex-row gap-4">
              <button
                type="button"
                onClick={() => setStep(3)}
                className="flex-1 px-8 py-5 border-2 border-slate-200 text-slate-700 font-black rounded-2xl hover:bg-slate-50 transition-all active:scale-95 uppercase text-xs tracking-widest"
              >
                Back
              </button>
              <button
                type="submit"
                className="flex-[2] bg-slate-900 text-white font-black py-5 rounded-2xl shadow-2xl shadow-slate-900/20 transition-all active:scale-[0.97] hover:bg-slate-800 uppercase text-xs tracking-[0.2em]"
              >
                Launch Digital Twin
              </button>
            </div>
          </form>
        </div>
      </div>
    );
  }

  // Step 3: Decision
  if (step === 3) {
    return (
      <div className="flex-1 flex items-center justify-center p-4 sm:p-6 lg:p-12">
        <div className="w-full max-w-xl bg-white rounded-[2.5rem] shadow-2xl shadow-slate-200/50 border border-slate-200 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="p-8 sm:p-12 text-center bg-blue-50 border-b border-blue-200">
            <div className="inline-flex items-center justify-center w-14 h-14 bg-blue-600 text-white rounded-[1.5rem] mb-6 shadow-lg -rotate-2" aria-hidden="true">
              <span className="text-2xl">⚙️</span>
            </div>
            <h2 className="text-3xl font-black text-slate-900 mb-2">GIS Data Integration</h2>
            <p className="text-sm sm:text-base text-slate-700 max-w-sm mx-auto font-medium leading-relaxed">
              Would you like to provide city-specific GIS layers now, or use our AI-driven spatial defaults?
            </p>
          </div>

          <div className="p-8 sm:p-12 space-y-4">
            <button
              onClick={() => setStep(4)}
              className="w-full group px-8 py-6 bg-slate-900 text-white rounded-2xl transition-all active:scale-[0.98] hover:bg-slate-800 flex items-center justify-between focus-visible:ring-4 focus-visible:ring-blue-600/30"
            >
              <div className="text-left">
                <p className="text-xs font-black uppercase tracking-widest text-blue-400 mb-1">Advanced Mode</p>
                <p className="font-bold text-lg">Add Custom GIS Layers</p>
              </div>
              <span className="text-2xl group-hover:translate-x-1 transition-transform" aria-hidden="true">→</span>
            </button>

            <button
              onClick={() => finalizeOnboarding()}
              className="w-full px-8 py-6 border-2 border-slate-200 text-slate-800 rounded-2xl hover:bg-slate-50 transition-all active:scale-[0.98] flex items-center justify-between"
            >
              <div className="text-left">
                <p className="text-xs font-black uppercase tracking-widest text-slate-600 mb-1">Standard Mode</p>
                <p className="font-bold text-lg">Skip and Use AI Defaults</p>
              </div>
              <span className="text-slate-600 text-xl" aria-hidden="true">⚡</span>
            </button>

            <button
              onClick={() => setStep(2)}
              className="w-full mt-4 text-xs font-black text-slate-600 uppercase tracking-[0.3em] hover:text-slate-900 transition-colors py-2"
            >
              Go Back
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Step 2: Portal URL
  if (step === 2) {
    return (
      <div className="flex-1 flex items-center justify-center p-4 sm:p-6 lg:p-12">
        <div className="w-full max-w-xl bg-white rounded-3xl shadow-2xl shadow-slate-200/50 border border-slate-200 overflow-hidden transition-all animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="p-6 sm:p-10 text-center bg-blue-50 border-b border-blue-200">
            <div className="inline-flex items-center justify-center w-12 h-12 bg-blue-600 text-white rounded-full mb-4 shadow-lg" aria-hidden="true">
              <span className="text-xl">🔗</span>
            </div>
            <h2 className="text-2xl sm:text-3xl font-black text-slate-900 mb-2">Connect Resources</h2>
            <p className="text-sm sm:text-base text-slate-700 max-w-sm mx-auto font-medium">
              Spatial core initialized for <b className="text-slate-900">{formData.name}</b>. Now, provide your city's official portal URL.
            </p>
          </div>

          <form onSubmit={handleStep2Submit} className="p-6 sm:p-10 space-y-6">
