              Submit Feedback
            </button>

            <div className="pt-6 text-center flex flex-col items-center gap-1">
              <a 
                href="https://angelsharks.net/" 
                target="_blank" 
                rel="noopener noreferrer" 
                className={`text-xs font-black uppercase tracking-[0.2em] transition-colors ${metadata.isEmergencyMode ? 'text-slate-400 hover:text-rose-500' : 'text-slate-500 hover:text-blue-700'}`}
              >
                Civic Twin by Angel Sharks
              </a>
              <span className={`text-[10px] font-bold uppercase tracking-[0.2em] ${metadata.isEmergencyMode ? 'text-rose-500' : 'text-blue-700'}`}>
                Copyright 2026
              </span>
            </div>
          </div>
        </div>
      </aside>

      {/* Main Viewport */}
      <div className="flex-1 flex flex-col min-w-0 h-full relative" role="main">
        {metadata.isEmergencyMode && (
          <div className="bg-rose-700 text-white px-4 py-2 text-xs font-black uppercase tracking-[0.3em] text-center shadow-lg relative z-10" role="alert">
            ANGEL SHARK TACTICAL B-LAN ACTIVE
          </div>
