        <div className={`lg:hidden p-4 flex items-center justify-between border-b ${metadata.isEmergencyMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'}`}>
          <button 
            onClick={() => setIsSidebarOpen(true)} 
            className={`px-4 py-2 rounded-xl text-xs font-black flex items-center gap-2 ${metadata.isEmergencyMode ? 'bg-slate-800 text-slate-200' : 'bg-slate-200 text-slate-800 focus-visible:ring-2 focus-visible:ring-blue-600'}`}
            aria-label="Open entity stats sidebar"
          >
            <span aria-hidden="true">📊</span> Entity Stats
          </button>
        </div>

        <div className="flex-1 flex flex-col xl:flex-row overflow-hidden relative">
          <div className="flex-1 flex flex-col min-w-0 overflow-y-auto">
            <div className={`transition-all duration-500 p-4 lg:p-6 relative ${isMapExpanded ? 'h-full sticky top-0 z-[1500] !p-0' : 'h-[66vh] pb-0'}`}>
              <div className={`h-full overflow-hidden relative border-4 transition-all duration-500 ${isMapExpanded ? 'rounded-none border-0' : 'rounded-3xl shadow-2xl border-white shadow-slate-300'}`}>
                {metadata.location && <Map location={metadata.location} name={metadata.name} isExpanded={isMapExpanded} />}
                <div className="absolute top-6 right-6 z-[2000] flex flex-col gap-2">
                  <button 
                    onClick={() => setIsMapExpanded(!isMapExpanded)} 
                    className="p-3 bg-white shadow-2xl rounded-2xl text-slate-900 hover:scale-105 active:scale-95 transition-all border border-slate-200 focus-visible:ring-4 focus-visible:ring-blue-600/30"
                    aria-label={isMapExpanded ? "Minimize map" : "Expand map"}
                  >
                    <span className="text-xl leading-none" aria-hidden="true">{isMapExpanded ? '🏹' : '🔍'}</span>
                  </button>
                </div>
              </div>
            </div>

            <div className={`p-4 sm:p-6 lg:p-10 transition-all duration-500 ${isMapExpanded ? 'opacity-0 h-0 overflow-hidden' : 'opacity-100'}`}>
              <header className="mb-8">
                <h3 className={`text-xl sm:text-2xl font-black tracking-tight ${metadata.isEmergencyMode ? 'text-white' : 'text-slate-900'}`}>Intelligence Matrix</h3>
                <p className={`text-sm font-bold uppercase tracking-widest ${metadata.isEmergencyMode ? 'text-slate-500' : 'text-slate-600'}`}>Digital Twin Live Feed</p>
              </header>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 sm:gap-8 mb-12">
                {insights.map((insight, idx) => (
                  <div key={idx} className={metadata.isEmergencyMode ? 'invert brightness-90 grayscale-[0.5]' : ''}>
                    <DataLayerCard insight={insight} />
                  </div>
                ))}
              </div>
            </div>
          </div>
          {metadata.isEmergencyMode && (
            <div className={`transition-all duration-500 xl:h-full overflow-hidden ${isMapExpanded ? 'w-0 border-0 opacity-0' : 'w-full xl:w-[350px] bg-slate-950 p-6 border-l border-slate-800'}`}>
              <BLanTacticalPanel nodes={meshNodes} alerts={tacticalAlerts} />
            </div>
          )}
        </div>
      </div>

      {isFeedbackOpen && (
        <FeedbackModal onClose={() => setIsFeedbackOpen(false)} />
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { TwinMetadata, MeshNode, NISTLayer, NeighborhoodBLan, ResidentPing, TacticalAlert } from '../types';
import { Map } from './Map';

interface GISAnalysisProps {
  metadata: TwinMetadata;
}

type AnalysisModule = 'connectivity' | 'water' | 'traffic' | 'emergency';

export const GISAnalysis: React.FC<GISAnalysisProps> = ({ metadata }) => {
  const [activeModule, setActiveModule] = useState<AnalysisModule>('connectivity');
  const [simulationActive, setSimulationActive] = useState(false);
  const [simLogs, setSimLogs] = useState<string[]>([]);

  // Dynamic Neighborhoods derived strictly from City Metadata
  const [neighborhoods, setNeighborhoods] = useState<NeighborhoodBLan[]>([]);

  useEffect(() => {
    // Generate simulated GIS neighborhood sectors based on the provided entity name
    const sectors = ['North Quadrant', 'Central Core', 'Highland Sector', 'Western Corridor', 'Eastern District'];
    const generated = sectors.map(s => ({
      name: `${metadata.name} ${s}`,
      nodes: Math.floor(Math.random() * 200) + 50,
      health: Math.floor(Math.random() * 40) + 60,
      status: (Math.random() > 0.8 ? 'degraded' : 'stable') as NeighborhoodBLan['status']
    }));
    setNeighborhoods(generated);
  }, [metadata.name]);

  // State for Connectivity
  const [networkNodes, setNetworkNodes] = useState<MeshNode[]>([
    { id: 'CORE-HUB-01', status: 'active', signal: 100, type: 'Fiber' },
    { id: 'RELAY-SECTOR-ALPHA', status: 'active', signal: 85, type: 'Wi-Fi' },
    { id: 'EMERGENCY-AP-01', status: 'active', signal: 95, type: 'Static' }, 
    { id: 'EMERGENCY-AP-02', status: 'active', signal: 90, type: 'Static' }, 
  ]);

  // Emergency Module States
  const [residentPings, setResidentPings] = useState<ResidentPing[]>([]);
  const [utilityAlerts, setUtilityAlerts] = useState<TacticalAlert[]>([]);

  useEffect(() => {
    if (neighborhoods.length > 0) {
      setResidentPings([
        { householdId: 'HH-772', neighborhood: neighborhoods[0].name, needs: [], powerStatus: 'on', timestamp: 'Now' },
        { householdId: 'HH-104', neighborhood: neighborhoods[1].name, needs: ['First Aid'], powerStatus: 'battery', timestamp: '3m ago' },
        { householdId: 'HH-882', neighborhood: neighborhoods[2].name, needs: [], powerStatus: 'on', timestamp: '5m ago' },
      ]);
      setUtilityAlerts([
        { timestamp: '11:15', sender: 'Regional Grid', message: `Load balancing initiated for ${metadata.name} regional sectors.`, priority: 'high' },
        { timestamp: '11:22', sender: 'Emergency Services', message: `Tactical B-LAN active across all ${metadata.name} quadrants.`, priority: 'critical' },
      ]);
    }
  }, [neighborhoods, metadata.name]);

  // State for Water Deep Dive
  const [waterCauseData, setWaterCauseData] = useState([
    { label: 'Irrigation Pattern', value: 45, color: 'bg-rose-500' },
    { label: 'Network Leakage', value: 30, color: 'bg-amber-500' },
    { label: 'Residential Use', value: 25, color: 'bg-emerald-500' },
  ]);

  // State for Traffic Simulation
  const [trafficMetric, setTrafficMetric] = useState(12.4);
  const [trafficDensity, setTrafficDensity] = useState(70);
  const [transportAvailability, setTransportAvailability] = useState(30);

  // Real-time Traffic Impact Calculation
  useEffect(() => {
    if (!simulationActive) {
      const baseDelay = 8 + (trafficDensity * 0.18); 
      const efficiencyFactor = (transportAvailability * 0.006); 
      const currentDelay = baseDelay * (1 - efficiencyFactor);
      setTrafficMetric(parseFloat(Math.max(1.5, currentDelay).toFixed(1)));
    }
  }, [trafficDensity, transportAvailability, simulationActive]);

  const addLog = (msg: string) => {
    setSimLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev].slice(0, 18));
  };

  const healSector = (name: string) => {
    setNeighborhoods(prev => prev.map(n => 
      n.name === name ? { ...n, health: 100, status: 'stable' } : n
    ));
    addLog(`HEAL COMMAND ISSUED: ${name} mesh fully restored.`);
  };

  const toggleIsolation = (name: string) => {
    setNeighborhoods(prev => prev.map(n => 
      n.name === name ? { 
        ...n, 
        status: n.status === 'isolated' ? 'stable' : 'isolated', 
        health: n.status === 'isolated' ? 100 : 0 
      } : n
    ));
    const isNowIsolated = neighborhoods.find(n => n.name === name)?.status !== 'isolated';
    addLog(`TACTICAL OVERRIDE: ${name} ${isNowIsolated ? 'ISOLATED' : 'RECONNECTED'} to A-LAN backbone.`);
  };

  const runEmergencySync = async () => {
    setSimulationActive(true);
    addLog(`POLLING ${metadata.name.toUpperCase()} TACTICAL HUBS...`);
    await new Promise(r => setTimeout(r, 1000));
    const dataSource = metadata.officialUrl ? `Official GIS: ${metadata.officialUrl}` : "Simulated Spatial Core";
    addLog(`INGESTING HOUSEHOLD DATA FROM ${dataSource}`);

    const newPing: ResidentPing = {
      householdId: `HH-${Math.floor(Math.random() * 900) + 100}`,
      neighborhood: neighborhoods[Math.floor(Math.random() * neighborhoods.length)].name,
      needs: Math.random() > 0.8 ? ['Medical Supply'] : [],
      powerStatus: Math.random() > 0.5 ? 'battery' : 'on',
      timestamp: 'Just now'
    };
    setResidentPings(prev => [newPing, ...prev].slice(0, 6));

    await new Promise(r => setTimeout(r, 1500));
    addLog(`SYNC COMPLETE: ${neighborhoods.length} Sectors reported via mesh.`);
    setSimulationActive(false);
  };

  const runConnectivitySim = async () => {
    setSimulationActive(true);
    addLog(`INITIATING ${metadata.name.toUpperCase()} FAILOVER TEST...`);
    await new Promise(r => setTimeout(r, 1500));
    addLog("STAGE 1: SIMULATING FIBER DISRUPTION. ACTIVATING B-LAN...");
    setNetworkNodes(prev => prev.map(n => ({ ...n, status: n.type === 'Fiber' ? 'failing' : 'relay', signal: Math.floor(Math.random() * 50) + 20 })));
    await new Promise(r => setTimeout(r, 1500));
    addLog(`RE-ROUTING ${metadata.name} CORE SERVICES VIA NEIGHBORHOOD MESH...`);
    await new Promise(r => setTimeout(r, 1500));
    addLog("SIMULATION COMPLETE: Critical nodes maintained.");
    setSimulationActive(false);
  };

  const runTrafficMitigation = async () => {
    setSimulationActive(true);
    addLog(`CALCULATING TRAFFIC FLOW FOR ${metadata.name}...`);
    await new Promise(r => setTimeout(r, 800));
    const currentBase = trafficMetric;
    addLog(`BASELINE DELAY: ${currentBase} MIN.`);
    await new Promise(r => setTimeout(r, 1000));
    addLog(`OPTIMIZING ARTERIAL SIGNAL PHASING...`);
    const targetMetric = currentBase * 0.75;
    let current = currentBase;
    while (current > targetMetric) {
      current -= 0.2;
      if (current < targetMetric) current = targetMetric;
      setTrafficMetric(parseFloat(current.toFixed(1)));
      await new Promise(r => setTimeout(r, 100));
    }
    addLog("EVPP PROTOCOL ACTIVE: Emergency vehicles prioritized.");
    await new Promise(r => setTimeout(r, 800));
    addLog("SUCCESS: Spatial core traffic reduction achieved.");
    setSimulationActive(false);
  };

  const runEmergencyReroute = async () => {
    setSimulationActive(true);
    addLog(`INITIATING EMERGENCY REROUTE PROTOCOL FOR ${metadata.name.toUpperCase()}...`);
    await new Promise(r => setTimeout(r, 800));
    addLog(`CALCULATING OPTIMAL RESPONSE PATHS (ORP) ACROSS ${neighborhoods.length} SECTORS...`);
    await new Promise(r => setTimeout(r, 1000));
    addLog(`TRIGGERING DYNAMIC TRAFFIC SIGNAL PREEMPTION (DTSP)...`);
    await new Promise(r => setTimeout(r, 1200));
    const reduction = (Math.random() * 3 + 2).toFixed(1);
    addLog(`PUBLIC SAFETY IMPACT: Average response time reduced by ${reduction} minutes.`);
    await new Promise(r => setTimeout(r, 800));
    addLog(`SUCCESS: Emergency corridor established via Central Axis.`);
    setSimulationActive(false);
  };

  return (
    <div className="flex-1 flex flex-col lg:flex-row min-h-0 bg-slate-950 text-slate-200 overflow-hidden">
      {/* Research Sidebar */}
      <aside className="w-full lg:w-[420px] border-r border-slate-800 flex flex-col overflow-hidden" aria-label="GIS Controls Sidebar">
        <header className="p-6 border-b border-slate-800 bg-slate-900/50">
          <div className="flex items-center justify-between mb-1">
             <h2 className="text-xl font-black text-white tracking-tight">GIS Layer Analysis</h2>
             <span className="text-xs font-black bg-blue-600/20 text-blue-400 px-3 py-1 rounded border border-blue-500/30 uppercase tracking-tighter">
               {metadata.officialUrl ? "OFFICIAL" : "SIMULATED"}
             </span>
          </div>
          <p className="text-xs font-black text-rose-500 uppercase tracking-widest">Research Center | {metadata.name}</p>
          {metadata.officialUrl && (
            <p className="text-xs text-slate-400 font-mono mt-2 truncate font-bold">Source: {metadata.officialUrl}</p>
          )}
        </header>

        {/* Module Switcher */}
        <nav className="flex border-b border-slate-800 overflow-x-auto no-scrollbar" aria-label="Analysis modules">
          {(['connectivity', 'water', 'traffic', 'emergency'] as AnalysisModule[]).map(mod => (
            <button
              key={mod}
              onClick={() => setActiveModule(mod)}
              className={`flex-1 min-w-[100px] py-5 text-xs font-black uppercase tracking-widest transition-all focus-visible:bg-slate-900 ${
                activeModule === mod ? 'text-white border-b-2 border-rose-500 bg-slate-900' : 'text-slate-400 hover:text-slate-200'
              }`}
              aria-current={activeModule === mod ? 'page' : undefined}
            >
              {mod}
            </button>
          ))}
        </nav>

        <div className="flex-1 overflow-y-auto p-6 space-y-8 scrollbar-thin scrollbar-thumb-slate-800">

          {activeModule === 'emergency' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-left duration-300">
              <section className="space-y-4">
                <div className="flex items-center justify-between">
                  <div>
                    <h3 className="text-xs font-black text-rose-500 uppercase tracking-widest mb-1">Neighborhood B-LAN Control</h3>
                    <a 
                      href="https://github.com/ADD12/b-lan" 
                      target="_blank" 
                      className="text-xs font-black text-blue-400 hover:text-blue-300 transition-colors uppercase underline underline-offset-2"
                    >
                      B-LAN Technical Spec ↗
                    </a>
                  </div>
                  <span className="text-xs text-slate-400 font-black uppercase">{neighborhoods.length} Active Hubs</span>
                </div>

                <div className="grid grid-cols-1 gap-3">
                  {neighborhoods.map(n => (
                    <div 
                      key={n.name} 
                      className={`p-4 bg-slate-900 border rounded-2xl transition-all duration-300 ${
                        n.status === 'stable' ? 'border-emerald-500/40 shadow-[0_0_15px_rgba(16,185,129,0.1)]' : 
                        n.status === 'degraded' ? 'border-amber-500/40 shadow-[0_0_15px_rgba(245,158,11,0.1)]' : 
                        'border-rose-600 shadow-[0_0_15px_rgba(244,63,94,0.2)]'
                      }`}
                    >
                      <div className="flex justify-between items-start mb-4">
                        <div className="flex-1 min-w-0 pr-2">
                          <span className="text-xs font-black text-white uppercase block mb-2 truncate tracking-tight">{n.name}</span>

                          {/* Enhanced Status Badge */}
                          <div className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[11px] font-black uppercase tracking-tight transition-all duration-300 ${
                            n.status === 'stable' ? 'bg-emerald-600 text-white shadow-[0_0_10px_rgba(16,185,129,0.4)]' : 
                            n.status === 'degraded' ? 'bg-amber-500 text-slate-950 shadow-[0_0_10px_rgba(245,158,11,0.4)]' : 
                            'bg-rose-700 text-white animate-pulse shadow-[0_0_15px_rgba(225,29,72,0.6)]'
                          }`}>
                            <span className="text-xs" aria-hidden="true">
                              {n.status === 'stable' ? '✓' : n.status === 'degraded' ? '⚠' : '✕'}
                            </span>
                            {n.status}
                          </div>
                        </div>

                        <div className="flex gap-2 shrink-0">
                          <button 
                            onClick={() => healSector(n.name)}
                            title={`Heal Sector: ${n.name}`}
                            className="w-8 h-8 rounded-lg bg-emerald-600 text-white flex items-center justify-center hover:bg-emerald-500 transition-all active:scale-90 border border-emerald-400/20"
                            aria-label={`Restore B-LAN sector: ${n.name}`}
                          >
                            <span className="text-sm" aria-hidden="true">✨</span>
                          </button>
                          <button 
                            onClick={() => toggleIsolation(n.name)}
                            title={`Toggle Isolation: ${n.name}`}
                            className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all active:scale-90 border ${
                              n.status === 'isolated' 
                                ? 'bg-blue-600 text-white border-blue-400' 
                                : 'bg-rose-700 text-white hover:bg-rose-600 border-rose-500/30'
                            }`}
                            aria-label={`Toggle isolation for sector: ${n.name}`}
                          >
                            <span className="text-sm" aria-hidden="true">📡</span>
                          </button>
                        </div>
                      </div>

                      <div className="flex items-center gap-3">
                        <div className="flex-1 h-2 bg-slate-800 rounded-full overflow-hidden" aria-hidden="true">
                          <div 
                            className={`h-full transition-all duration-500 ${
                              n.health > 70 ? 'bg-emerald-500' : 
                              n.health > 30 ? 'bg-amber-500' : 
                              'bg-rose-600 animate-pulse'
                            }`} 
                            style={{ width: `${n.health}%` }}
                          ></div>
                        </div>
                        <span className="text-xs font-mono font-bold text-slate-300 w-16 text-right">
                          {n.nodes} Nodes
                        </span>
                      </div>
                    </div>
                  ))}
                </div>
              </section>

              <section className="space-y-4">
                <h3 className="text-xs font-black text-blue-400 uppercase tracking-widest">Resident Ping Data (Household)</h3>
                <div className="space-y-2 max-h-[160px] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-slate-700">
                  {residentPings.length === 0 && <p className="text-xs text-slate-500 italic font-bold">No household data synchronized yet...</p>}
                  {residentPings.map((p, i) => (
                    <div key={i} className="p-3 bg-slate-900 border border-slate-800 rounded-xl text-xs flex justify-between items-center transition-all hover:border-blue-500/50">
                      <div>
                        <span className="font-black text-slate-100">{p.householdId}</span>
                        <span className="mx-2 text-slate-700" aria-hidden="true">|</span>
                        <span className="text-slate-400 font-bold">{p.neighborhood}</span>
                      </div>
                      <div className="flex items-center gap-2">
                        {p.needs.length > 0 && <span className="bg-rose-700 text-white px-2 py-0.5 rounded text-[10px] font-black uppercase">Need: {p.needs[0]}</span>}
                        <span className={`w-2.5 h-2.5 rounded-full ${p.powerStatus === 'on' ? 'bg-emerald-500' : p.powerStatus === 'battery' ? 'bg-amber-500' : 'bg-rose-600'}`} aria-label={`Power status: ${p.powerStatus}`}></span>
                      </div>
                    </div>
                  ))}
                </div>
              </section>

              <button 
                onClick={runEmergencySync}
                disabled={simulationActive}
                className="w-full py-5 bg-rose-700 hover:bg-rose-600 disabled:opacity-50 text-white font-black rounded-2xl shadow-xl transition-all flex items-center justify-center gap-2 active:scale-95 focus-visible:ring-4 focus-visible:ring-rose-500/30"
              >
                <span aria-hidden="true">📡</span> BROADCAST GLOBAL B-LAN SYNC
              </button>
            </div>
          )}

          {activeModule === 'connectivity' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-left duration-300">
              <section className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-xs font-black text-blue-400 uppercase tracking-widest">Network Verification</h3>
                  <span className="text-xs font-black bg-blue-600/20 text-blue-400 px-3 py-1 rounded border border-blue-500/30 uppercase">HYBRID TOPOLOGY</span>
                </div>
                <div className="grid grid-cols-1 gap-2">
                  {networkNodes.map(node => (
                    <div key={node.id} className="p-4 bg-slate-900 border border-slate-800 rounded-2xl flex items-center justify-between">
                      <div className="flex items-center gap-4">
                        <div className={`w-3 h-3 rounded-full ${node.status === 'active' ? 'bg-emerald-500 shadow-[0_0_8px_#10b981]' : node.status === 'relay' ? 'bg-amber-500' : 'bg-rose-600 animate-pulse'}`} aria-hidden="true"></div>
                        <div>
                          <p className="text-xs font-black text-slate-100 uppercase tracking-tight">{node.id}</p>
                          <p className="text-xs text-slate-500 font-black uppercase tracking-widest">{node.type}</p>
                        </div>
                      </div>
                      <span className="text-xs font-mono font-black text-slate-300 bg-slate-800 px-2 py-1 rounded">{node.signal}%</span>
                    </div>
                  ))}
                </div>
              </section>

              <button 
                onClick={runConnectivitySim}
                disabled={simulationActive}
                className="w-full py-5 bg-blue-700 hover:bg-blue-600 disabled:opacity-50 text-white font-black rounded-2xl shadow-xl transition-all flex items-center justify-center gap-2 active:scale-95 focus-visible:ring-4 focus-visible:ring-blue-500/30"
              >
                <span aria-hidden="true">📡</span> RUN INFRASTRUCTURE STRESS TEST
              </button>
            </div>
          )}

          {activeModule === 'water' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-left duration-300">
              <section className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-xs font-black text-emerald-500 uppercase tracking-widest">Utility Consumption</h3>
                  <span className="text-xs font-black text-rose-500 uppercase">Live GIS Data</span>
                </div>
                <div className="p-8 bg-slate-900 border border-slate-800 rounded-3xl space-y-8">
                  <p className="text-sm text-slate-300 leading-relaxed font-bold italic">
                    Spatial analysis for {metadata.name} identifies localized consumption surges. Data is calibrated against portal historical metrics.
                  </p>
                  <div className="space-y-6">
                    {waterCauseData.map(item => (
                      <div key={item.label} className="space-y-2">
                        <div className="flex justify-between text-xs font-black uppercase tracking-widest">
                          <span className="text-slate-100">{item.label}</span>
                          <span className="text-slate-400">{item.value}%</span>
                        </div>
                        <div className="h-3 w-full bg-slate-800 rounded-full overflow-hidden" aria-hidden="true">
                          <div className={`h-full ${item.color}`} style={{ width: `${item.value}%` }}></div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </section>
            </div>
          )}

          {activeModule === 'traffic' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-left duration-300">
              <section className="space-y-6">
                <div className="space-y-6 p-6 bg-slate-900 rounded-3xl border border-slate-800 shadow-inner">
                  <div className="space-y-3">
                    <div className="flex justify-between items-center">
                      <label htmlFor="density-slider" className="text-xs font-black text-slate-300 uppercase tracking-widest">Traffic Density</label>
                      <span className="text-sm font-mono text-amber-500 font-black" aria-live="polite">{trafficDensity}%</span>
                    </div>
                    <input 
