import React, { useEffect, useRef, useState } from 'react';
import { GeoLocation } from '../types';

interface MapProps {
  location: GeoLocation;
  name: string;
  isExpanded?: boolean;
}

interface WeatherInfo {
  temp: number;
  windSpeed: number;
  conditionCode: number;
  conditionText: string;
}

export const Map: React.FC<MapProps> = ({ location, name, isExpanded }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const radarLayerRef = useRef<any>(null);
  const baseLayerRef = useRef<any>(null);

  // GIS Layer Refs
  const parcelsLayerRef = useRef<any>(null);
  const utilitiesLayerRef = useRef<any>(null);
  const greeneryLayerRef = useRef<any>(null);
  const householdLayerRef = useRef<any>(null);

  const [streetViewCoords, setStreetViewCoords] = useState<{lat: number, lng: number} | null>(null);
  const [weatherInfo, setWeatherInfo] = useState<WeatherInfo | null>(null);
  const [isSatellite, setIsSatellite] = useState(false);

  // Simulated and real layer visibility states
  const [layers, setLayers] = useState({
    parcels: true,
    utilities: true,
    greenery: true,
    health: true,
    households: true,
    weather: false
  });

  const getWeatherText = (code: number) => {
    if (code === 0) return 'Clear Sky';
    if (code <= 3) return 'Partly Cloudy';
    if (code <= 48) return 'Foggy';
    if (code <= 67) return 'Rain / Drizzle';
    if (code <= 77) return 'Snow';
    if (code <= 99) return 'Thunderstorm';
    return 'Overcast';
  };

  const fetchWeatherData = async () => {
    try {
      const response = await fetch(
        `https://api.open-meteo.com/v1/forecast?latitude=${location.lat}&longitude=${location.lng}&current_weather=true`
      );
      const data = await response.json();
      if (data.current_weather) {
        setWeatherInfo({
          temp: data.current_weather.temperature,
          windSpeed: data.current_weather.windspeed,
          conditionCode: data.current_weather.weathercode,
          conditionText: getWeatherText(data.current_weather.weathercode)
        });
      }
    } catch (err) {
      console.error("Weather sync failed", err);
    }
  };

  const updateRadarLayer = async () => {
    if (!mapRef.current) return;

    // Remove existing radar layer if any
    if (radarLayerRef.current) {
      mapRef.current.removeLayer(radarLayerRef.current);
      radarLayerRef.current = null;
    }

    if (layers.weather) {
      try {
        const rvResponse = await fetch('https://api.rainviewer.com/public/maps.json');
        const rvData = await rvResponse.json();
        const latestTs = rvData[rvData.length - 1];

        const radarUrl = `https://tilecache.rainviewer.com/v2/radar/${latestTs}/256/{z}/{x}/{y}/2/1_1.png`;
        radarLayerRef.current = (window as any).L.tileLayer(radarUrl, {
          opacity: 0.6,
          zIndex: 1000
        }).addTo(mapRef.current);
      } catch (err) {
        console.error("Radar sync failed", err);
      }
    }
  };

  // Switch Base Layer Logic
  useEffect(() => {
    if (!mapRef.current) return;
    const L = (window as any).L;

    if (baseLayerRef.current) {
      mapRef.current.removeLayer(baseLayerRef.current);
    }

    const streetUrl = 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png';
    const satelliteUrl = 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}';

    const attribution = isSatellite 
      ? 'Tiles &copy; Esri &mdash; Source: Esri, i-cubed, USDA, USGS, AEX, GeoEye, Getmapping, Aerogrid, IGN, IGP, UPR-EGP, and the GIS User Community'
      : '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors';

    baseLayerRef.current = L.tileLayer(isSatellite ? satelliteUrl : streetUrl, {
      attribution: attribution,
      maxZoom: 19
    }).addTo(mapRef.current);

    // Re-ensure the GIS layers are on top
    if (radarLayerRef.current) radarLayerRef.current.bringToFront();
  }, [isSatellite]);

  // Logic to manage Leaflet LayerGroups visibility based on state
  useEffect(() => {
    if (!mapRef.current) return;

    const handleLayerToggle = (layerRef: React.MutableRefObject<any>, visible: boolean) => {
      if (layerRef.current) {
        if (visible) {
          if (!mapRef.current.hasLayer(layerRef.current)) {
            layerRef.current.addTo(mapRef.current);
          }
        } else {
          if (mapRef.current.hasLayer(layerRef.current)) {
            mapRef.current.removeLayer(layerRef.current);
          }
        }
      }
    };

    handleLayerToggle(parcelsLayerRef, layers.parcels);
    handleLayerToggle(utilitiesLayerRef, layers.utilities);
    handleLayerToggle(greeneryLayerRef, layers.greenery);
    handleLayerToggle(householdLayerRef, layers.households);
  }, [layers, location]);

  useEffect(() => {
    fetchWeatherData();
  }, [location]);

  useEffect(() => {
    updateRadarLayer();
  }, [layers.weather]);

  useEffect(() => {
    if (mapContainerRef.current && !mapRef.current) {
      const L = (window as any).L;

      // Initialize map
      mapRef.current = L.map(mapContainerRef.current, {
        zoomControl: false 
      }).setView([location.lat, location.lng], 15);

      L.control.zoom({
        position: 'bottomleft'
      }).addTo(mapRef.current);

      // Create Layer Groups
      parcelsLayerRef.current = L.layerGroup();
      utilitiesLayerRef.current = L.layerGroup();
      greeneryLayerRef.current = L.layerGroup();
      householdLayerRef.current = L.layerGroup();

      // Add default visible layers
      if (layers.parcels) parcelsLayerRef.current.addTo(mapRef.current);
      if (layers.utilities) utilitiesLayerRef.current.addTo(mapRef.current);
      if (layers.greenery) greeneryLayerRef.current.addTo(mapRef.current);
      if (layers.households) householdLayerRef.current.addTo(mapRef.current);

      const addMarkerWithStreetView = (pos: [number, number], title: string, subtitle: string, group?: any) => {
        const marker = L.marker(pos);
        if (group) marker.addTo(group);
        else marker.addTo(mapRef.current);

        const popupContent = document.createElement('div');
        popupContent.className = 'p-1';
        popupContent.innerHTML = `
          <div class="mb-2">
            <b class="text-slate-900 block text-sm">${title}</b>
            <span class="text-slate-500 text-[10px] font-bold uppercase">${subtitle}</span>
          </div>
          <button class="street-view-btn w-full bg-blue-600 text-white text-[10px] font-black py-2 rounded-lg hover:bg-blue-700 transition-colors uppercase tracking-widest">
            Street View
          </button>
        `;

        const btn = popupContent.querySelector('.street-view-btn');
        btn?.addEventListener('click', () => {
          setStreetViewCoords({ lat: pos[0], lng: pos[1] });
          marker.closePopup();
        });

        marker.bindPopup(popupContent);
      };

      // Core Marker
      addMarkerWithStreetView([location.lat, location.lng], name, 'Digital Twin Core');

      // --- SIMULATED GIS GEOMETRY ---

      // Simulated Parcels (Blue outlines)
      const parcelStyle = { color: '#2563eb', weight: 1.5, fillOpacity: 0.1, fillColor: '#3b82f6' };
      const latOffset = 0.001;
      const lngOffset = 0.0015;
      for (let i = -2; i <= 2; i++) {
        for (let j = -2; j <= 2; j++) {
          const bounds = [
            [location.lat + i * latOffset, location.lng + j * lngOffset],
            [location.lat + (i + 1) * latOffset, location.lng + (j + 1) * lngOffset]
          ];
          L.rectangle(bounds as any, parcelStyle).addTo(parcelsLayerRef.current);
        }
      }

      // Simulated Utilities (Amber dashed lines)
      const utilityStyle = { color: '#f59e0b', weight: 3, dashArray: '5, 10', opacity: 0.8 };
      L.polyline([
        [location.lat - 0.005, location.lng],
        [location.lat + 0.005, location.lng]
      ], utilityStyle).addTo(utilitiesLayerRef.current);
      L.polyline([
        [location.lat, location.lng - 0.008],
        [location.lat, location.lng + 0.008]
      ], utilityStyle).addTo(utilitiesLayerRef.current);

      // Simulated Green Space (Emerald polygons)
      const greeneryStyle = { color: '#059669', weight: 0, fillOpacity: 0.4, fillColor: '#10b981' };
      L.circle([location.lat + 0.004, location.lng + 0.004], { radius: 150, ...greeneryStyle }).addTo(greeneryLayerRef.current);
      L.circle([location.lat - 0.003, location.lng - 0.005], { radius: 200, ...greeneryStyle }).addTo(greeneryLayerRef.current);

      // Simulated Infrastructure Nodes
      addMarkerWithStreetView([location.lat + 0.005, location.lng + 0.005], `${name} Health Alpha`, 'Primary Health Node');
      addMarkerWithStreetView([location.lat - 0.005, location.lng - 0.003], `${name} Health Beta`, 'Secondary Health Node');

      // Household Pings (Simulated)
      const pings: [number, number][] = [
        [location.lat + 0.002, location.lng + 0.002],
        [location.lat - 0.002, location.lng + 0.004],
        [location.lat + 0.003, location.lng - 0.001],
      ];
      pings.forEach((pos, i) => {
        addMarkerWithStreetView(pos, `Relay #${i+102}`, 'Resident B-LAN Relay', householdLayerRef.current);
      });
    }

    if (mapRef.current) {
      setTimeout(() => {
        mapRef.current.invalidateSize();
        if (isExpanded) {
          mapRef.current.setZoom(17, { animate: true });
        } else {
          mapRef.current.setZoom(15, { animate: true });
        }
      }, 500);
    }
  }, [location, name, isExpanded]);

  const toggleLayer = (layer: keyof typeof layers) => {
    setLayers(prev => ({ ...prev, [layer]: !prev[layer] }));
  };

  const getStreetViewConfig = (coords: {lat: number, lng: number}) => {
    const y = location.lat - coords.lat;
    const x = location.lng - coords.lng;
    let heading = Math.atan2(x, y) * (180 / Math.PI);
    if (heading < 0) heading += 360;

    if (Math.abs(y) < 0.00001 && Math.abs(x) < 0.00001) {
      heading = 315;
    }

    const pitch = (coords.lat % 0.01) * 2000 - 10;

    return { 
      heading: Math.round(heading), 
      pitch: Math.round(pitch),
      fov: 40
    };
  };

  const streetViewConfig = streetViewCoords ? getStreetViewConfig(streetViewCoords) : null;

  return (
    <div className="w-full h-full relative bg-slate-200 transition-all duration-500">
      <div ref={mapContainerRef} className="w-full h-full" />

      {/* HUD Overlays */}
      <div className="absolute top-4 left-4 z-[1000] flex flex-col gap-2 pointer-events-none">
        <div className="glass-panel px-4 py-2.5 rounded-2xl text-[12px] font-black text-slate-800 shadow-xl border border-white/60 flex items-center gap-2.5 pointer-events-auto">
          <span className="w-2.5 h-2.5 bg-emerald-600 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.6)]" aria-hidden="true"></span>
          OFFICIAL GIS DATA SOURCE
        </div>

        {/* Satellite Toggle Button - ADA Compliant */}
        <button 
          onClick={() => setIsSatellite(!isSatellite)}
          className={`glass-panel px-4 py-3 rounded-2xl shadow-xl border flex items-center gap-3 pointer-events-auto transition-all focus-visible:ring-4 focus-visible:ring-blue-600/30 ${isSatellite ? 'bg-slate-900 border-blue-500 text-white' : 'bg-white border-white/60 text-slate-900'}`}
          aria-label={isSatellite ? "Switch to Street View" : "Switch to Satellite View"}
        >
          <span className="text-xl" aria-hidden="true">{isSatellite ? '🏙️' : '🛰️'}</span>
          <div className="text-left">
            <p className={`text-[10px] font-black uppercase tracking-widest leading-none mb-0.5 ${isSatellite ? 'text-blue-400' : 'text-slate-500'}`}>Map Type</p>
            <p className="text-xs font-black uppercase">{isSatellite ? 'Satellite' : 'Street'}</p>
          </div>
        </button>

        {weatherInfo && (
          <div className="glass-panel px-4 py-3 rounded-2xl shadow-xl border border-white/60 flex flex-col gap-1 pointer-events-auto bg-slate-900/10 backdrop-blur-md">
            <div className="flex items-center gap-3">
              <span className="text-xl" aria-hidden="true">
                {weatherInfo.conditionCode < 3 ? '☀️' : weatherInfo.conditionCode < 50 ? '☁️' : '🌧️'}
              </span>
              <div>
                <p className="text-[12px] font-black text-slate-900 uppercase tracking-widest">{weatherInfo.conditionText}</p>
                <div className="flex items-baseline gap-1">
                  <span className="text-lg font-black text-slate-900 leading-none">{weatherInfo.temp}°C</span>
                  <span className="text-[10px] font-bold text-slate-600 uppercase tracking-tighter">Local Temp</span>
                </div>
              </div>
            </div>
            <div className="mt-1 pt-1 border-t border-slate-300/50 flex justify-between items-center">
               <span className="text-[10px] font-black text-slate-500 uppercase">Wind Velocity</span>
               <span className="text-[10px] font-mono font-bold text-slate-800">{weatherInfo.windSpeed} km/h</span>
            </div>
          </div>
        )}
      </div>

      {/* Street View Embed Overlay */}
      {streetViewCoords && streetViewConfig && (
        <div className="absolute inset-0 z-[3000] bg-slate-900 animate-in fade-in zoom-in-95 duration-300">
          <header className="absolute top-4 left-4 right-4 z-[3100] flex justify-between items-center px-6 py-3 bg-white/90 backdrop-blur-md rounded-2xl border border-white/50 shadow-2xl">
            <div className="flex items-center gap-4">
              <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white text-sm" aria-hidden="true">👁️</div>
              <div>
                <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Spatial Immersion</p>
                <h4 className="text-[12px] font-bold text-slate-900">Digital Street Analysis Mode</h4>
              </div>
            </div>
            <div className="flex items-center gap-4">
              <div className="hidden sm:flex flex-col text-right">
                <span className="text-[10px] font-black text-slate-500 uppercase">View Delta</span>
                <span className="text-[11px] font-mono font-bold text-slate-800">H: {streetViewConfig.heading}° | P: {streetViewConfig.pitch}°</span>
              </div>
              <button 
                onClick={() => setStreetViewCoords(null)}
                className="w-10 h-10 flex items-center justify-center bg-slate-100 hover:bg-slate-200 text-slate-900 rounded-full font-black text-lg transition-all focus-visible:ring-4 focus-visible:ring-slate-400"
                aria-label="Exit Street View"
              >
                ✕
              </button>
            </div>
          </header>

          <iframe
            title="Google Street View"
            className="w-full h-full border-0"
            loading="lazy"
            allowFullScreen
            src={`https://www.google.com/maps/embed/v1/streetview?key=${process.env.API_KEY}&location=${streetViewCoords.lat},${streetViewCoords.lng}&heading=${streetViewConfig.heading}&pitch=${streetViewConfig.pitch}&fov=${streetViewConfig.fov}`}
          ></iframe>

          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-[3100] px-6 py-2 bg-slate-900/90 backdrop-blur-md border border-white/10 rounded-2xl text-[10px] font-mono text-white shadow-2xl flex items-center gap-4">
            <div className="flex items-center gap-2">
              <span className="w-2 h-2 bg-blue-400 rounded-full animate-pulse" aria-hidden="true"></span>
              LIVE PERSPECTIVE CALIBRATED
            </div>
            <div className="w-px h-3 bg-white/20" aria-hidden="true"></div>
            <span>LAT: {streetViewCoords.lat.toFixed(6)}</span>
            <span>LNG: {streetViewCoords.lng.toFixed(6)}</span>
          </div>
        </div>
      )}

      {isExpanded && !streetViewCoords && (
        <div className="absolute bottom-6 right-6 z-[1000] glass-panel p-5 rounded-[2rem] border border-white/60 shadow-2xl animate-in slide-in-from-bottom duration-500 w-[300px]" role="complementary" aria-label="Map Layer Legend">
          <div className="flex items-center justify-between mb-4">
            <h4 className="text-[12px] font-black text-slate-600 uppercase tracking-widest">Urban Layer Legend</h4>
            <div className="text-[10px] font-black text-slate-500 bg-slate-100 px-2 py-0.5 rounded-full uppercase tracking-tighter">Official GIS</div>
          </div>

          <div className="space-y-3">
            <div className={`group flex items-start gap-3 p-3 rounded-2xl transition-all cursor-pointer focus-visible:ring-2 focus-visible:ring-blue-600/30 ${layers.parcels ? 'bg-blue-600/10' : 'opacity-50 grayscale'}`}
                 role="button"
                 tabIndex={0}
                 aria-pressed={layers.parcels}
                 onKeyDown={(e) => e.key === 'Enter' && toggleLayer('parcels')}
                 onClick={() => toggleLayer('parcels')}>
              <div className="w-5 h-5 bg-blue-500/10 border-2 border-blue-700 rounded-md shrink-0 mt-0.5" aria-hidden="true"></div>
              <div>
                <span className="text-[12px] font-black text-slate-900 block mb-0.5 uppercase tracking-tight">Parcel Boundaries</span>
              </div>
            </div>

            <div className={`group flex items-start gap-3 p-3 rounded-2xl transition-all cursor-pointer focus-visible:ring-2 focus-visible:ring-amber-600/30 ${layers.utilities ? 'bg-amber-600/10' : 'opacity-50 grayscale'}`}
                 role="button"
                 tabIndex={0}
                 aria-pressed={layers.utilities}
                 onKeyDown={(e) => e.key === 'Enter' && toggleLayer('utilities')}
                 onClick={() => toggleLayer('utilities')}>
              <div className="w-5 h-5 bg-amber-500/10 border-2 border-amber-700 rounded-md shrink-0 mt-0.5" aria-hidden="true"></div>
              <div>
                <span className="text-[12px] font-black text-slate-900 block mb-0.5 uppercase tracking-tight">Underground Utilities</span>
              </div>
            </div>

            <div className={`group flex items-start gap-3 p-3 rounded-2xl transition-all cursor-pointer focus-visible:ring-2 focus-visible:ring-emerald-600/30 ${layers.greenery ? 'bg-emerald-600/10' : 'opacity-50 grayscale'}`}
                 role="button"
                 tabIndex={0}
                 aria-pressed={layers.greenery}
                 onKeyDown={(e) => e.key === 'Enter' && toggleLayer('greenery')}
                 onClick={() => toggleLayer('greenery')}>
              <div className="w-5 h-5 bg-emerald-500/10 border-2 border-emerald-700 rounded-md shrink-0 mt-0.5" aria-hidden="true"></div>
              <div>
                <span className="text-[12px] font-black text-slate-900 block mb-0.5 uppercase tracking-tight">Public Green Space</span>
              </div>
            </div>

            <div className="h-px bg-slate-200 my-1 mx-2" aria-hidden="true"></div>

            <div className={`group flex items-start gap-3 p-3 rounded-2xl transition-all cursor-pointer focus-visible:ring-2 focus-visible:ring-rose-600/30 ${layers.weather ? 'bg-rose-600/10' : 'opacity-50 grayscale'}`}
                 role="button"
                 tabIndex={0}
                 aria-pressed={layers.weather}
                 onKeyDown={(e) => e.key === 'Enter' && toggleLayer('weather')}
                 onClick={() => toggleLayer('weather')}>
              <div className="w-5 h-5 bg-rose-500/10 border-2 border-rose-700 rounded-md shrink-0 mt-0.5" aria-hidden="true"></div>
              <div>
                <span className="text-[12px] font-black text-slate-900 block mb-0.5 uppercase tracking-tight">Tactical Radar</span>
              </div>
            </div>

            <div className={`group flex items-start gap-3 p-3 rounded-2xl transition-all cursor-pointer focus-visible:ring-2 focus-visible:ring-slate-900/30 ${layers.households ? 'bg-slate-900/10' : 'opacity-50 grayscale'}`}
                 role="button"
                 tabIndex={0}
                 aria-pressed={layers.households}
                 onKeyDown={(e) => e.key === 'Enter' && toggleLayer('households')}
                 onClick={() => toggleLayer('households')}>
              <div className="w-5 h-5 bg-slate-900/10 border-2 border-slate-900 rounded-md shrink-0 mt-0.5" aria-hidden="true"></div>
              <div>
                <span className="text-[12px] font-black text-slate-900 block mb-0.5 uppercase tracking-tight">Resident B-LAN</span>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { GeoLocation } from '../types';

interface MapProps {
  location: GeoLocation;
  name: string;
  isExpanded?: boolean;
}

interface WeatherInfo {
  temp: number;
  windSpeed: number;
  conditionCode: number;
  conditionText: string;
}

export const Map: React.FC<MapProps> = ({ location, name, isExpanded }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const radarLayerRef = useRef<any>(null);
  const baseLayerRef = useRef<any>(null);

  // GIS Layer Refs
  const parcelsLayerRef = useRef<any>(null);
  const utilitiesLayerRef = useRef<any>(null);
  const greeneryLayerRef = useRef<any>(null);
  const householdLayerRef = useRef<any>(null);
  const heatmapLayerRef = useRef<any>(null);

  const [streetViewCoords, setStreetViewCoords] = useState<{lat: number, lng: number} | null>(null);
  const [weatherInfo, setWeatherInfo] = useState<WeatherInfo | null>(null);
  const [isSatellite, setIsSatellite] = useState(false);

  // Simulated and real layer visibility states
  const [layers, setLayers] = useState({
    parcels: true,
    utilities: true,
    greenery: true,
    health: true,
    households: true,
    weather: false,
    heatmap: true
  });

  const getWeatherText = (code: number) => {
    if (code === 0) return 'Clear Sky';
    if (code <= 3) return 'Partly Cloudy';
    if (code <= 48) return 'Foggy';
    if (code <= 67) return 'Rain / Drizzle';
    if (code <= 77) return 'Snow';
    if (code <= 99) return 'Thunderstorm';
    return 'Overcast';
  };

  const fetchWeatherData = async () => {
    try {
      const response = await fetch(
        `https://api.open-meteo.com/v1/forecast?latitude=${location.lat}&longitude=${location.lng}&current_weather=true`
      );
      const data = await response.json();
      if (data.current_weather) {
        setWeatherInfo({
          temp: data.current_weather.temperature,
          windSpeed: data.current_weather.windspeed,
          conditionCode: data.current_weather.weathercode,
          conditionText: getWeatherText(data.current_weather.weathercode)
        });
      }
    } catch (err) {
      console.error("Weather sync failed", err);
    }
  };

  const updateRadarLayer = async () => {
    if (!mapRef.current) return;

    // Remove existing radar layer if any
    if (radarLayerRef.current) {
      mapRef.current.removeLayer(radarLayerRef.current);
      radarLayerRef.current = null;
    }

    if (layers.weather) {
      try {
        const rvResponse = await fetch('https://api.rainviewer.com/public/maps.json');
        const rvData = await rvResponse.json();
        const latestTs = rvData[rvData.length - 1];

        const radarUrl = `https://tilecache.rainviewer.com/v2/radar/${latestTs}/256/{z}/{x}/{y}/2/1_1.png`;
        radarLayerRef.current = (window as any).L.tileLayer(radarUrl, {
          opacity: 0.6,
          zIndex: 1000
        }).addTo(mapRef.current);
      } catch (err) {
        console.error("Radar sync failed", err);
      }
    }
  };

  // Switch Base Layer Logic
  useEffect(() => {
    if (!mapRef.current) return;
    const L = (window as any).L;

    if (baseLayerRef.current) {
      mapRef.current.removeLayer(baseLayerRef.current);
    }

    const streetUrl = 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png';
    const satelliteUrl = 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}';

    const attribution = isSatellite 
      ? 'Tiles &copy; Esri &mdash; Source: Esri, i-cubed, USDA, USGS, AEX, GeoEye, Getmapping, Aerogrid, IGN, IGP, UPR-EGP, and the GIS User Community'
      : '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors';

    baseLayerRef.current = L.tileLayer(isSatellite ? satelliteUrl : streetUrl, {
      attribution: attribution,
      maxZoom: 19
    }).addTo(mapRef.current);

    // Re-ensure the GIS layers are on top
    if (radarLayerRef.current) radarLayerRef.current.bringToFront();
  }, [isSatellite]);

  // Logic to manage Leaflet LayerGroups visibility based on state
  useEffect(() => {
    if (!mapRef.current) return;

    const handleLayerToggle = (layerRef: React.MutableRefObject<any>, visible: boolean) => {
      if (layerRef.current) {
        if (visible) {
          if (!mapRef.current.hasLayer(layerRef.current)) {
            layerRef.current.addTo(mapRef.current);
          }
        } else {
          if (mapRef.current.hasLayer(layerRef.current)) {
            mapRef.current.removeLayer(layerRef.current);
          }
        }
      }
    };

    handleLayerToggle(parcelsLayerRef, layers.parcels);
    handleLayerToggle(utilitiesLayerRef, layers.utilities);
    handleLayerToggle(greeneryLayerRef, layers.greenery);
    handleLayerToggle(householdLayerRef, layers.households);
    handleLayerToggle(heatmapLayerRef, layers.heatmap);
  }, [layers, location]);

  useEffect(() => {
    fetchWeatherData();
  }, [location]);

  useEffect(() => {
    updateRadarLayer();
  }, [layers.weather]);

  useEffect(() => {
    if (mapContainerRef.current && !mapRef.current) {
      const L = (window as any).L;

      // Initialize map
      mapRef.current = L.map(mapContainerRef.current, {
        zoomControl: false 
      }).setView([location.lat, location.lng], 15);

      L.control.zoom({
        position: 'bottomleft'
      }).addTo(mapRef.current);

      // Create Layer Groups
      parcelsLayerRef.current = L.layerGroup();
      utilitiesLayerRef.current = L.layerGroup();
      greeneryLayerRef.current = L.layerGroup();
      householdLayerRef.current = L.layerGroup();

      // Add default visible layers
      if (layers.parcels) parcelsLayerRef.current.addTo(mapRef.current);
      if (layers.utilities) utilitiesLayerRef.current.addTo(mapRef.current);
      if (layers.greenery) greeneryLayerRef.current.addTo(mapRef.current);
      if (layers.households) householdLayerRef.current.addTo(mapRef.current);

      const addMarkerWithStreetView = (pos: [number, number], title: string, subtitle: string, group?: any) => {
        const marker = L.marker(pos);
        if (group) marker.addTo(group);
        else marker.addTo(mapRef.current);

        const popupContent = document.createElement('div');
        popupContent.className = 'p-1';
        popupContent.innerHTML = `
          <div class="mb-2">
            <b class="text-slate-900 block text-sm">${title}</b>
            <span class="text-slate-500 text-[10px] font-bold uppercase">${subtitle}</span>
          </div>
          <button class="street-view-btn w-full bg-blue-600 text-white text-[10px] font-black py-2 rounded-lg hover:bg-blue-700 transition-colors uppercase tracking-widest">
            Street View
          </button>
        `;

        const btn = popupContent.querySelector('.street-view-btn');
        btn?.addEventListener('click', () => {
          setStreetViewCoords({ lat: pos[0], lng: pos[1] });
          marker.closePopup();
        });

        marker.bindPopup(popupContent);
      };

      // Core Marker
      addMarkerWithStreetView([location.lat, location.lng], name, 'Digital Twin Core');

      // --- SIMULATED GIS GEOMETRY ---

      // Simulated Parcels (Blue outlines)
      const parcelStyle = { color: '#2563eb', weight: 1.5, fillOpacity: 0.1, fillColor: '#3b82f6' };
      const latOffset = 0.001;
      const lngOffset = 0.0015;
      for (let i = -2; i <= 2; i++) {
        for (let j = -2; j <= 2; j++) {
          const bounds = [
            [location.lat + i * latOffset, location.lng + j * lngOffset],
            [location.lat + (i + 1) * latOffset, location.lng + (j + 1) * lngOffset]
          ];
          L.rectangle(bounds as any, parcelStyle).addTo(parcelsLayerRef.current);
        }
      }

      // Simulated Utilities (Amber dashed lines)
      const utilityStyle = { color: '#f59e0b', weight: 3, dashArray: '5, 10', opacity: 0.8 };
      L.polyline([
        [location.lat - 0.005, location.lng],
        [location.lat + 0.005, location.lng]
      ], utilityStyle).addTo(utilitiesLayerRef.current);
      L.polyline([
        [location.lat, location.lng - 0.008],
        [location.lat, location.lng + 0.008]
      ], utilityStyle).addTo(utilitiesLayerRef.current);

      // Simulated Green Space (Emerald polygons)
      const greeneryStyle = { color: '#059669', weight: 0, fillOpacity: 0.4, fillColor: '#10b981' };
      L.circle([location.lat + 0.004, location.lng + 0.004], { radius: 150, ...greeneryStyle }).addTo(greeneryLayerRef.current);
      L.circle([location.lat - 0.003, location.lng - 0.005], { radius: 200, ...greeneryStyle }).addTo(greeneryLayerRef.current);

      // Simulated Infrastructure Nodes
      addMarkerWithStreetView([location.lat + 0.005, location.lng + 0.005], `${name} Health Alpha`, 'Primary Health Node');
      addMarkerWithStreetView([location.lat - 0.005, location.lng - 0.003], `${name} Health Beta`, 'Secondary Health Node');

      // Household Pings (Simulated)
      const pings: [number, number][] = [
        [location.lat + 0.002, location.lng + 0.002],
        [location.lat - 0.002, location.lng + 0.004],
        [location.lat + 0.003, location.lng - 0.001],
      ];
      pings.forEach((pos, i) => {
        addMarkerWithStreetView(pos, `Relay #${i+102}`, 'Resident B-LAN Relay', householdLayerRef.current);
      });

      // --- HEATMAP INTEGRATION ---
      // Collect points from pings and some extra simulated hotspots
      const heatmapPoints = [
        ...pings.map(p => [p[0], p[1], 0.8]), // Households
        [location.lat + 0.003, location.lng + 0.003, 1.0], // High density alert
        [location.lat - 0.004, location.lng + 0.002, 0.7], // Utility stress point
        [location.lat + 0.001, location.lng - 0.002, 0.5],
        [location.lat + 0.005, location.lng + 0.001, 0.9],
        [location.lat - 0.001, location.lng + 0.005, 0.6]
      ];

      if (L.heatLayer) {
        heatmapLayerRef.current = L.heatLayer(heatmapPoints, {
          radius: 25,
          blur: 15,
          maxZoom: 17,
          gradient: { 0.4: 'blue', 0.65: 'lime', 1: 'red' }
        });
        if (layers.heatmap) heatmapLayerRef.current.addTo(mapRef.current);
      }
    }

    if (mapRef.current) {
      setTimeout(() => {
        mapRef.current.invalidateSize();
        if (isExpanded) {
          mapRef.current.setZoom(17, { animate: true });
        } else {
          mapRef.current.setZoom(15, { animate: true });
        }
      }, 500);
    }
  }, [location, name, isExpanded]);

  const toggleLayer = (layer: keyof typeof layers) => {
    setLayers(prev => ({ ...prev, [layer]: !prev[layer] }));
  };

  const getStreetViewConfig = (coords: {lat: number, lng: number}) => {
    const y = location.lat - coords.lat;
    const x = location.lng - coords.lng;
    let heading = Math.atan2(x, y) * (180 / Math.PI);
    if (heading < 0) heading += 360;

    if (Math.abs(y) < 0.00001 && Math.abs(x) < 0.00001) {
      heading = 315;
    }

    const pitch = (coords.lat % 0.01) * 2000 - 10;

    return { 
      heading: Math.round(heading), 
      pitch: Math.round(pitch),
      fov: 40
    };
  };

  const streetViewConfig = streetViewCoords ? getStreetViewConfig(streetViewCoords) : null;

  return (
    <div className="w-full h-full relative bg-slate-200 transition-all duration-500">
      <div ref={mapContainerRef} className="w-full h-full" />

      {/* HUD Overlays */}
      <div className="absolute top-4 left-4 z-[1000] flex flex-col gap-2 pointer-events-none">
        <div className="glass-panel px-4 py-2.5 rounded-2xl text-[12px] font-black text-slate-800 shadow-xl border border-white/60 flex items-center gap-2.5 pointer-events-auto">
          <span className="w-2.5 h-2.5 bg-emerald-600 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.6)]" aria-hidden="true"></span>
          OFFICIAL GIS DATA SOURCE
        </div>

        {/* Satellite Toggle Button - ADA Compliant */}
        <button 
          onClick={() => setIsSatellite(!isSatellite)}
          className={`glass-panel px-4 py-3 rounded-2xl shadow-xl border flex items-center gap-3 pointer-events-auto transition-all focus-visible:ring-4 focus-visible:ring-blue-600/30 ${isSatellite ? 'bg-slate-900 border-blue-500 text-white' : 'bg-white border-white/60 text-slate-900'}`}
          aria-label={isSatellite ? "Switch to Street View" : "Switch to Satellite View"}
        >
          <span className="text-xl" aria-hidden="true">{isSatellite ? '🏙️' : '🛰️'}</span>
          <div className="text-left">
            <p className={`text-[10px] font-black uppercase tracking-widest leading-none mb-0.5 ${isSatellite ? 'text-blue-400' : 'text-slate-500'}`}>Map Type</p>
            <p className="text-xs font-black uppercase">{isSatellite ? 'Satellite' : 'Street'}</p>
          </div>
        </button>

        {weatherInfo && (
          <div className="glass-panel px-4 py-3 rounded-2xl shadow-xl border border-white/60 flex flex-col gap-1 pointer-events-auto bg-slate-900/10 backdrop-blur-md">
            <div className="flex items-center gap-3">
              <span className="text-xl" aria-hidden="true">
                {weatherInfo.conditionCode < 3 ? '☀️' : weatherInfo.conditionCode < 50 ? '☁️' : '🌧️'}
              </span>
              <div>
                <p className="text-[12px] font-black text-slate-900 uppercase tracking-widest">{weatherInfo.conditionText}</p>
                <div className="flex items-baseline gap-1">
                  <span className="text-lg font-black text-slate-900 leading-none">{weatherInfo.temp}°C</span>
                  <span className="text-[10px] font-bold text-slate-600 uppercase tracking-tighter">Local Temp</span>
                </div>
              </div>
            </div>
            <div className="mt-1 pt-1 border-t border-slate-300/50 flex justify-between items-center">
               <span className="text-[10px] font-black text-slate-500 uppercase">Wind Velocity</span>
               <span className="text-[10px] font-mono font-bold text-slate-800">{weatherInfo.windSpeed} km/h</span>
            </div>
          </div>
        )}
      </div>

      {/* Street View Embed Overlay */}
      {streetViewCoords && streetViewConfig && (
        <div className="absolute inset-0 z-[3000] bg-slate-900 animate-in fade-in zoom-in-95 duration-300">
          <header className="absolute top-4 left-4 right-4 z-[3100] flex justify-between items-center px-6 py-3 bg-white/90 backdrop-blur-md rounded-2xl border border-white/50 shadow-2xl">
            <div className="flex items-center gap-4">
              <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white text-sm" aria-hidden="true">👁️</div>
              <div>
                <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Spatial Immersion</p>
                <h4 className="text-[12px] font-bold text-slate-900">Digital Street Analysis Mode</h4>
              </div>
            </div>
            <div className="flex items-center gap-4">
              <div className="hidden sm:flex flex-col text-right">
                <span className="text-[10px] font-black text-slate-500 uppercase">View Delta</span>
                <span className="text-[11px] font-mono font-bold text-slate-800">H: {streetViewConfig.heading}° | P: {streetViewConfig.pitch}°</span>
              </div>
              <button 
                onClick={() => setStreetViewCoords(null)}
                className="w-10 h-10 flex items-center justify-center bg-slate-100 hover:bg-slate-200 text-slate-900 rounded-full font-black text-lg transition-all focus-visible:ring-4 focus-visible:ring-slate-400"
                aria-label="Exit Street View"
