    const y = location.lat - coords.lat;
    const x = location.lng - coords.lng;
    let heading = Math.atan2(x, y) * (180 / Math.PI);
    if (heading < 0) heading += 360;
    if (Math.abs(y) < 0.00001 && Math.abs(x) < 0.00001) heading = 315;
    const pitch = (coords.lat % 0.01) * 2000 - 10;
    return { heading: Math.round(heading), pitch: Math.round(pitch), fov: 40 };
  };

