import React, { useEffect, useRef, useState } from 'react';
import { GeoLocation } from '../types';

interface MapProps {
  location: GeoLocation;
  name: string;
  isExpanded?: boolean;
}

interface WeatherInfo {
  temp: number;
  windSpeed: number;
  conditionCode: number;
  conditionText: string;
}

export const Map: React.FC<MapProps> = ({ location, name, isExpanded }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const radarLayerRef = useRef<any>(null);
  const baseLayerRef = useRef<any>(null);

  // GIS Layer Groups
  const parcelsLayerRef = useRef<any>(null);
  const utilitiesLayerRef = useRef<any>(null);
  const greeneryLayerRef = useRef<any>(null);
  const householdLayerRef = useRef<any>(null);
  const heatmapLayerRef = useRef<any>(null);

  const [streetViewCoords, setStreetViewCoords] = useState<{lat: number, lng: number} | null>(null);
  const [weatherInfo, setWeatherInfo] = useState<WeatherInfo | null>(null);
  const [isSatellite, setIsSatellite] = useState(false);

  const [layers, setLayers] = useState({
    parcels: true,
    utilities: true,
    greenery: true,
    health: true,
    households: true,
    weather: false,
    heatmap: true
  });

  const getWeatherText = (code: number) => {
    if (code === 0) return 'Clear Sky';
    if (code <= 3) return 'Partly Cloudy';
    if (code <= 48) return 'Foggy';
    if (code <= 67) return 'Rain / Drizzle';
    if (code <= 77) return 'Snow';
    if (code <= 99) return 'Thunderstorm';
    return 'Overcast';
  };

  const fetchWeatherData = async () => {
    try {
      const response = await fetch(
        `https://api.open-meteo.com/v1/forecast?latitude=${location.lat}&longitude=${location.lng}&current_weather=true`
      );
      const data = await response.json();
      if (data.current_weather) {
        setWeatherInfo({
          temp: data.current_weather.temperature,
          windSpeed: data.current_weather.windspeed,
          conditionCode: data.current_weather.weathercode,
          conditionText: getWeatherText(data.current_weather.weathercode)
        });
      }
    } catch (err) {
      console.error("Weather sync failed", err);
    }
  };

  // Switch Base Layer Logic
  useEffect(() => {
    if (!mapRef.current) return;
    const L = (window as any).L;

    if (baseLayerRef.current) {
      mapRef.current.removeLayer(baseLayerRef.current);
    }

    const streetUrl = 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png';
    const satelliteUrl = 'https://{s}.google.com/vt/lyrs=y&x={x}&y={y}&z={z}';

    const attribution = isSatellite 
      ? 'Map data &copy; Google'
      : '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors';

    baseLayerRef.current = L.tileLayer(isSatellite ? satelliteUrl : streetUrl, {
      attribution: attribution,
      maxZoom: 20,
      subdomains: isSatellite ? ['mt0', 'mt1', 'mt2', 'mt3'] : ['a', 'b', 'c']
    }).addTo(mapRef.current);

    if (radarLayerRef.current) radarLayerRef.current.bringToFront();
  }, [isSatellite]);

  // Initial Map Load
  useEffect(() => {
    if (!mapContainerRef.current) return;
    const L = (window as any).L;
    if (!L) return;

    if (!mapRef.current) {
      mapRef.current = L.map(mapContainerRef.current, {
        zoomControl: false,
        layers: []
      }).setView([location.lat, location.lng], 15);

      L.control.zoom({ position: 'bottomleft' }).addTo(mapRef.current);

      // Create Layer Groups
      parcelsLayerRef.current = L.layerGroup();
      utilitiesLayerRef.current = L.layerGroup();
      greeneryLayerRef.current = L.layerGroup();
      householdLayerRef.current = L.layerGroup();

      // Simulated Data Setup
      const parcelStyle = { color: '#2563eb', weight: 2, fillOpacity: 0.15, fillColor: '#3b82f6' };
      for (let i = -1; i <= 1; i++) {
        for (let j = -1; j <= 1; j++) {
          L.rectangle([
            [location.lat + i * 0.001, location.lng + j * 0.0015],
            [location.lat + (i + 0.8) * 0.001, location.lng + (j + 0.8) * 0.0015]
          ], parcelStyle).addTo(parcelsLayerRef.current);
        }
      }

      const utilityStyle = { color: '#fbbf24', weight: 4, dashArray: '5, 10', opacity: 0.9 };
      L.polyline([[location.lat - 0.003, location.lng], [location.lat + 0.003, location.lng]], utilityStyle).addTo(utilitiesLayerRef.current);

      const pings: [number, number, number][] = [
        [location.lat + 0.001, location.lng + 0.001, 1],
        [location.lat - 0.001, location.lng - 0.001, 0.8],
        [location.lat + 0.002, location.lng - 0.001, 0.7],
        [location.lat, location.lng, 0.5]
      ];

      pings.forEach((p, idx) => {
        L.marker([p[0], p[1]]).addTo(householdLayerRef.current).bindPopup(`<b>Household Node ${idx + 101}</b><br/>Status: Synchronized`);
      });

      if (L.heatLayer) {
        heatmapLayerRef.current = L.heatLayer(pings, {
          radius: 35,
          blur: 20,
          maxZoom: 18,
          gradient: { 0.4: '#3b82f6', 0.65: '#10b981', 1: '#ef4444' }
        });
      }

      // Initial visibility
      parcelsLayerRef.current.addTo(mapRef.current);
      utilitiesLayerRef.current.addTo(mapRef.current);
      householdLayerRef.current.addTo(mapRef.current);
      if (heatmapLayerRef.current) heatmapLayerRef.current.addTo(mapRef.current);
    } else {
      mapRef.current.setView([location.lat, location.lng], mapRef.current.getZoom());
    }

    // Force resize on all layout shifts
    const observer = new ResizeObserver(() => {
      if (mapRef.current) mapRef.current.invalidateSize();
    });
    observer.observe(mapContainerRef.current);

    fetchWeatherData();

    return () => {
      observer.disconnect();
    };
  }, [location]);

  // Handle layer toggles
  useEffect(() => {
    if (!mapRef.current) return;
    const toggle = (ref: any, visible: boolean) => {
      if (!ref.current) return;
      if (visible) ref.current.addTo(mapRef.current);
      else mapRef.current.removeLayer(ref.current);
    };

    toggle(parcelsLayerRef, layers.parcels);
    toggle(utilitiesLayerRef, layers.utilities);
    toggle(greeneryLayerRef, layers.greenery);
    toggle(householdLayerRef, layers.households);
    toggle(heatmapLayerRef, layers.heatmap);
  }, [layers]);

  useEffect(() => {
    if (mapRef.current) {
      mapRef.current.setZoom(isExpanded ? 17 : 15, { animate: true });
      setTimeout(() => mapRef.current.invalidateSize(), 400);
    }
  }, [isExpanded]);

  const toggleLayer = (layer: keyof typeof layers) => {
    setLayers(prev => ({ ...prev, [layer]: !prev[layer] }));
  };

  const openStreetView = (coords: {lat: number, lng: number}) => {
    setStreetViewCoords(coords);
  };

  return (
    <div className="w-full h-full relative bg-slate-200 transition-all duration-500 overflow-hidden">
      <div ref={mapContainerRef} className="w-full h-full absolute inset-0 z-0 bg-slate-300" style={{ minHeight: '300px' }} />

      {/* HUD Overlays */}
      <div className="absolute top-4 left-4 z-[1000] flex flex-col gap-3 pointer-events-none">
        <div className="glass-panel px-4 py-2.5 rounded-2xl text-[12px] font-black text-slate-800 shadow-xl border border-white/60 flex items-center gap-2.5 pointer-events-auto">
          <span className="w-2.5 h-2.5 bg-emerald-600 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.6)]" aria-hidden="true"></span>
          OFFICIAL GIS DATA SOURCE
        </div>

        <button 
          onClick={() => setIsSatellite(!isSatellite)}
          className={`glass-panel px-5 py-3.5 rounded-2xl shadow-2xl border flex items-center gap-4 pointer-events-auto transition-all active:scale-[0.98] focus-visible:ring-4 focus-visible:ring-blue-600/30 ${isSatellite ? 'bg-slate-900 border-blue-500 text-white' : 'bg-white border-white/60 text-slate-900'}`}
          aria-label={isSatellite ? "Switch to OpenStreetMap View" : "Switch to Google Earth Satellite"}
        >
          <div className="w-10 h-10 rounded-xl bg-slate-100 flex items-center justify-center text-xl shadow-inner border border-slate-200" aria-hidden="true">
             {isSatellite ? '🏙️' : '🌍'}
          </div>
          <div className="text-left">
            <p className={`text-[10px] font-black uppercase tracking-widest leading-none mb-1 ${isSatellite ? 'text-blue-400' : 'text-slate-500'}`}>Base Layer</p>
            <p className="text-xs font-black uppercase tracking-tighter">{isSatellite ? 'Google Satellite' : 'OpenStreetMap'}</p>
          </div>
        </button>

        {weatherInfo && (
          <div className="glass-panel px-4 py-3 rounded-2xl shadow-xl border border-white/60 flex flex-col gap-1 pointer-events-auto bg-white/90 backdrop-blur-md">
            <div className="flex items-center gap-3">
              <span className="text-xl" aria-hidden="true">
                {weatherInfo.conditionCode < 3 ? '☀️' : weatherInfo.conditionCode < 50 ? '☁️' : '🌧️'}
              </span>
              <div>
                <p className="text-[12px] font-black text-slate-900 uppercase tracking-widest leading-none mb-1">{weatherInfo.conditionText}</p>
                <div className="flex items-baseline gap-1">
                  <span className="text-lg font-black text-slate-900 leading-none">{weatherInfo.temp}°C</span>
                  <span className="text-[10px] font-bold text-slate-600 uppercase tracking-tighter">Local</span>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Street View Embed Overlay */}
      {streetViewCoords && (
        <div className="absolute inset-0 z-[3000] bg-slate-900 animate-in fade-in zoom-in-95 duration-300">
          <header className="absolute top-4 left-4 right-4 z-[3100] flex justify-between items-center px-6 py-3 bg-white/90 backdrop-blur-md rounded-2xl border border-white/50 shadow-2xl">
            <div className="flex items-center gap-4">
              <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white text-sm" aria-hidden="true">👁️</div>
              <div>
                <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Spatial Immersion</p>
                <h4 className="text-[12px] font-bold text-slate-900">Street Analysis Mode</h4>
              </div>
            </div>
            <button 
              onClick={() => setStreetViewCoords(null)}
              className="w-10 h-10 flex items-center justify-center bg-slate-100 hover:bg-slate-200 text-slate-900 rounded-full font-black text-lg transition-all"
            >✕</button>
          </header>
          <iframe
            title="Google Street View"
            className="w-full h-full border-0"
            loading="lazy"
            allowFullScreen
            src={`https://www.google.com/maps/embed/v1/streetview?key=${process.env.API_KEY}&location=${streetViewCoords.lat},${streetViewCoords.lng}`}
          ></iframe>
        </div>
      )}

      {isExpanded && !streetViewCoords && (
        <div className="absolute bottom-6 right-6 z-[1000] glass-panel p-5 rounded-[2rem] border border-white/60 shadow-2xl animate-in slide-in-from-bottom duration-500 w-[300px]">
          <div className="flex items-center justify-between mb-4">
            <h4 className="text-[12px] font-black text-slate-600 uppercase tracking-widest">Urban Layer Legend</h4>
            <div className="text-[10px] font-black text-slate-500 bg-slate-100 px-2 py-0.5 rounded-full uppercase tracking-tighter">Official GIS</div>
          </div>
          <div className="space-y-3">
            {[
              { id: 'parcels', label: 'Parcel Boundaries', color: 'bg-blue-600/10', border: 'border-blue-700' },
              { id: 'utilities', label: 'Underground Utilities', color: 'bg-amber-600/10', border: 'border-amber-700' },
              { id: 'greenery', label: 'Public Green Space', color: 'bg-emerald-600/10', border: 'border-emerald-700' },
              { id: 'heatmap', label: 'Regional Heatmap', color: 'bg-gradient-to-tr from-rose-500 to-rose-600', border: 'border-rose-700' },
              { id: 'households', label: 'Resident B-LAN', color: 'bg-slate-900/10', border: 'border-slate-900' }
            ].map((layer) => (
              <div key={layer.id} className={`group flex items-start gap-3 p-3 rounded-2xl transition-all cursor-pointer ${(layers as any)[layer.id] ? layer.color : 'opacity-50 grayscale'}`}
                 onClick={() => toggleLayer(layer.id as any)}>
                <div className={`w-5 h-5 rounded-md shrink-0 mt-0.5 border-2 ${layer.border} ${(layers as any)[layer.id] ? layer.color : ''}`} aria-hidden="true"></div>
