              <div key={layer.id} className={`group flex items-start gap-3 p-3 rounded-2xl transition-all cursor-pointer ${(layers as any)[layer.id] ? layer.color : 'opacity-50 grayscale'}`}
                 onClick={() => toggleLayer(layer.id as any)}>
                <div className={`w-5 h-5 rounded-md shrink-0 mt-0.5 border-2 ${layer.border} ${(layers as any)[layer.id] ? layer.color : ''}`} aria-hidden="true"></div>
                <span className="text-[12px] font-black text-slate-900 block mb-0.5 uppercase tracking-tight">{layer.label}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { GeoLocation } from '../types';

interface MapProps {
  location: GeoLocation;
  name: string;
  isExpanded?: boolean;
}

interface WeatherInfo {
  temp: number;
  windSpeed: number;
  conditionCode: number;
  conditionText: string;
}

export const Map: React.FC<MapProps> = ({ location, name, isExpanded }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const baseLayerRef = useRef<any>(null);

  // GIS Layer Groups
  const parcelsLayerRef = useRef<any>(null);
  const utilitiesLayerRef = useRef<any>(null);
  const greeneryLayerRef = useRef<any>(null);
  const householdLayerRef = useRef<any>(null);
  const heatmapLayerRef = useRef<any>(null);

  const [streetViewCoords, setStreetViewCoords] = useState<{lat: number, lng: number} | null>(null);
  const [weatherInfo, setWeatherInfo] = useState<WeatherInfo | null>(null);
  const [isSatellite, setIsSatellite] = useState(false); // OSM is default (false)

  const [layers, setLayers] = useState({
    parcels: true,
    utilities: true,
    greenery: true,
    health: true,
    households: true,
    weather: false,
    heatmap: true
  });

  const getWeatherText = (code: number) => {
    if (code === 0) return 'Clear Sky';
    if (code <= 3) return 'Partly Cloudy';
    if (code <= 48) return 'Foggy';
    if (code <= 67) return 'Rain / Drizzle';
    if (code <= 77) return 'Snow';
    if (code <= 99) return 'Thunderstorm';
    return 'Overcast';
  };

  const fetchWeatherData = async () => {
    try {
      const response = await fetch(
        `https://api.open-meteo.com/v1/forecast?latitude=${location.lat}&longitude=${location.lng}&current_weather=true`
      );
      const data = await response.json();
      if (data.current_weather) {
        setWeatherInfo({
          temp: data.current_weather.temperature,
          windSpeed: data.current_weather.windspeed,
          conditionCode: data.current_weather.weathercode,
          conditionText: getWeatherText(data.current_weather.weathercode)
        });
      }
    } catch (err) {
      console.error("Weather sync failed", err);
    }
  };

  // Logic to switch base layers: OpenStreetMap vs Google Satellite Hybrid
  const updateBaseLayer = () => {
    if (!mapRef.current) return;
    const L = (window as any).L;

    if (baseLayerRef.current) {
      mapRef.current.removeLayer(baseLayerRef.current);
    }

    // Street: Standard OSM
    // Satellite: Google Hybrid (lyrs=y)
    const streetUrl = 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png';
    const satelliteUrl = 'https://mt1.google.com/vt/lyrs=y&x={x}&y={y}&z={z}';

    const attribution = isSatellite 
      ? 'Map data &copy; Google'
      : '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors';

    baseLayerRef.current = L.tileLayer(isSatellite ? satelliteUrl : streetUrl, {
      attribution: attribution,
      maxZoom: 20,
      subdomains: isSatellite ? ['mt0', 'mt1', 'mt2', 'mt3'] : ['a', 'b', 'c']
    }).addTo(mapRef.current);

    // Ensure base layer is always at the bottom
    baseLayerRef.current.bringToBack();
  };

  // 1. Initial Map and GIS Layer Setup
  useEffect(() => {
    if (!mapContainerRef.current) return;
    const L = (window as any).L;
    if (!L) return;

    if (!mapRef.current) {
      // Initialize map object
      mapRef.current = L.map(mapContainerRef.current, {
        zoomControl: false,
        attributionControl: true
      }).setView([location.lat, location.lng], 15);

      L.control.zoom({ position: 'bottomleft' }).addTo(mapRef.current);

      // Add the default OSM layer
      updateBaseLayer();

      // Create and Add GIS Overlay Groups
      parcelsLayerRef.current = L.layerGroup().addTo(mapRef.current);
      utilitiesLayerRef.current = L.layerGroup().addTo(mapRef.current);
      greeneryLayerRef.current = L.layerGroup().addTo(mapRef.current);
      householdLayerRef.current = L.layerGroup().addTo(mapRef.current);

      // Simulated Data Construction
      const parcelStyle = { color: '#2563eb', weight: 1.5, fillOpacity: 0.1, fillColor: '#3b82f6' };
      for (let i = -1; i <= 1; i++) {
        for (let j = -1; j <= 1; j++) {
          L.rectangle([
            [location.lat + i * 0.0012, location.lng + j * 0.0018],
            [location.lat + (i + 0.8) * 0.0012, location.lng + (j + 0.8) * 0.0018]
          ], parcelStyle).addTo(parcelsLayerRef.current);
        }
      }

      const utilityStyle = { color: '#fbbf24', weight: 2.5, dashArray: '6, 10', opacity: 0.7 };
      L.polyline([[location.lat - 0.004, location.lng], [location.lat + 0.004, location.lng]], utilityStyle).addTo(utilitiesLayerRef.current);
      L.polyline([[location.lat, location.lng - 0.005], [location.lat, location.lng + 0.005]], utilityStyle).addTo(utilitiesLayerRef.current);

      const pings: [number, number, number][] = [
        [location.lat + 0.001, location.lng + 0.001, 1],
        [location.lat - 0.0015, location.lng - 0.001, 0.8],
        [location.lat + 0.002, location.lng - 0.0012, 0.7],
        [location.lat + 0.0005, location.lng - 0.002, 0.6]
      ];

      pings.forEach((p, idx) => {
        L.marker([p[0], p[1]]).addTo(householdLayerRef.current).bindPopup(`
          <div class="p-1">
            <b class="text-slate-900 block text-xs mb-1">Node AS-${idx + 400}</b>
            <p class="text-[10px] text-slate-500 font-bold uppercase mb-2">Resident Mesh Active</p>
            <button onclick="window.dispatchEvent(new CustomEvent('open-street-view', {detail: {lat: ${p[0]}, lng: ${p[1]}}}))" class="w-full bg-blue-600 text-white text-[10px] font-black py-1.5 rounded-lg hover:bg-blue-700 transition-colors uppercase">
              Street View
            </button>
          </div>
        `);
      });

      if (L.heatLayer) {
        heatmapLayerRef.current = L.heatLayer(pings, {
          radius: 40,
          blur: 25,
          maxZoom: 18,
          gradient: { 0.4: '#3b82f6', 0.65: '#10b981', 1: '#ef4444' }
        }).addTo(mapRef.current);
      }

      // Add Global Listener for Street View inside popups
      const handleSVOpen = (e: any) => setStreetViewCoords(e.detail);
      window.addEventListener('open-street-view', handleSVOpen);

      // Cleanup
      return () => {
        window.removeEventListener('open-street-view', handleSVOpen);
      };
    } else {
      // Update position if map already exists
      mapRef.current.setView([location.lat, location.lng], mapRef.current.getZoom());
    }

    // Critical: Watch container size to prevent grey boxes
    const observer = new ResizeObserver(() => {
      if (mapRef.current) mapRef.current.invalidateSize();
    });
    observer.observe(mapContainerRef.current);

    fetchWeatherData();

    return () => {
      observer.disconnect();
    };
  }, [location]);

  // 2. React to isSatellite toggle
  useEffect(() => {
    updateBaseLayer();
  }, [isSatellite]);

  // 3. Handle GIS Layer Visibilities
  useEffect(() => {
    if (!mapRef.current) return;
    const toggle = (ref: any, visible: boolean) => {
      if (!ref.current) return;
      if (visible) {
        if (!mapRef.current.hasLayer(ref.current)) ref.current.addTo(mapRef.current);
      } else {
        if (mapRef.current.hasLayer(ref.current)) mapRef.current.removeLayer(ref.current);
      }
    };

    toggle(parcelsLayerRef, layers.parcels);
    toggle(utilitiesLayerRef, layers.utilities);
    toggle(greeneryLayerRef, layers.greenery);
    toggle(householdLayerRef, layers.households);
    toggle(heatmapLayerRef, layers.heatmap);
  }, [layers]);

  // 4. Force invalidation on expansion or location change
  useEffect(() => {
    if (mapRef.current) {
      const zoom = isExpanded ? 17 : 15;
      mapRef.current.setZoom(zoom, { animate: true });
      // Multiple attempts to ensure it fills the container after animations
      setTimeout(() => mapRef.current.invalidateSize(), 50);
      setTimeout(() => mapRef.current.invalidateSize(), 300);
      setTimeout(() => mapRef.current.invalidateSize(), 600);
    }
  }, [isExpanded, location]);

  const toggleLayer = (layer: keyof typeof layers) => {
    setLayers(prev => ({ ...prev, [layer]: !prev[layer] }));
  };

  return (
    <div className="w-full h-full relative bg-slate-200 transition-all duration-500 overflow-hidden">
      {/* Map Target */}
      <div 
        ref={mapContainerRef} 
        className="w-full h-full absolute inset-0 z-0 bg-slate-200" 
        style={{ minHeight: '100%' }}
      />

      {/* Control HUD Overlay */}
      <div className="absolute top-4 left-4 z-[1000] flex flex-col gap-3 pointer-events-none">
        <div className="glass-panel px-4 py-2.5 rounded-2xl text-[11px] font-black text-slate-800 shadow-xl border border-white/60 flex items-center gap-2.5 pointer-events-auto">
          <span className="w-2.5 h-2.5 bg-emerald-600 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.6)]" aria-hidden="true"></span>
          GIS ACTIVE
        </div>

        {/* The Toggle Button requested by the user */}
        <button 
          onClick={() => setIsSatellite(!isSatellite)}
          className={`glass-panel px-5 py-3.5 rounded-2xl shadow-2xl border flex items-center gap-4 pointer-events-auto transition-all active:scale-[0.98] focus-visible:ring-4 focus-visible:ring-blue-600/30 group ${isSatellite ? 'bg-slate-900 border-blue-500 text-white' : 'bg-white border-white/60 text-slate-900'}`}
          aria-label={isSatellite ? "Switch to OpenStreetMap View" : "Switch to Google Earth Satellite"}
        >
          <div className="w-10 h-10 rounded-xl bg-slate-100 flex items-center justify-center text-xl shadow-inner border border-slate-200 group-hover:scale-110 transition-transform" aria-hidden="true">
             {isSatellite ? '🏙️' : '🌍'}
          </div>
          <div className="text-left pr-2">
            <p className={`text-[9px] font-black uppercase tracking-widest leading-none mb-1 ${isSatellite ? 'text-blue-400' : 'text-slate-500'}`}>Map Mode</p>
            <p className="text-xs font-black uppercase tracking-tighter">{isSatellite ? 'Google Satellite' : 'OpenStreetMap'}</p>
          </div>
        </button>

        {weatherInfo && (
          <div className="glass-panel px-4 py-3 rounded-2xl shadow-xl border border-white/60 flex flex-col gap-1 pointer-events-auto bg-white/90 backdrop-blur-md">
            <div className="flex items-center gap-3">
              <span className="text-xl" aria-hidden="true">
                {weatherInfo.conditionCode < 3 ? '☀️' : weatherInfo.conditionCode < 50 ? '☁️' : '🌧️'}
              </span>
              <div>
                <p className="text-[10px] font-black text-slate-900 uppercase tracking-widest leading-none mb-1">{weatherInfo.conditionText}</p>
                <div className="flex items-baseline gap-1">
                  <span className="text-base font-black text-slate-900 leading-none">{weatherInfo.temp}°C</span>
                  <span className="text-[9px] font-bold text-slate-600 uppercase tracking-tighter">Live</span>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Street View Embed Overlay */}
      {streetViewCoords && (
        <div className="absolute inset-0 z-[3000] bg-slate-900 animate-in fade-in zoom-in-95 duration-300">
          <header className="absolute top-4 left-4 right-4 z-[3100] flex justify-between items-center px-6 py-3 bg-white/90 backdrop-blur-md rounded-2xl border border-white/50 shadow-2xl">
            <div className="flex items-center gap-4">
              <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white text-sm" aria-hidden="true">👁️</div>
              <div>
                <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Spatial Analysis</p>
                <h4 className="text-[11px] font-bold text-slate-900">Virtual Immersion Node</h4>
              </div>
            </div>
            <button 
              onClick={() => setStreetViewCoords(null)}
              className="w-10 h-10 flex items-center justify-center bg-slate-100 hover:bg-slate-200 text-slate-900 rounded-full font-black text-lg transition-all"
            >✕</button>
          </header>
          <iframe
            title="Google Street View"
            className="w-full h-full border-0"
            loading="lazy"
            allowFullScreen
            src={`https://www.google.com/maps/embed/v1/streetview?key=${process.env.API_KEY}&location=${streetViewCoords.lat},${streetViewCoords.lng}`}
          ></iframe>
        </div>
      )}

      {/* GIS Legend Panel */}
      {isExpanded && !streetViewCoords && (
        <div className="absolute bottom-6 right-6 z-[1000] glass-panel p-5 rounded-[2rem] border border-white/60 shadow-2xl animate-in slide-in-from-bottom duration-500 w-[280px]">
          <div className="flex items-center justify-between mb-4">
            <h4 className="text-[11px] font-black text-slate-600 uppercase tracking-widest">Active Layers</h4>
            <div className="text-[9px] font-black text-blue-600 bg-blue-50 px-2 py-0.5 rounded-full uppercase tracking-tighter">NIST GIS</div>
          </div>
          <div className="space-y-2.5">
            {[
              { id: 'parcels', label: 'Parcel Polygons', color: 'bg-blue-600/10', border: 'border-blue-700' },
              { id: 'utilities', label: 'Grid Infrastructure', color: 'bg-amber-600/10', border: 'border-amber-700' },
              { id: 'heatmap', label: 'Consumption Heat', color: 'bg-gradient-to-tr from-rose-500 to-rose-600', border: 'border-rose-700' },
              { id: 'households', label: 'B-LAN Mesh Nodes', color: 'bg-slate-900/10', border: 'border-slate-900' }
            ].map((layer) => (
              <div key={layer.id} className={`group flex items-start gap-3 p-2.5 rounded-xl transition-all cursor-pointer ${(layers as any)[layer.id] ? layer.color : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer(layer.id as any)}>
                <div className={`w-4 h-4 rounded-md shrink-0 mt-0.5 border-2 ${layer.border} ${(layers as any)[layer.id] ? layer.color : ''}`} aria-hidden="true"></div>
                <span className="text-[11px] font-black text-slate-800 block uppercase tracking-tight">{layer.label}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { GeoLocation } from '../types';

interface MapProps {
  location: GeoLocation;
  name: string;
  isExpanded?: boolean;
}

interface WeatherInfo {
  temp: number;
  windSpeed: number;
  conditionCode: number;
  conditionText: string;
}

export const Map: React.FC<MapProps> = ({ location, name, isExpanded }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const baseLayerRef = useRef<any>(null);

  // GIS Layer Groups
  const parcelsLayerRef = useRef<any>(null);
  const utilitiesLayerRef = useRef<any>(null);
  const greeneryLayerRef = useRef<any>(null);
  const householdLayerRef = useRef<any>(null);
  const heatmapLayerRef = useRef<any>(null);

  const [streetViewCoords, setStreetViewCoords] = useState<{lat: number, lng: number} | null>(null);
  const [weatherInfo, setWeatherInfo] = useState<WeatherInfo | null>(null);
  const [isSatellite, setIsSatellite] = useState(false); // OSM is default (false)

  const [layers, setLayers] = useState({
    parcels: true,
    utilities: true,
    greenery: true,
    health: true,
    households: true,
    weather: false,
    heatmap: true
  });

  const getWeatherText = (code: number) => {
    if (code === 0) return 'Clear Sky';
    if (code <= 3) return 'Partly Cloudy';
    if (code <= 48) return 'Foggy';
    if (code <= 67) return 'Rain / Drizzle';
    if (code <= 77) return 'Snow';
    if (code <= 99) return 'Thunderstorm';
    return 'Overcast';
  };

  const fetchWeatherData = async () => {
    try {
      const response = await fetch(
        `https://api.open-meteo.com/v1/forecast?latitude=${location.lat}&longitude=${location.lng}&current_weather=true`
      );
      const data = await response.json();
      if (data.current_weather) {
        setWeatherInfo({
          temp: data.current_weather.temperature,
          windSpeed: data.current_weather.windspeed,
          conditionCode: data.current_weather.weathercode,
          conditionText: getWeatherText(data.current_weather.weathercode)
        });
      }
    } catch (err) {
      console.error("Weather sync failed", err);
    }
  };

  // Logic to switch base layers: OpenStreetMap vs Google Satellite Hybrid
  const updateBaseLayer = () => {
    if (!mapRef.current) return;
    const L = (window as any).L;

    if (baseLayerRef.current) {
      mapRef.current.removeLayer(baseLayerRef.current);
    }

    // Street: Standard OSM
    // Satellite: Google Hybrid (lyrs=y)
    const streetUrl = 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png';
    const satelliteUrl = 'https://mt1.google.com/vt/lyrs=y&x={x}&y={y}&z={z}';

    const attribution = isSatellite 
      ? 'Map data &copy; Google'
      : '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors';

    baseLayerRef.current = L.tileLayer(isSatellite ? satelliteUrl : streetUrl, {
      attribution: attribution,
      maxZoom: 20,
      subdomains: isSatellite ? ['mt0', 'mt1', 'mt2', 'mt3'] : ['a', 'b', 'c']
    }).addTo(mapRef.current);

    // Ensure base layer is always at the bottom
    baseLayerRef.current.bringToBack();
  };

  // 1. Initial Map and GIS Layer Setup
  useEffect(() => {
    if (!mapContainerRef.current) return;
    const L = (window as any).L;
    if (!L) return;

    if (!mapRef.current) {
      // Initialize map object
      mapRef.current = L.map(mapContainerRef.current, {
        zoomControl: false,
        attributionControl: true
      }).setView([location.lat, location.lng], 15);

      L.control.zoom({ position: 'bottomleft' }).addTo(mapRef.current);

      // Add the default OSM layer
      updateBaseLayer();

      // Create and Add GIS Overlay Groups
      parcelsLayerRef.current = L.layerGroup().addTo(mapRef.current);
      utilitiesLayerRef.current = L.layerGroup().addTo(mapRef.current);
      greeneryLayerRef.current = L.layerGroup().addTo(mapRef.current);
      householdLayerRef.current = L.layerGroup().addTo(mapRef.current);

      // Simulated Parcels
      const parcelStyle = { color: '#2563eb', weight: 1.5, fillOpacity: 0.1, fillColor: '#3b82f6' };
      for (let i = -1; i <= 1; i++) {
        for (let j = -1; j <= 1; j++) {
          L.rectangle([
            [location.lat + i * 0.0012, location.lng + j * 0.0018],
            [location.lat + (i + 0.8) * 0.0012, location.lng + (j + 0.8) * 0.0018]
          ], parcelStyle).addTo(parcelsLayerRef.current);
        }
      }

      // Simulated Utilities
      const utilityStyle = { color: '#fbbf24', weight: 2.5, dashArray: '6, 10', opacity: 0.7 };
      L.polyline([[location.lat - 0.004, location.lng], [location.lat + 0.004, location.lng]], utilityStyle).addTo(utilitiesLayerRef.current);
      L.polyline([[location.lat, location.lng - 0.005], [location.lat, location.lng + 0.005]], utilityStyle).addTo(utilitiesLayerRef.current);

      // Simulated Green Space
      const greenStyle = { color: '#059669', weight: 0, fillOpacity: 0.3, fillColor: '#10b981' };
      L.circle([location.lat + 0.003, location.lng - 0.004], { radius: 180, ...greenStyle }).addTo(greeneryLayerRef.current);
      L.circle([location.lat - 0.002, location.lng + 0.003], { radius: 120, ...greenStyle }).addTo(greeneryLayerRef.current);

      const pings: [number, number, number][] = [
        [location.lat + 0.001, location.lng + 0.001, 1],
        [location.lat - 0.0015, location.lng - 0.001, 0.8],
        [location.lat + 0.002, location.lng - 0.0012, 0.7],
        [location.lat + 0.0005, location.lng - 0.002, 0.6]
      ];

      pings.forEach((p, idx) => {
        L.marker([p[0], p[1]]).addTo(householdLayerRef.current).bindPopup(`
          <div class="p-1">
            <b class="text-slate-900 block text-xs mb-1">Node AS-${idx + 400}</b>
            <p class="text-[10px] text-slate-500 font-bold uppercase mb-2">Resident Mesh Active</p>
            <button onclick="window.dispatchEvent(new CustomEvent('open-street-view', {detail: {lat: ${p[0]}, lng: ${p[1]}}}))" class="w-full bg-blue-600 text-white text-[10px] font-black py-1.5 rounded-lg hover:bg-blue-700 transition-colors uppercase">
              Street View
            </button>
          </div>
        `);
      });

      if (L.heatLayer) {
        heatmapLayerRef.current = L.heatLayer(pings, {
          radius: 40,
          blur: 25,
          maxZoom: 18,
          gradient: { 0.4: '#3b82f6', 0.65: '#10b981', 1: '#ef4444' }
        }).addTo(mapRef.current);
      }

      // Add Global Listener for Street View inside popups
      const handleSVOpen = (e: any) => setStreetViewCoords(e.detail);
      window.addEventListener('open-street-view', handleSVOpen);

      // Cleanup
      return () => {
        window.removeEventListener('open-street-view', handleSVOpen);
      };
    } else {
      // Update position if map already exists
      mapRef.current.setView([location.lat, location.lng], mapRef.current.getZoom());
    }

    // Critical: Watch container size to prevent grey boxes
    const observer = new ResizeObserver(() => {
      if (mapRef.current) mapRef.current.invalidateSize();
    });
    observer.observe(mapContainerRef.current);

    fetchWeatherData();

    return () => {
      observer.disconnect();
    };
  }, [location]);

  // 2. React to isSatellite toggle
  useEffect(() => {
    updateBaseLayer();
  }, [isSatellite]);

  // 3. Handle GIS Layer Visibilities
  useEffect(() => {
    if (!mapRef.current) return;
    const toggle = (ref: any, visible: boolean) => {
      if (!ref.current) return;
      if (visible) {
        if (!mapRef.current.hasLayer(ref.current)) ref.current.addTo(mapRef.current);
      } else {
        if (mapRef.current.hasLayer(ref.current)) mapRef.current.removeLayer(ref.current);
      }
    };

    toggle(parcelsLayerRef, layers.parcels);
    toggle(utilitiesLayerRef, layers.utilities);
    toggle(greeneryLayerRef, layers.greenery);
    toggle(householdLayerRef, layers.households);
    toggle(heatmapLayerRef, layers.heatmap);
  }, [layers]);

  // 4. Force invalidation on expansion or location change
  useEffect(() => {
    if (mapRef.current) {
      const zoom = isExpanded ? 17 : 15;
      mapRef.current.setZoom(zoom, { animate: true });
      // Multiple attempts to ensure it fills the container after animations
      setTimeout(() => mapRef.current.invalidateSize(), 50);
      setTimeout(() => mapRef.current.invalidateSize(), 300);
      setTimeout(() => mapRef.current.invalidateSize(), 600);
    }
  }, [isExpanded, location]);

  const toggleLayer = (layer: keyof typeof layers) => {
    setLayers(prev => ({ ...prev, [layer]: !prev[layer] }));
  };

  return (
    <div className="w-full h-full relative bg-slate-200 transition-all duration-500 overflow-hidden">
      {/* Map Target */}
      <div 
        ref={mapContainerRef} 
        className="w-full h-full absolute inset-0 z-0 bg-slate-200" 
        style={{ minHeight: '100%' }}
      />

      {/* Control HUD Overlay */}
      <div className="absolute top-4 left-4 z-[1000] flex flex-col gap-3 pointer-events-none max-w-[220px]">
        <div className="glass-panel px-4 py-2.5 rounded-2xl text-[11px] font-black text-slate-800 shadow-xl border border-white/60 flex items-center gap-2.5 pointer-events-auto">
          <span className="w-2.5 h-2.5 bg-emerald-600 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.6)]" aria-hidden="true"></span>
          GIS ACTIVE
        </div>

        {/* The Toggle Button for Base Map */}
        <button 
          onClick={() => setIsSatellite(!isSatellite)}
          className={`glass-panel px-5 py-3.5 rounded-2xl shadow-2xl border flex items-center gap-4 pointer-events-auto transition-all active:scale-[0.98] focus-visible:ring-4 focus-visible:ring-blue-600/30 group ${isSatellite ? 'bg-slate-900 border-blue-500 text-white' : 'bg-white border-white/60 text-slate-900'}`}
          aria-label={isSatellite ? "Switch to OpenStreetMap View" : "Switch to Google Earth Satellite"}
        >
          <div className="w-10 h-10 rounded-xl bg-slate-100 flex items-center justify-center text-xl shadow-inner border border-slate-200 group-hover:scale-110 transition-transform" aria-hidden="true">
             {isSatellite ? '🏙️' : '🌍'}
          </div>
          <div className="text-left pr-2">
            <p className={`text-[9px] font-black uppercase tracking-widest leading-none mb-1 ${isSatellite ? 'text-blue-400' : 'text-slate-500'}`}>Map Mode</p>
            <p className="text-xs font-black uppercase tracking-tighter">{isSatellite ? 'Satellite' : 'Street'}</p>
          </div>
        </button>

        {/* GIS Layer Toggles Panel */}
        <div className="glass-panel p-3 rounded-2xl shadow-xl border border-white/60 pointer-events-auto bg-white/90 backdrop-blur-md flex flex-col gap-2">
           <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest px-1 mb-1 leading-none">GIS Data Layers</p>
           {[
             { id: 'parcels', label: 'Parcels', icon: '📦' },
             { id: 'utilities', label: 'Utilities', icon: '⚡' },
             { id: 'greenery', label: 'Greenery', icon: '🌳' }
           ].map(layer => (
             <button
               key={layer.id}
               onClick={() => toggleLayer(layer.id as any)}
               className={`flex items-center gap-3 px-3 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all border shadow-sm ${layers[layer.id as keyof typeof layers] ? 'bg-blue-600 text-white border-blue-400' : 'bg-white text-slate-500 border-slate-200 hover:bg-slate-50'}`}
             >
               <span className="text-sm shrink-0" aria-hidden="true">{layer.icon}</span>
               <span className="truncate">{layer.label}</span>
               <div className={`ml-auto w-3.5 h-3.5 rounded-full border-2 ${layers[layer.id as keyof typeof layers] ? 'bg-white border-white' : 'border-slate-300'}`} aria-hidden="true" />
             </button>
           ))}
        </div>

        {weatherInfo && (
          <div className="glass-panel px-4 py-3 rounded-2xl shadow-xl border border-white/60 flex flex-col gap-1 pointer-events-auto bg-white/90 backdrop-blur-md">
            <div className="flex items-center gap-3">
              <span className="text-xl" aria-hidden="true">
                {weatherInfo.conditionCode < 3 ? '☀️' : weatherInfo.conditionCode < 50 ? '☁️' : '🌧️'}
              </span>
              <div>
                <p className="text-[10px] font-black text-slate-900 uppercase tracking-widest leading-none mb-1">{weatherInfo.conditionText}</p>
                <div className="flex items-baseline gap-1">
                  <span className="text-base font-black text-slate-900 leading-none">{weatherInfo.temp}°C</span>
                  <span className="text-[9px] font-bold text-slate-600 uppercase tracking-tighter">Live</span>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Street View Embed Overlay */}
      {streetViewCoords && (
        <div className="absolute inset-0 z-[3000] bg-slate-900 animate-in fade-in zoom-in-95 duration-300">
          <header className="absolute top-4 left-4 right-4 z-[3100] flex justify-between items-center px-6 py-3 bg-white/90 backdrop-blur-md rounded-2xl border border-white/50 shadow-2xl">
            <div className="flex items-center gap-4">
              <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white text-sm" aria-hidden="true">👁️</div>
              <div>
                <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Spatial Analysis</p>
                <h4 className="text-[11px] font-bold text-slate-900">Virtual Immersion Node</h4>
              </div>
            </div>
            <button 
              onClick={() => setStreetViewCoords(null)}
              className="w-10 h-10 flex items-center justify-center bg-slate-100 hover:bg-slate-200 text-slate-900 rounded-full font-black text-lg transition-all"
            >✕</button>
          </header>
          <iframe
            title="Google Street View"
            className="w-full h-full border-0"
            loading="lazy"
            allowFullScreen
            src={`https://www.google.com/maps/embed/v1/streetview?key=${process.env.API_KEY}&location=${streetViewCoords.lat},${streetViewCoords.lng}`}
          ></iframe>
        </div>
      )}

      {/* GIS Legend Panel */}
      {isExpanded && !streetViewCoords && (
        <div className="absolute bottom-6 right-6 z-[1000] glass-panel p-5 rounded-[2rem] border border-white/60 shadow-2xl animate-in slide-in-from-bottom duration-500 w-[280px]">
          <div className="flex items-center justify-between mb-4">
            <h4 className="text-[11px] font-black text-slate-600 uppercase tracking-widest">Map Legend</h4>
            <div className="text-[9px] font-black text-blue-600 bg-blue-50 px-2 py-0.5 rounded-full uppercase tracking-tighter">NIST GIS</div>
          </div>
          <div className="space-y-2.5">
            {[
              { id: 'parcels', label: 'Parcel Polygons', color: 'bg-blue-600/10', border: 'border-blue-700' },
              { id: 'utilities', label: 'Grid Infrastructure', color: 'bg-amber-600/10', border: 'border-amber-700' },
              { id: 'greenery', label: 'Public Green Spaces', color: 'bg-emerald-600/10', border: 'border-emerald-700' },
              { id: 'heatmap', label: 'Consumption Heat', color: 'bg-gradient-to-tr from-rose-500 to-rose-600', border: 'border-rose-700' },
              { id: 'households', label: 'B-LAN Mesh Nodes', color: 'bg-slate-900/10', border: 'border-slate-900' }
            ].map((layer) => (
              <div key={layer.id} className={`group flex items-start gap-3 p-2.5 rounded-xl transition-all cursor-pointer ${(layers as any)[layer.id] ? layer.color : 'opacity-40 grayscale'}`}
                 onClick={() => toggleLayer(layer.id as any)}>
                <div className={`w-4 h-4 rounded-md shrink-0 mt-0.5 border-2 ${layer.border} ${(layers as any)[layer.id] ? layer.color : ''}`} aria-hidden="true"></div>
                <span className="text-[11px] font-black text-slate-800 block uppercase tracking-tight">{layer.label}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { GeoLocation } from '../types';

interface MapProps {
  location: GeoLocation;
  name: string;
  isExpanded?: boolean;
}

interface WeatherInfo {
  temp: number;
  windSpeed: number;
  conditionCode: number;
  conditionText: string;
}

export const Map: React.FC<MapProps> = ({ location, name, isExpanded }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const baseLayerRef = useRef<any>(null);

  // GIS Layer Groups
  const parcelsLayerRef = useRef<any>(null);
  const utilitiesLayerRef = useRef<any>(null);
  const greeneryLayerRef = useRef<any>(null);
  const householdLayerRef = useRef<any>(null);
  const heatmapLayerRef = useRef<any>(null);

  const [streetViewCoords, setStreetViewCoords] = useState<{lat: number, lng: number} | null>(null);
  const [weatherInfo, setWeatherInfo] = useState<WeatherInfo | null>(null);
  const [isSatellite, setIsSatellite] = useState(false);

  const [layers, setLayers] = useState({
    parcels: true,
    utilities: true,
    greenery: true,
    households: true,
    heatmap: true
  });

  const getWeatherText = (code: number) => {
    if (code === 0) return 'Clear Sky';
    if (code <= 3) return 'Partly Cloudy';
    if (code <= 48) return 'Foggy';
    if (code <= 67) return 'Rain / Drizzle';
    if (code <= 77) return 'Snow';
    if (code <= 99) return 'Thunderstorm';
    return 'Overcast';
  };

  const fetchWeatherData = async () => {
    try {
      const response = await fetch(
        `https://api.open-meteo.com/v1/forecast?latitude=${location.lat}&longitude=${location.lng}&current_weather=true`
      );
      const data = await response.json();
      if (data.current_weather) {
        setWeatherInfo({
          temp: data.current_weather.temperature,
          windSpeed: data.current_weather.windspeed,
          conditionCode: data.current_weather.weathercode,
          conditionText: getWeatherText(data.current_weather.weathercode)
        });
      }
    } catch (err) {
      console.error("Weather sync failed", err);
    }
  };

  const updateBaseLayer = () => {
    if (!mapRef.current) return;
    const L = (window as any).L;

    if (baseLayerRef.current) {
      mapRef.current.removeLayer(baseLayerRef.current);
    }

    const streetUrl = 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png';
    const satelliteUrl = 'https://mt1.google.com/vt/lyrs=y&x={x}&y={y}&z={z}';

    const attribution = isSatellite 
      ? 'Map data &copy; Google'
      : '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors';

    baseLayerRef.current = L.tileLayer(isSatellite ? satelliteUrl : streetUrl, {
      attribution: attribution,
      maxZoom: 20,
      subdomains: isSatellite ? ['mt0', 'mt1', 'mt2', 'mt3'] : ['a', 'b', 'c']
    }).addTo(mapRef.current);

    baseLayerRef.current.bringToBack();
  };

  useEffect(() => {
    if (!mapContainerRef.current) return;
    const L = (window as any).L;
    if (!L) return;

    if (!mapRef.current) {
      mapRef.current = L.map(mapContainerRef.current, {
        zoomControl: false,
        attributionControl: true
      }).setView([location.lat, location.lng], 15);

      L.control.zoom({ position: 'bottomleft' }).addTo(mapRef.current);

      updateBaseLayer();

      // Initialize Groups
      parcelsLayerRef.current = L.layerGroup().addTo(mapRef.current);
      utilitiesLayerRef.current = L.layerGroup().addTo(mapRef.current);
      greeneryLayerRef.current = L.layerGroup().addTo(mapRef.current);
      householdLayerRef.current = L.layerGroup().addTo(mapRef.current);

      // 1. Refined Parcels: Varied grid for "City" look
      const parcelStyle = { color: '#3b82f6', weight: 1, fillOpacity: 0.12, fillColor: '#93c5fd' };
      for (let i = -3; i <= 3; i++) {
        for (let j = -3; j <= 3; j++) {
          if ((i + j) % 2 === 0) continue; // Sparse grid
          L.rectangle([
            [location.lat + i * 0.0008, location.lng + j * 0.0012],
            [location.lat + (i + 0.7) * 0.0008, location.lng + (j + 0.9) * 0.0012]
          ], parcelStyle).addTo(parcelsLayerRef.current).bindTooltip("Legal Parcel Boundary");
        }
      }

      // 2. Refined Utilities: Distinct "Subterranean" neon amber dash
      const utilityStyle = { color: '#f59e0b', weight: 3, dashArray: '10, 10', opacity: 0.9 };
      L.polyline([[location.lat - 0.006, location.lng + 0.002], [location.lat + 0.006, location.lng - 0.002]], utilityStyle).addTo(utilitiesLayerRef.current).bindTooltip("Main Utility Trunk Line");
      L.polyline([[location.lat + 0.002, location.lng - 0.006], [location.lat - 0.002, location.lng + 0.006]], { ...utilityStyle, color: '#fbbf24' }).addTo(utilitiesLayerRef.current);

      // 3. Refined Greenery: Soft Emerald Polygons/Circles
      const greenStyle = { color: '#047857', weight: 1, fillOpacity: 0.4, fillColor: '#10b981' };
      L.circle([location.lat + 0.004, location.lng - 0.004], { radius: 220, ...greenStyle }).addTo(greeneryLayerRef.current).bindTooltip("Public Park Space");
      L.circle([location.lat - 0.003, location.lng + 0.005], { radius: 150, ...greenStyle }).addTo(greeneryLayerRef.current).bindTooltip("Preserved Green Space");

      const pings: [number, number, number][] = [
        [location.lat + 0.001, location.lng + 0.001, 1],
        [location.lat - 0.0015, location.lng - 0.001, 0.8],
        [location.lat + 0.002, location.lng - 0.0012, 0.7],
        [location.lat + 0.0005, location.lng - 0.002, 0.6]
      ];

      pings.forEach((p, idx) => {
        L.circleMarker([p[0], p[1]], { radius: 6, color: '#1e293b', fillColor: '#334155', fillOpacity: 1, weight: 2 }).addTo(householdLayerRef.current).bindPopup(`
          <div class="p-1">
            <b class="text-slate-900 block text-xs mb-1">Node CT-${idx + 400}</b>
            <p class="text-[10px] text-slate-500 font-bold uppercase mb-2">Resident Mesh Active</p>
            <button onclick="window.dispatchEvent(new CustomEvent('open-street-view', {detail: {lat: ${p[0]}, lng: ${p[1]}}}))" class="w-full bg-blue-600 text-white text-[10px] font-black py-1.5 rounded-lg hover:bg-blue-700 transition-colors uppercase">
              Street View
            </button>
          </div>
        `);
      });

      if (L.heatLayer) {
        heatmapLayerRef.current = L.heatLayer(pings, {
          radius: 45,
          blur: 20,
          maxZoom: 18,
          gradient: { 0.4: '#3b82f6', 0.65: '#10b981', 1: '#f43f5e' }
        }).addTo(mapRef.current);
      }

      const handleSVOpen = (e: any) => setStreetViewCoords(e.detail);
      window.addEventListener('open-street-view', handleSVOpen);

      return () => {
        window.removeEventListener('open-street-view', handleSVOpen);
      };
    } else {
      mapRef.current.setView([location.lat, location.lng], mapRef.current.getZoom());
    }

    const observer = new ResizeObserver(() => {
      if (mapRef.current) mapRef.current.invalidateSize();
    });
    observer.observe(mapContainerRef.current);

    fetchWeatherData();

    return () => {
      observer.disconnect();
    };
  }, [location]);

  useEffect(() => {
    updateBaseLayer();
  }, [isSatellite]);

  // Handle Layer Visibilities
  useEffect(() => {
    if (!mapRef.current) return;
    const toggleGroup = (ref: any, visible: boolean) => {
      if (!ref.current) return;
      if (visible) {
        if (!mapRef.current.hasLayer(ref.current)) ref.current.addTo(mapRef.current);
      } else {
        if (mapRef.current.hasLayer(ref.current)) mapRef.current.removeLayer(ref.current);
      }
    };

    toggleGroup(parcelsLayerRef, layers.parcels);
    toggleGroup(utilitiesLayerRef, layers.utilities);
    toggleGroup(greeneryLayerRef, layers.greenery);
    toggleGroup(householdLayerRef, layers.households);
    toggleGroup(heatmapLayerRef, layers.heatmap);
  }, [layers]);

  useEffect(() => {
    if (mapRef.current) {
      const zoom = isExpanded ? 17 : 15;
      mapRef.current.setZoom(zoom, { animate: true });
      setTimeout(() => mapRef.current.invalidateSize(), 100);
      setTimeout(() => mapRef.current.invalidateSize(), 500);
    }
  }, [isExpanded, location]);

  const toggleLayer = (layer: keyof typeof layers) => {
    setLayers(prev => ({ ...prev, [layer]: !prev[layer] }));
  };

  return (
    <div className="w-full h-full relative bg-slate-200 transition-all duration-500 overflow-hidden">
      <div 
        ref={mapContainerRef} 
        className="w-full h-full absolute inset-0 z-0 bg-slate-200" 
        style={{ minHeight: '100%' }}
      />

      {/* HUD OVERLAY */}
      <div className="absolute top-4 left-4 z-[1000] flex flex-col gap-3 pointer-events-none max-w-[220px]">
        <div className="glass-panel px-4 py-2.5 rounded-2xl text-[11px] font-black text-slate-800 shadow-xl border border-white/60 flex items-center gap-2.5 pointer-events-auto">
          <span className="w-2.5 h-2.5 bg-blue-600 rounded-full animate-pulse shadow-[0_0_8px_rgba(59,130,246,0.6)]" aria-hidden="true"></span>
