        <button 
          onClick={() => setIsSatellite(!isSatellite)}
          className={`glass-panel px-5 py-3.5 rounded-2xl shadow-2xl border flex items-center gap-4 pointer-events-auto transition-all active:scale-[0.98] group ${isSatellite ? 'bg-slate-900 border-blue-500 text-white' : 'bg-white border-white/60 text-slate-900'}`}
          aria-label={isSatellite ? "Switch to Street View" : "Switch to Satellite View"}
        >
          <div className="w-10 h-10 rounded-xl bg-slate-100 flex items-center justify-center text-xl shadow-inner border border-slate-200 group-hover:scale-110 transition-transform" aria-hidden="true">
             {isSatellite ? '🏙️' : '🌍'}
          </div>
          <div className="text-left pr-2">
            <p className={`text-[9px] font-black uppercase tracking-widest leading-none mb-1 ${isSatellite ? 'text-blue-400' : 'text-slate-500'}`}>Layer mode</p>
            <p className="text-xs font-black uppercase tracking-tighter">{isSatellite ? 'Satellite' : 'Roadmap'}</p>
