import React, { useEffect, useRef, useState } from 'react';
import { GeoLocation } from '../types';

interface MapProps {
  location: GeoLocation;
  name: string;
  isExpanded?: boolean;
}

interface WeatherInfo {
  temp: number;
  windSpeed: number;
  conditionCode: number;
  conditionText: string;
}

type MapMode = 'street' | 'satellite' | 'topo';

export const Map: React.FC<MapProps> = ({ location, name, isExpanded }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const baseLayerRef = useRef<any>(null);

  // GIS Layer Groups
  const parcelsLayerRef = useRef<any>(null);
  const utilitiesLayerRef = useRef<any>(null);
  const greeneryLayerRef = useRef<any>(null);
  const householdLayerRef = useRef<any>(null);
  const heatmapLayerRef = useRef<any>(null);

  const [streetViewCoords, setStreetViewCoords] = useState<{lat: number, lng: number} | null>(null);
  const [weatherInfo, setWeatherInfo] = useState<WeatherInfo | null>(null);
  const [mapMode, setMapMode] = useState<MapMode>('street');

  const [layers, setLayers] = useState({
    parcels: true,
    utilities: true,
    greenery: true,
    households: true,
    heatmap: true
  });

  const getWeatherText = (code: number) => {
    if (code === 0) return 'Clear Sky';
    if (code <= 3) return 'Partly Cloudy';
    if (code <= 48) return 'Foggy';
    if (code <= 67) return 'Rain / Drizzle';
    if (code <= 77) return 'Snow';
    if (code <= 99) return 'Thunderstorm';
    return 'Overcast';
  };

  const fetchWeatherData = async () => {
    try {
      const response = await fetch(
        `https://api.open-meteo.com/v1/forecast?latitude=${location.lat}&longitude=${location.lng}&current_weather=true`
      );
      const data = await response.json();
      if (data.current_weather) {
        setWeatherInfo({
          temp: data.current_weather.temperature,
          windSpeed: data.current_weather.windspeed,
          conditionCode: data.current_weather.weathercode,
          conditionText: getWeatherText(data.current_weather.weathercode)
        });
      }
    } catch (err) {
      console.error("Weather sync failed", err);
    }
  };

  const updateBaseLayer = () => {
    if (!mapRef.current) return;
    const L = (window as any).L;

    if (baseLayerRef.current) {
      mapRef.current.removeLayer(baseLayerRef.current);
    }

    let url = '';
    let attribution = '';
    let maxZoom = 20;

    switch (mapMode) {
      case 'satellite':
        url = 'https://mt1.google.com/vt/lyrs=y&x={x}&y={y}&z={z}';
        attribution = 'Map data &copy; Google';
        break;
      case 'topo':
        url = 'https://basemap.nationalmap.gov/arcgis/rest/services/USGSTopo/MapServer/tile/{z}/{y}/{x}';
        attribution = 'Tiles courtesy of the U.S. Geological Survey';
        maxZoom = 16; // USGS Topo tiles usually cap at 16
        break;
      case 'street':
      default:
        url = 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png';
        attribution = '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors';
        break;
    }

    baseLayerRef.current = L.tileLayer(url, {
      attribution: attribution,
      maxZoom: maxZoom,
      subdomains: mapMode === 'satellite' ? ['mt0', 'mt1', 'mt2', 'mt3'] : ['a', 'b', 'c']
    }).addTo(mapRef.current);

    baseLayerRef.current.bringToBack();
  };

  useEffect(() => {
    if (!mapContainerRef.current) return;
    const L = (window as any).L;
    if (!L) return;

    if (!mapRef.current) {
      mapRef.current = L.map(mapContainerRef.current, {
        zoomControl: false,
        attributionControl: true
      }).setView([location.lat, location.lng], 15);

      L.control.zoom({ position: 'bottomleft' }).addTo(mapRef.current);

      updateBaseLayer();

      // Initialize Groups
      parcelsLayerRef.current = L.layerGroup().addTo(mapRef.current);
      utilitiesLayerRef.current = L.layerGroup().addTo(mapRef.current);
      greeneryLayerRef.current = L.layerGroup().addTo(mapRef.current);
      householdLayerRef.current = L.layerGroup().addTo(mapRef.current);

      // 1. Refined Parcels
      const parcelStyle = { color: '#3b82f6', weight: 1, fillOpacity: 0.12, fillColor: '#93c5fd' };
      for (let i = -3; i <= 3; i++) {
        for (let j = -3; j <= 3; j++) {
          if ((i + j) % 2 === 0) continue;
          L.rectangle([
            [location.lat + i * 0.0008, location.lng + j * 0.0012],
            [location.lat + (i + 0.7) * 0.0008, location.lng + (j + 0.9) * 0.0012]
          ], parcelStyle).addTo(parcelsLayerRef.current).bindTooltip("Legal Parcel Boundary");
        }
      }

      // 2. Refined Utilities
      const utilityStyle = { color: '#f59e0b', weight: 3, dashArray: '10, 10', opacity: 0.9 };
      L.polyline([[location.lat - 0.006, location.lng + 0.002], [location.lat + 0.006, location.lng - 0.002]], utilityStyle).addTo(utilitiesLayerRef.current).bindTooltip("Main Utility Trunk Line");
      L.polyline([[location.lat + 0.002, location.lng - 0.006], [location.lat - 0.002, location.lng + 0.006]], { ...utilityStyle, color: '#fbbf24' }).addTo(utilitiesLayerRef.current);

      // 3. Refined Greenery
      const greenStyle = { color: '#047857', weight: 1, fillOpacity: 0.4, fillColor: '#10b981' };
      L.circle([location.lat + 0.004, location.lng - 0.004], { radius: 220, ...greenStyle }).addTo(greeneryLayerRef.current).bindTooltip("Public Park Space");
      L.circle([location.lat - 0.003, location.lng + 0.005], { radius: 150, ...greenStyle }).addTo(greeneryLayerRef.current).bindTooltip("Preserved Green Space");

      const pings: [number, number, number][] = [
        [location.lat + 0.001, location.lng + 0.001, 1],
        [location.lat - 0.0015, location.lng - 0.001, 0.8],
        [location.lat + 0.002, location.lng - 0.0012, 0.7],
        [location.lat + 0.0005, location.lng - 0.002, 0.6]
      ];

      pings.forEach((p, idx) => {
        L.circleMarker([p[0], p[1]], { radius: 6, color: '#1e293b', fillColor: '#334155', fillOpacity: 1, weight: 2 }).addTo(householdLayerRef.current).bindPopup(`
          <div class="p-1">
            <b class="text-slate-900 block text-xs mb-1">Node CT-${idx + 400}</b>
            <p class="text-[10px] text-slate-500 font-bold uppercase mb-2">Resident Mesh Active</p>
            <button onclick="window.dispatchEvent(new CustomEvent('open-street-view', {detail: {lat: ${p[0]}, lng: ${p[1]}}}))" class="w-full bg-blue-600 text-white text-[10px] font-black py-1.5 rounded-lg hover:bg-blue-700 transition-colors uppercase">
              Street View
            </button>
          </div>
        `);
      });

      if (L.heatLayer) {
        heatmapLayerRef.current = L.heatLayer(pings, {
          radius: 45,
          blur: 20,
          maxZoom: 18,
          gradient: { 0.4: '#3b82f6', 0.65: '#10b981', 1: '#f43f5e' }
        }).addTo(mapRef.current);
      }

      const handleSVOpen = (e: any) => setStreetViewCoords(e.detail);
      window.addEventListener('open-street-view', handleSVOpen);

      return () => {
        window.removeEventListener('open-street-view', handleSVOpen);
      };
    } else {
      mapRef.current.setView([location.lat, location.lng], mapRef.current.getZoom());
    }

    const observer = new ResizeObserver(() => {
      if (mapRef.current) mapRef.current.invalidateSize();
    });
    observer.observe(mapContainerRef.current);

    fetchWeatherData();

    return () => {
      observer.disconnect();
    };
  }, [location]);

  useEffect(() => {
    updateBaseLayer();
  }, [mapMode]);

  // Handle Layer Visibilities
  useEffect(() => {
    if (!mapRef.current) return;
    const toggleGroup = (ref: any, visible: boolean) => {
      if (!ref.current) return;
      if (visible) {
        if (!mapRef.current.hasLayer(ref.current)) ref.current.addTo(mapRef.current);
      } else {
        if (mapRef.current.hasLayer(ref.current)) mapRef.current.removeLayer(ref.current);
      }
    };

    toggleGroup(parcelsLayerRef, layers.parcels);
    toggleGroup(utilitiesLayerRef, layers.utilities);
    toggleGroup(greeneryLayerRef, layers.greenery);
    toggleGroup(householdLayerRef, layers.households);
    toggleGroup(heatmapLayerRef, layers.heatmap);
  }, [layers]);

  useEffect(() => {
    if (mapRef.current) {
      const zoom = isExpanded ? 17 : 15;
      mapRef.current.setZoom(zoom, { animate: true });
      setTimeout(() => mapRef.current.invalidateSize(), 100);
      setTimeout(() => mapRef.current.invalidateSize(), 500);
    }
  }, [isExpanded, location]);

  const toggleLayer = (layer: keyof typeof layers) => {
    setLayers(prev => ({ ...prev, [layer]: !prev[layer] }));
  };

  return (
    <div className="w-full h-full relative bg-slate-200 transition-all duration-500 overflow-hidden">
      <div 
        ref={mapContainerRef} 
        className="w-full h-full absolute inset-0 z-0 bg-slate-200" 
        style={{ minHeight: '100%' }}
      />

      {/* HUD OVERLAY */}
      <div className="absolute top-4 left-4 z-[1000] flex flex-col gap-3 pointer-events-none max-w-[220px]">
        <div className="glass-panel px-4 py-2.5 rounded-2xl text-[11px] font-black text-slate-800 shadow-xl border border-white/60 flex items-center gap-2.5 pointer-events-auto">
          <span className="w-2.5 h-2.5 bg-blue-600 rounded-full animate-pulse shadow-[0_0_8px_rgba(59,130,246,0.6)]" aria-hidden="true"></span>
          GIS ACTIVE ENGINE
        </div>

        {/* Base Map Mode Selection */}
        <div className="glass-panel p-1.5 rounded-2xl shadow-xl border border-white/60 pointer-events-auto bg-white/95 backdrop-blur-md flex flex-col gap-1">
          <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest px-2 pt-1 mb-1 leading-none">Map Base Mode</p>
          <div className="grid grid-cols-1 gap-1">
            {[
              { id: 'street', label: 'Street', icon: '🏙️' },
              { id: 'satellite', label: 'Satellite', icon: '🌍' },
              { id: 'topo', label: 'USGS Topo', icon: '⛰️' }
            ].map((mode) => (
              <button
                key={mode.id}
                onClick={() => setMapMode(mode.id as MapMode)}
                className={`flex items-center gap-3 px-3 py-2 rounded-xl text-[10px] font-black uppercase transition-all border shadow-sm ${mapMode === mode.id ? 'bg-slate-900 text-white border-slate-700' : 'bg-white text-slate-400 border-slate-200 hover:bg-slate-50'}`}
              >
                <span className="text-sm shrink-0" aria-hidden="true">{mode.icon}</span>
                <span className="truncate">{mode.label}</span>
                {mapMode === mode.id && <div className="ml-auto w-2 h-2 bg-blue-500 rounded-full" aria-hidden="true"></div>}
              </button>
            ))}
          </div>
        </div>

        <div className="glass-panel p-3 rounded-2xl shadow-xl border border-white/60 pointer-events-auto bg-white/95 backdrop-blur-md flex flex-col gap-1.5">
           <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest px-1 mb-1 leading-none">Spatial Overlays</p>
           {[
             { id: 'parcels', label: 'Parcels', icon: '📦', color: 'bg-blue-600' },
             { id: 'utilities', label: 'Utilities', icon: '⚡', color: 'bg-amber-500' },
             { id: 'greenery', label: 'Greenery', icon: '🌳', color: 'bg-emerald-600' }
           ].map(layer => (
             <button
               key={layer.id}
               onClick={() => toggleLayer(layer.id as any)}
               className={`flex items-center gap-3 px-3 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all border shadow-sm ${layers[layer.id as keyof typeof layers] ? 'bg-slate-900 text-white border-slate-700' : 'bg-white text-slate-400 border-slate-200 hover:bg-slate-50'}`}
             >
               <div className={`w-3 h-3 rounded-full ${layers[layer.id as keyof typeof layers] ? layer.color : 'bg-slate-200'}`} aria-hidden="true" />
               <span className="truncate">{layer.label}</span>
               <span className="ml-auto opacity-50">{layer.icon}</span>
             </button>
           ))}
        </div>

        {weatherInfo && (
          <div className="glass-panel px-4 py-3 rounded-2xl shadow-xl border border-white/60 flex flex-col gap-1 pointer-events-auto bg-white/90 backdrop-blur-md">
            <div className="flex items-center gap-3">
              <span className="text-xl" aria-hidden="true">
                {weatherInfo.conditionCode < 3 ? '☀️' : weatherInfo.conditionCode < 50 ? '☁️' : '🌧️'}
              </span>
              <div>
                <p className="text-[10px] font-black text-slate-900 uppercase tracking-widest leading-none mb-1">{weatherInfo.conditionText}</p>
                <div className="flex items-baseline gap-1">
                  <span className="text-base font-black text-slate-900 leading-none">{weatherInfo.temp}°C</span>
                  <span className="text-[9px] font-bold text-slate-500 uppercase tracking-tighter">Live</span>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Street View Embed Overlay */}
      {streetViewCoords && (
        <div className="absolute inset-0 z-[3000] bg-slate-900 animate-in fade-in zoom-in-95 duration-300">
          <header className="absolute top-4 left-4 right-4 z-[3100] flex justify-between items-center px-6 py-3 bg-white/90 backdrop-blur-md rounded-2xl border border-white/50 shadow-2xl">
            <div className="flex items-center gap-4">
              <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white text-sm" aria-hidden="true">👁️</div>
              <div>
                <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Spatial Analysis</p>
                <h4 className="text-[11px] font-bold text-slate-900">Digital Immersion Point</h4>
              </div>
            </div>
            <button 
              onClick={() => setStreetViewCoords(null)}
              className="w-10 h-10 flex items-center justify-center bg-slate-100 hover:bg-slate-200 text-slate-900 rounded-full font-black text-lg transition-all"
            >✕</button>
          </header>
          <iframe
            title="Google Street View"
            className="w-full h-full border-0"
            loading="lazy"
            allowFullScreen
            src={`https://www.google.com/maps/embed/v1/streetview?key=${process.env.API_KEY}&location=${streetViewCoords.lat},${streetViewCoords.lng}`}
          ></iframe>
        </div>
      )}

      {/* LEGEND HUD */}
      {isExpanded && !streetViewCoords && (
        <div className="absolute bottom-6 right-6 z-[1000] glass-panel p-5 rounded-[2rem] border border-white/60 shadow-2xl animate-in slide-in-from-bottom duration-500 w-[260px]">
          <div className="flex items-center justify-between mb-4">
            <h4 className="text-[11px] font-black text-slate-600 uppercase tracking-widest">Active Legenda</h4>
            <div className="text-[9px] font-black text-blue-600 bg-blue-50 px-2 py-0.5 rounded-full uppercase tracking-tighter">GIS v2.4</div>
          </div>
          <div className="space-y-2">
            {[
              { id: 'parcels', label: 'Parcel Polygons', color: 'bg-blue-600/10', dot: 'bg-blue-600' },
              { id: 'utilities', label: 'Utility Infrastructure', color: 'bg-amber-600/10', dot: 'bg-amber-500' },
              { id: 'greenery', label: 'Park Boundaries', color: 'bg-emerald-600/10', dot: 'bg-emerald-600' },
              { id: 'heatmap', label: 'Consumption Heat', color: 'bg-rose-600/10', dot: 'bg-rose-500' }
            ].map((layer) => (
              <div key={layer.id} className={`flex items-center gap-3 p-2 rounded-xl transition-all ${(layers as any)[layer.id] ? 'opacity-100' : 'opacity-30 grayscale'}`}>
                <div className={`w-3 h-3 rounded-full ${layer.dot}`} aria-hidden="true" />
                <span className="text-[11px] font-black text-slate-700 block uppercase tracking-tight truncate">{layer.label}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { GeoLocation } from '../types';

interface MapProps {
  location: GeoLocation;
  name: string;
  isExpanded?: boolean;
}

interface WeatherInfo {
  temp: number;
  windSpeed: number;
  conditionCode: number;
  conditionText: string;
}

type MapMode = 'street' | 'satellite' | 'topo';

export const Map: React.FC<MapProps> = ({ location, name, isExpanded }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const baseLayerRef = useRef<any>(null);

  // GIS Layer Groups
  const parcelsLayerRef = useRef<any>(null);
  const utilitiesLayerRef = useRef<any>(null);
  const greeneryLayerRef = useRef<any>(null);
  const householdLayerRef = useRef<any>(null);
  const heatmapLayerRef = useRef<any>(null);

  const [streetViewCoords, setStreetViewCoords] = useState<{lat: number, lng: number} | null>(null);
  const [weatherInfo, setWeatherInfo] = useState<WeatherInfo | null>(null);
  const [mapMode, setMapMode] = useState<MapMode>('street');

  const [layers, setLayers] = useState({
    parcels: true,
    utilities: true,
    greenery: true,
    households: true,
    heatmap: true
  });

  const getWeatherText = (code: number) => {
    if (code === 0) return 'Clear Sky';
    if (code <= 3) return 'Partly Cloudy';
    if (code <= 48) return 'Foggy';
    if (code <= 67) return 'Rain / Drizzle';
    if (code <= 77) return 'Snow';
    if (code <= 99) return 'Thunderstorm';
    return 'Overcast';
  };

  const fetchWeatherData = async () => {
    try {
      const response = await fetch(
        `https://api.open-meteo.com/v1/forecast?latitude=${location.lat}&longitude=${location.lng}&current_weather=true`
      );
      const data = await response.json();
      if (data.current_weather) {
        setWeatherInfo({
          temp: data.current_weather.temperature,
          windSpeed: data.current_weather.windspeed,
          conditionCode: data.current_weather.weathercode,
          conditionText: getWeatherText(data.current_weather.weathercode)
        });
      }
    } catch (err) {
      console.error("Weather sync failed", err);
    }
  };

  const updateBaseLayer = () => {
    if (!mapRef.current) return;
    const L = (window as any).L;
    if (!L) return;

    if (baseLayerRef.current) {
      mapRef.current.removeLayer(baseLayerRef.current);
    }

    let url = '';
    let options: any = { maxZoom: 20 };

    switch (mapMode) {
      case 'satellite':
        // Using Google Hybrid (Satelite + Roads)
        url = 'https://{s}.google.com/vt/lyrs=y&x={x}&y={y}&z={z}';
        options = {
          ...options,
          subdomains: ['mt0', 'mt1', 'mt2', 'mt3'],
          attribution: 'Map data &copy; Google'
        };
        break;
      case 'topo':
        url = 'https://basemap.nationalmap.gov/arcgis/rest/services/USGSTopo/MapServer/tile/{z}/{y}/{x}';
