    if (mapRef.current) {
      const zoom = isExpanded ? 17 : 15;
      mapRef.current.setZoom(zoom, { animate: true });

      // Call invalidateSize multiple times during the transition to ensure full coverage
      const intervals = [50, 200, 500, 1000];
      intervals.forEach(ms => {
        setTimeout(() => mapRef.current?.invalidateSize(), ms);
      });
    }
  }, [isExpanded]);

