        };
        break;
    }

    baseLayerRef.current = L.tileLayer(url, options).addTo(mapRef.current);
    baseLayerRef.current.bringToBack();
  };

  // 1. Initial Setup and Lifecycle
  useEffect(() => {
    if (!mapContainerRef.current) return;
    const L = (window as any).L;
    if (!L) return;

    // Check for container size to prevent IndexSizeError in canvas-based layers (like heatmaps)
    if (mapContainerRef.current.clientWidth === 0 || mapContainerRef.current.clientHeight === 0) {
      const retryTimeout = setTimeout(() => {
