import React, { useState, useRef, useEffect } from 'react';
import { TwinMetadata, ChatMessage } from '../types';
import { chatWithMapsGrounding } from '../services/geminiService';

interface AIChatPanelProps {
  metadata: TwinMetadata | null;
  onClose: () => void;
}

export const AIChatPanel: React.FC<AIChatPanelProps> = ({ metadata, onClose }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: `Hello! I am the Civic AI assistant for ${metadata?.name || 'your community'}. How can I help you explore the Digital Twin today?`, timestamp: new Date().toLocaleTimeString() }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMsg: ChatMessage = { role: 'user', text: input, timestamp: new Date().toLocaleTimeString() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      const response = await chatWithMapsGrounding(input, metadata);
      const modelMsg: ChatMessage = { 
        role: 'model', 
        text: response.text + (response.sources.length > 0 ? '\n\nSources:\n' + response.sources.join('\n') : ''), 
        timestamp: new Date().toLocaleTimeString() 
      };
      setMessages(prev => [...prev, modelMsg]);
    } catch (err) {
      setMessages(prev => [...prev, { role: 'model', text: "Sorry, I'm having trouble connecting to the cloud nodes.", timestamp: new Date().toLocaleTimeString() }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed bottom-24 right-6 z-[4000] w-full max-w-[400px] h-[600px] bg-white rounded-[2.5rem] shadow-2xl border border-slate-200 flex flex-col overflow-hidden animate-in slide-in-from-bottom duration-300">
      <header className="px-8 py-6 bg-slate-900 text-white flex justify-between items-center">
        <div>
          <h3 className="text-lg font-black tracking-tight">Civic Assistant</h3>
          <p className="text-[10px] text-blue-400 font-black uppercase tracking-widest">Maps Grounded AI</p>
        </div>
        <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors font-black">✕</button>
      </header>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] px-5 py-3 rounded-2xl text-sm font-medium shadow-sm ${
              m.role === 'user' ? 'bg-blue-600 text-white rounded-br-none' : 'bg-white text-slate-800 border border-slate-200 rounded-bl-none'
            }`}>
              <p className="whitespace-pre-wrap">{m.text}</p>
              <span className={`text-[8px] font-black uppercase block mt-1 opacity-50 ${m.role === 'user' ? 'text-right' : 'text-left'}`}>
                {m.timestamp}
              </span>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white border border-slate-200 px-5 py-3 rounded-2xl rounded-bl-none shadow-sm flex items-center gap-2">
              <span className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-bounce"></span>
              <span className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-bounce delay-75"></span>
              <span className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-bounce delay-150"></span>
            </div>
          </div>
        )}
      </div>

      <form onSubmit={handleSend} className="p-6 bg-white border-t border-slate-200 flex gap-3">
        <input 
          type="text" 
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Ask about places, news, or city data..."
          className="flex-1 px-5 py-4 bg-slate-100 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-blue-600/20 text-sm font-medium"
        />
        <button type="submit" className="w-12 h-12 bg-blue-600 text-white rounded-2xl flex items-center justify-center shadow-lg hover:scale-105 active:scale-95 transition-all">
          <span className="text-xl">➔</span>
        </button>
      </form>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { TwinMetadata } from '../types';
import { getLiveAudioSession } from '../services/geminiService';

interface LiveAudioPanelProps {
  metadata: TwinMetadata | null;
  onClose: () => void;
}

export const LiveAudioPanel: React.FC<LiveAudioPanelProps> = ({ metadata, onClose }) => {
  const [isActive, setIsActive] = useState(false);
  const [transcription, setTranscription] = useState('');
  const [isConnecting, setIsConnecting] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const outputNodeRef = useRef<GainNode | null>(null);
  const sessionRef = useRef<any>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  const decodeAudio = (base64: string) => {
    const binaryString = atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number) => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const encodeAudio = (bytes: Uint8Array) => {
    let binary = '';
    for (let i = 0; i < bytes.byteLength; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  };

  const startSession = async () => {
    setIsConnecting(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      outputNodeRef.current = audioContextRef.current.createGain();
      outputNodeRef.current.connect(audioContextRef.current.destination);

      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });

      const callbacks = {
        onopen: () => {
          setIsActive(true);
          setIsConnecting(false);
          const source = inputCtx.createMediaStreamSource(stream);
          const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
          scriptProcessor.onaudioprocess = (e) => {
            const inputData = e.inputBuffer.getChannelData(0);
            const int16 = new Int16Array(inputData.length);
            for (let i = 0; i < inputData.length; i++) {
              int16[i] = inputData[i] * 32768;
            }
            const base64 = encodeAudio(new Uint8Array(int16.buffer));
            sessionRef.current?.sendRealtimeInput({ media: { data: base64, mimeType: 'audio/pcm;rate=16000' } });
          };
          source.connect(scriptProcessor);
          scriptProcessor.connect(inputCtx.destination);
        },
        onmessage: async (msg: any) => {
          const audioStr = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (audioStr && audioContextRef.current) {
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, audioContextRef.current.currentTime);
            const buffer = await decodeAudioData(decodeAudio(audioStr), audioContextRef.current, 24000, 1);
            const source = audioContextRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(outputNodeRef.current!);
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += buffer.duration;
            sourcesRef.current.add(source);
            source.onended = () => sourcesRef.current.delete(source);
          }

          if (msg.serverContent?.outputTranscription) {
            setTranscription(prev => (prev + ' ' + msg.serverContent.outputTranscription.text).slice(-200));
          }
        },
        onclose: () => setIsActive(false),
        onerror: (e: any) => console.error("Live Audio Error", e),
      };

      const sessionPromise = getLiveAudioSession(callbacks, metadata);
      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error("Failed to start voice session", err);
      setIsConnecting(false);
    }
  };

  const stopSession = () => {
    sessionRef.current?.close();
    sourcesRef.current.forEach(s => s.stop());
    sourcesRef.current.clear();
    setIsActive(false);
  };

  useEffect(() => {
    return () => stopSession();
  }, []);

  return (
    <div className="fixed inset-0 z-[5000] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-xl animate-in fade-in duration-300">
      <div className="w-full max-w-lg bg-slate-900 border border-slate-800 rounded-[3rem] p-10 shadow-2xl text-center space-y-8 animate-in zoom-in-95 duration-300">
        <div className="relative inline-block">
          <div className={`w-32 h-32 rounded-full bg-blue-600/20 border-2 border-blue-500 flex items-center justify-center text-4xl shadow-2xl transition-all duration-500 ${isActive ? 'scale-110 shadow-blue-500/50 animate-pulse' : ''}`}>
            {isActive ? '🎙️' : '🔇'}
          </div>
          {isActive && (
            <div className="absolute inset-0 rounded-full border-4 border-blue-500 animate-ping opacity-20"></div>
          )}
        </div>

        <div className="space-y-2">
          <h2 className="text-3xl font-black text-white tracking-tight">Civic Voice Control</h2>
          <p className="text-xs font-black text-blue-400 uppercase tracking-[0.3em]">Native Audio Live API</p>
        </div>

        <div className="bg-slate-950 rounded-2xl p-6 h-32 flex flex-col items-center justify-center text-slate-400 italic font-medium text-sm border border-slate-800 shadow-inner overflow-hidden">
          {isActive ? (
            <p className="animate-in fade-in duration-500 line-clamp-3">{transcription || "Listening for your voice..."}</p>
          ) : (
            <p>System offline. Tap to connect to the community mesh.</p>
          )}
        </div>

        <div className="flex gap-4">
          {!isActive ? (
            <button 
              onClick={startSession}
              disabled={isConnecting}
              className="flex-1 py-5 bg-blue-600 hover:bg-blue-500 text-white font-black rounded-2xl shadow-xl transition-all active:scale-95 disabled:opacity-50 uppercase text-xs tracking-widest"
            >
              {isConnecting ? 'Initializing Mesh...' : 'Connect to Voice Hub'}
            </button>
          ) : (
            <button 
              onClick={stopSession}
              className="flex-1 py-5 bg-rose-600 hover:bg-rose-500 text-white font-black rounded-2xl shadow-xl transition-all active:scale-95 uppercase text-xs tracking-widest"
            >
              Disconnect Session
            </button>
          )}
          <button 
            onClick={onClose}
            className="px-8 py-5 bg-slate-800 text-slate-400 font-black rounded-2xl hover:text-white transition-colors uppercase text-xs tracking-widest"
          >
            Close
          </button>
        </div>

        <div className="flex items-center justify-center gap-6 pt-4 border-t border-slate-800/50">
          <span className="text-[10px] font-black text-slate-600 uppercase tracking-widest">24kHz PCM Audio</span>
          <div className="h-4 w-px bg-slate-800"></div>
          <span className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Low Latency Fog Sync</span>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { TwinMetadata, NeighborhoodBLan, ConnectivityStatus, TrafficSimState } from '../types';
import { Map } from './Map';

interface GISAnalysisProps {
  metadata: TwinMetadata;
  connectivity: ConnectivityStatus;
}

type AnalysisModule = 'connectivity' | 'water' | 'traffic' | 'emergency';

export const GISAnalysis: React.FC<GISAnalysisProps> = ({ metadata, connectivity }) => {
  const [activeModule, setActiveModule] = useState<AnalysisModule>('connectivity');
  const [simulationActive, setSimulationActive] = useState(false);
  const [simLogs, setSimLogs] = useState<string[]>([]);
  const [targetCid, setTargetCid] = useState<string>('all');

  // Traffic Simulation State
  const [trafficSim, setTrafficSim] = useState<TrafficSimState>({
    publicTransportAvailability: 45,
    trafficDensity: 60,
    peakHourDelay: 22
  });

  const isFogMode = connectivity === 'offline-fog';
  const [neighborhoods, setNeighborhoods] = useState<NeighborhoodBLan[]>([]);

  useEffect(() => {
    const generated = metadata.cids.map((cid) => ({
      name: cid.name,
      nodes: Math.floor(Math.random() * 200) + 50,
      health: cid.meshActive ? 95 : 40,
      status: (cid.meshActive ? 'stable' : 'degraded') as NeighborhoodBLan['status'],
      cid: cid.id
    }));
    setNeighborhoods(generated);
  }, [metadata]);

  // Recalculate Peak Hour Delay based on simulation params
  useEffect(() => {
    const baseDelay = 10;
    const densityImpact = (trafficSim.trafficDensity / 100) * 40;
    const transportRelief = (trafficSim.publicTransportAvailability / 100) * 15;
    const calculatedDelay = Math.max(0, Math.round(baseDelay + densityImpact - transportRelief));

    setTrafficSim(prev => ({ ...prev, peakHourDelay: calculatedDelay }));
  }, [trafficSim.publicTransportAvailability, trafficSim.trafficDensity]);

  const addLog = (msg: string) => {
    setSimLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev].slice(0, 15));
  };

  const handleSimChange = (param: keyof TrafficSimState, value: number) => {
    setTrafficSim(prev => ({ ...prev, [param]: value }));
    addLog(`Sim Parameter Changed: ${param} set to ${value}%`);
  };

  const broadcastCidAlert = async () => {
    setSimulationActive(true);
    const scope = targetCid === 'all' ? 'GLOBAL REGION' : `CID-${targetCid}`;
    addLog(`BROADCASTING TO ${scope} via B-LAN CORE...`);
    await new Promise(r => setTimeout(r, 1200));
    addLog(`ALERT DISPATCHED: "Emergency Fog Node optimization complete for ${scope}"`);
    setSimulationActive(false);
  };

  return (
    <div className="flex-1 flex flex-col lg:flex-row min-h-0 bg-slate-950 text-slate-200 overflow-hidden">
      <aside className="w-full lg:w-[420px] border-r border-slate-800 flex flex-col overflow-hidden">
        <header className="p-6 border-b border-slate-800 bg-slate-900/50">
           <h2 className="text-xl font-black text-white tracking-tight">Tactical GIS Core</h2>
           <p className="text-xs font-black text-amber-500 uppercase tracking-widest">
             {isFogMode ? "FOG NETWORK ACTIVE" : "SYNCHRONIZED WITH CLOUD"}
           </p>
        </header>

        <nav className="flex border-b border-slate-800 overflow-x-auto no-scrollbar">
          {(['connectivity', 'water', 'traffic', 'emergency'] as AnalysisModule[]).map(mod => (
            <button
              key={mod}
              onClick={() => setActiveModule(mod)}
              className={`flex-1 min-w-[100px] py-5 text-xs font-black uppercase tracking-widest transition-all ${
                activeModule === mod ? 'text-white border-b-2 border-amber-500 bg-slate-900' : 'text-slate-400 hover:text-slate-200'
              }`}
            >
              {mod}
            </button>
          ))}
        </nav>

        <div className="flex-1 overflow-y-auto p-6 space-y-8 scrollbar-thin scrollbar-thumb-slate-800">

          {activeModule === 'traffic' && (
            <div className="space-y-8 animate-in fade-in duration-300">
              <section className="space-y-6">
                <h3 className="text-xs font-black text-blue-400 uppercase tracking-widest">Urban Flow Parameters</h3>

                <div className="space-y-4">
                  <div className="space-y-2">
                    <div className="flex justify-between text-[10px] font-black uppercase text-slate-400">
                      <span>Public Transport Availability</span>
                      <span className="text-blue-400">{trafficSim.publicTransportAvailability}%</span>
                    </div>
                    <input 
                      type="range" 
                      min="0" max="100" 
                      value={trafficSim.publicTransportAvailability}
                      onChange={(e) => handleSimChange('publicTransportAvailability', parseInt(e.target.value))}
                      className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-500"
                    />
                  </div>

                  <div className="space-y-2">
                    <div className="flex justify-between text-[10px] font-black uppercase text-slate-400">
                      <span>Traffic Density</span>
                      <span className="text-rose-400">{trafficSim.trafficDensity}%</span>
                    </div>
                    <input 
                      type="range" 
                      min="0" max="100" 
                      value={trafficSim.trafficDensity}
                      onChange={(e) => handleSimChange('trafficDensity', parseInt(e.target.value))}
                      className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-rose-500"
                    />
                  </div>
                </div>

                <div className="p-6 bg-slate-900 border border-slate-800 rounded-[2rem] text-center shadow-xl">
                  <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Projected Peak Hour Delay</p>
                  <p className="text-5xl font-black text-white tracking-tighter">
                    {trafficSim.peakHourDelay} <span className="text-sm text-slate-500 uppercase">min</span>
                  </p>
                  <p className="text-[9px] font-bold text-blue-400 mt-2 italic">Calculated via Civic Twin Simulation Engine</p>
                </div>
              </section>
            </div>
          )}

          {activeModule === 'emergency' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-left duration-300">
              <section className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-xs font-black text-amber-500 uppercase tracking-widest">B-LAN CID Targeting</h3>
                  <select 
                    value={targetCid}
                    onChange={(e) => setTargetCid(e.target.value)}
                    className="bg-slate-900 border border-slate-700 rounded-lg px-2 py-1 text-[10px] font-black text-blue-400 outline-none"
                  >
                    <option value="all">Global Broadcast</option>
                    {metadata.cids.map(c => <option key={c.id} value={c.id}>CID-{c.id} ({c.name})</option>)}
                  </select>
                </div>

                <div className="grid grid-cols-1 gap-3">
                  {neighborhoods.map(n => (
                    <div key={n.cid} className="p-4 bg-slate-900 border border-slate-800 rounded-2xl">
                      <div className="flex justify-between items-center mb-2">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">CID-{n.cid}</span>
                        <span className={`w-2 h-2 rounded-full ${n.status === 'stable' ? 'bg-emerald-500' : 'bg-rose-500'}`}></span>
                      </div>
                      <p className="text-sm font-black text-white truncate mb-4">{n.name}</p>
                      <div className="h-1 w-full bg-slate-800 rounded-full overflow-hidden">
                        <div className="h-full bg-blue-500" style={{ width: `${n.health}%` }}></div>
                      </div>
                    </div>
                  ))}
                </div>
              </section>

              <button 
                onClick={broadcastCidAlert}
                disabled={simulationActive}
                className="w-full py-5 bg-amber-600 hover:bg-amber-500 text-slate-950 font-black rounded-2xl shadow-xl transition-all uppercase text-xs tracking-widest flex items-center justify-center gap-2 active:scale-95"
              >
                📡 BROADCAST TARGETED ALERT
              </button>
            </div>
          )}

          <section className="pt-8 border-t border-slate-800 space-y-4">
            <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest">Digital Twin Logs (Fog Active)</h4>
            <div className="h-[250px] bg-slate-950 border border-slate-800 rounded-2xl p-5 font-mono text-xs space-y-3 overflow-y-auto">
              {simLogs.map((log, i) => (
                <div key={i} className={`font-bold ${log.includes('ALERT') ? 'text-amber-400' : 'text-slate-400'}`}>
                  {log}
                </div>
              ))}
            </div>
          </section>
        </div>
      </aside>

      <div className="flex-1 relative overflow-hidden">
        <Map location={metadata.location!} name={`${metadata.name} | B-LAN ANALYSIS`} isExpanded={true} />

        {simulationActive && (
          <div className="absolute inset-0 z-[2000] flex items-center justify-center bg-black/40 backdrop-blur-sm pointer-events-none">
            <div className="p-10 rounded-3xl border border-amber-500/50 bg-slate-900 shadow-2xl animate-pulse text-center">
               <h3 className="text-2xl font-black text-white uppercase tracking-tight">Syncing B-LAN Hubs</h3>
               <p className="text-amber-400 font-bold">CID Communities within Mesh network...</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Layout } from './components/Layout';
import { Onboarding } from './components/Onboarding';
import { Dashboard } from './components/Dashboard';
import { GISAnalysis } from './components/GISAnalysis';
import { AdminSettings } from './components/AdminSettings';
import { Documentation } from './components/Documentation';
import { AIChatPanel } from './components/AIChatPanel';
import { LiveAudioPanel } from './components/LiveAudioPanel';
import { TwinMetadata, SmartCityInsight, ViewType, ConnectivityStatus } from './types';
import { generateDigitalTwinInsights } from './services/geminiService';

const STORAGE_KEY = 'civic_twin_persistence';

const App: React.FC = () => {
  const [metadata, setMetadata] = useState<TwinMetadata | null>(null);
  const [insights, setInsights] = useState<SmartCityInsight[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [connectivity, setConnectivity] = useState<ConnectivityStatus>('online');

  // AI Panel States
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [isVoiceOpen, setIsVoiceOpen] = useState(false);

  // Load persisted state on mount
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const { metadata: savedMetadata, insights: savedInsights, view: savedView } = JSON.parse(saved);
        if (savedMetadata) setMetadata(savedMetadata);
        if (savedInsights) setInsights(savedInsights);
        if (savedView) setCurrentView(savedView);
        console.log("System state sustained from local persistence.");
      } catch (e) {
        console.error("Persistence hydration failed", e);
      }
    }
  }, []);

  // Persist state changes
  useEffect(() => {
    if (metadata) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({
        metadata,
        insights,
        view: currentView
      }));
    }
  }, [metadata, insights, currentView]);

  // Connectivity Listener
  useEffect(() => {
    const updateStatus = () => {
      setConnectivity(navigator.onLine ? 'online' : 'offline-fog');
    };
    window.addEventListener('online', updateStatus);
    window.addEventListener('offline', updateStatus);
    updateStatus();
    return () => {
      window.removeEventListener('online', updateStatus);
      window.removeEventListener('offline', updateStatus);
    };
  }, []);

  const fetchInsights = useCallback(async (data: TwinMetadata) => {
    if (!navigator.onLine) {
      console.warn("Offline mode: Skipping AI insight generation. Using Fog cached logic.");
      return;
    }
    setIsLoading(true);
    try {
      const results = await generateDigitalTwinInsights(data);
      setInsights(results);
    } catch (err) {
      console.error("Failed to load twin insights", err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleOnboardingComplete = (data: TwinMetadata) => {
    setMetadata(data);
    fetchInsights(data);
  };

  const handleRefresh = () => {
    if (metadata) fetchInsights(metadata);
  };

  const renderContent = () => {
    if (currentView === 'documentation') {
      return <Documentation />;
    }

    if (currentView === 'admin') {
      return <AdminSettings metadata={metadata} />;
    }

    if (!metadata) {
      return <Onboarding onComplete={handleOnboardingComplete} />;
    }

    switch (currentView) {
      case 'dashboard':
        return (
          <Dashboard 
            metadata={metadata} 
            insights={insights} 
            isLoading={isLoading} 
            onRefresh={handleRefresh}
            connectivity={connectivity}
          />
        );
      case 'gis-analysis':
        return <GISAnalysis metadata={metadata} connectivity={connectivity} />;
      default:
        return null;
    }
  };

  return (
    <Layout 
      currentView={currentView} 
      onViewChange={setCurrentView} 
      isMetadataSet={!!metadata}
      connectivity={connectivity}
    >
      {renderContent()}

      {/* AI Access Triggers */}
      {metadata && (
        <div className="fixed bottom-6 right-6 z-[3000] flex flex-col gap-3">
          <button 
            onClick={() => setIsVoiceOpen(true)}
            className="w-14 h-14 bg-emerald-600 text-white rounded-2xl shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all group"
            title="Open AI Voice"
          >
            <span className="text-2xl group-hover:animate-pulse">🎙️</span>
          </button>
          <button 
            onClick={() => setIsChatOpen(true)}
            className="w-14 h-14 bg-blue-600 text-white rounded-2xl shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all group"
            title="Open AI Chat"
          >
            <span className="text-2xl group-hover:animate-pulse">💬</span>
          </button>
        </div>
      )}

      {isChatOpen && (
        <AIChatPanel metadata={metadata} onClose={() => setIsChatOpen(false)} />
      )}

      {isVoiceOpen && (
        <LiveAudioPanel metadata={metadata} onClose={() => setIsVoiceOpen(false)} />
      )}
    </Layout>
  );
};

