          <nav className="space-y-8 flex-1">
            <section className={`p-4 bg-slate-950 border border-slate-800 rounded-2xl transition-opacity ${isTacticalLocked ? 'opacity-30' : 'opacity-100'}`}>
              <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-3">Mesh Telemetry</h3>
              <div className="space-y-2 text-[11px] font-bold">
