  lng: number;
  displayName: string;
}

export type UserRole = 'CID_OPERATOR' | 'MAYOR' | 'CITY_MANAGER' | 'RESIDENT';

export interface CIDUser {
  id: string;
  role: UserRole;
  cid: string;
  name: string;
}

export interface MeshNode {
  id: string;
  status: 'active' | 'relay' | 'failing';
  signal: number; // 0-100
  type: 'Static' | 'Mobile' | 'Fog' | 'Fiber' | 'Wi-Fi';
