    login: string;
    avatar_url: string;
  };
}

export type ViewType = 'dashboard' | 'gis-analysis' | 'admin' | 'documentation';
export type ConnectivityStatus = 'online' | 'offline-fog' | 'disconnected';

export interface TrafficSimState {
  publicTransportAvailability: number;
  trafficDensity: number;
  peakHourDelay: number;
}

import React, { useState } from 'react';
import { TwinMetadata, GISLayerEndpoints, CID } from '../types';

interface OnboardingProps {
  onComplete: (metadata: TwinMetadata) => void;
}

export const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState<1 | 2 | 3 | 4 | 5>(1);
  const [formData, setFormData] = useState({
    name: '',
    address: '',
    type: 'City' as TwinMetadata['type'],
    officialUrl: ''
  });
  const [gisLayers, setGisLayers] = useState<GISLayerEndpoints>({
    parcels: '',
    utilities: '',
    infrastructure: '',
    safety: '',
    greenery: ''
  });
  const [cids, setCids] = useState<CID[]>([]);
  const [newCidName, setNewCidName] = useState('');
  const [tempLocation, setTempLocation] = useState<TwinMetadata['location']>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleStep1Submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    try {
      const encodedAddress = encodeURIComponent(formData.address);
      const response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodedAddress}&limit=1`);
      const data = await response.json();

      if (data && data.length > 0) {
        setTempLocation({
          lat: parseFloat(data[0].lat),
          lng: parseFloat(data[0].lon),
          displayName: data[0].display_name
        });
        setStep(2);
      } else {
        setError("Location not found. Try a street address or city name.");
      }
    } catch (err) {
      setError("Connectivity issue. Please check your network.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleAddCid = () => {
    if (!newCidName) return;
    const cid: CID = {
      id: Math.floor(Math.random() * 900 + 100).toString(),
      name: newCidName,
      population: Math.floor(Math.random() * 5000 + 500),
      meshActive: true
    };
    setCids([...cids, cid]);
    setNewCidName('');
  };

  const finalizeOnboarding = (layers?: GISLayerEndpoints) => {
    onComplete({
      name: formData.name,
      address: formData.address,
      type: formData.type,
      location: tempLocation,
      officialUrl: formData.officialUrl,
      gisLayers: layers,
      isEmergencyMode: false,
      cids: cids.length > 0 ? cids : [
        { id: '772', name: `${formData.name} Central CID`, population: 1200, meshActive: true },
        { id: '104', name: `${formData.name} Highlands CID`, population: 850, meshActive: true }
      ]
    });
  };

  if (step === 5) {
    return (
      <div className="flex-1 flex items-center justify-center p-4">
        <div className="w-full max-w-xl bg-white rounded-[2.5rem] shadow-2xl border border-slate-200 overflow-hidden animate-in fade-in zoom-in-95 duration-500">
          <div className="p-8 text-center bg-blue-50 border-b border-blue-200">
            <h2 className="text-3xl font-black text-slate-900 mb-2">Define Community IDs</h2>
            <p className="text-sm text-slate-700 font-medium">Link local CIDs to your Wi-Fi Mesh Fog network (B-lan).</p>
          </div>
          <div className="p-8 space-y-6">
            <div className="flex gap-2">
              <input 
                type="text" 
                value={newCidName}
                onChange={(e) => setNewCidName(e.target.value)}
                placeholder="Community / CID Name" 
                className="flex-1 px-5 py-4 bg-slate-50 border border-slate-300 rounded-2xl outline-none"
              />
              <button 
                onClick={handleAddCid}
                className="px-6 py-4 bg-blue-600 text-white font-black rounded-2xl"
              >Add</button>
            </div>
            <div className="max-h-48 overflow-y-auto space-y-2">
              {cids.map(c => (
                <div key={c.id} className="p-4 bg-slate-50 border rounded-xl flex items-center justify-between">
                  <span className="font-bold text-slate-900">{c.name}</span>
                  <span className="text-[10px] font-black text-blue-600 uppercase">CID-{c.id}</span>
                </div>
              ))}
            </div>
            <button
              onClick={() => finalizeOnboarding(gisLayers)}
              className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl shadow-xl uppercase text-xs tracking-[0.2em]"
            >Launch Digital Twin Core</button>
          </div>
        </div>
      </div>
    );
  }

  if (step === 4) {
    return (
      <div className="flex-1 flex items-center justify-center p-4">
        <div className="w-full max-w-3xl bg-white rounded-[2.5rem] shadow-2xl border border-slate-200 overflow-hidden">
          <div className="p-8 text-center bg-emerald-50 border-b border-emerald-200">
             <h2 className="text-3xl font-black text-slate-900 mb-2">Configure GIS Layers</h2>
             <p className="text-sm text-slate-700 font-medium">Provide spatial endpoints (GeoJSON/FeatureLayers) for modeling.</p>
          </div>
          <form onSubmit={(e) => { e.preventDefault(); setStep(5); }} className="p-8 space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {[
                { key: 'parcels', label: 'Parcel Boundaries' },
                { key: 'utilities', label: 'Underground Utilities' },
                { key: 'greenery', label: 'Public Green Space' },
                { key: 'infrastructure', label: 'General Infrastructure' },
                { key: 'safety', label: 'Public Safety Nodes' }
              ].map(item => (
                <div key={item.key} className="space-y-1.5">
                  <label className="text-xs font-black text-slate-700 uppercase tracking-widest ml-1">{item.label}</label>
                  <input
                    type="url"
                    className="w-full px-5 py-4 bg-slate-50 border border-slate-300 rounded-2xl text-sm"
                    placeholder={`https://gis-server/api/${item.key}`}
                    value={(gisLayers as any)[item.key]}
                    onChange={(e) => setGisLayers({ ...gisLayers, [item.key]: e.target.value })}
                  />
                </div>
              ))}
            </div>
            <button type="submit" className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl uppercase text-xs tracking-widest">Next: Define CIDs</button>
          </form>
        </div>
      </div>
    );
  }

  if (step === 3) {
    return (
      <div className="flex-1 flex items-center justify-center p-4">
        <div className="w-full max-w-xl bg-white rounded-[2.5rem] shadow-2xl border border-slate-200 overflow-hidden">
          <div className="p-12 text-center">
            <h2 className="text-3xl font-black text-slate-900 mb-6">GIS Data Strategy</h2>
            <div className="space-y-4">
              <button onClick={() => setStep(4)} className="w-full p-6 bg-slate-900 text-white rounded-2xl font-bold flex items-center justify-between">
                <span>Add Custom GIS Layers</span>
                <span>→</span>
              </button>
              <button onClick={() => setStep(5)} className="w-full p-6 border-2 border-slate-200 text-slate-800 rounded-2xl font-bold flex items-center justify-between">
                <span>Use AI Data Defaults</span>
                <span>⚡</span>
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (step === 2) {
    return (
      <div className="flex-1 flex items-center justify-center p-4">
        <div className="w-full max-w-xl bg-white rounded-[2.5rem] shadow-2xl border border-slate-200 overflow-hidden">
          <div className="p-8 text-center bg-blue-50 border-b border-blue-200">
            <h2 className="text-3xl font-black text-slate-900 mb-2">Connect Portal</h2>
            <p className="text-sm text-slate-700 font-medium">Link your official city website for AI data scraping.</p>
          </div>
          <form onSubmit={(e) => { e.preventDefault(); setStep(3); }} className="p-8 space-y-6">
            <input
              type="url"
              required
              className="w-full px-5 py-4 bg-slate-50 border border-slate-300 rounded-2xl outline-none"
              placeholder="https://www.cityname.gov"
              value={formData.officialUrl}
              onChange={(e) => setFormData({ ...formData, officialUrl: e.target.value })}
            />
            <div className="flex gap-4">
               <button type="button" onClick={() => setStep(1)} className="flex-1 py-5 border-2 border-slate-200 rounded-2xl font-bold">Back</button>
               <button type="submit" className="flex-[2] py-5 bg-blue-600 text-white rounded-2xl font-black shadow-lg">Next Step</button>
            </div>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex-1 flex items-center justify-center p-4">
      <div className="w-full max-w-xl bg-white rounded-[2.5rem] shadow-2xl border border-slate-200 overflow-hidden">
        <div className="p-8 text-center bg-slate-50 border-b border-slate-200">
          <h2 className="text-3xl font-black text-slate-900 mb-2">Initialize Civic Twin</h2>
          <p className="text-sm text-slate-700 font-medium">Calibrate your physical region for spatial simulation.</p>
        </div>
        <form onSubmit={handleStep1Submit} className="p-8 space-y-6">
          <input
            type="text"
            required
            className="w-full px-5 py-4 bg-slate-50 border border-slate-300 rounded-2xl outline-none"
            placeholder="Entity Name"
            value={formData.name}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
          />
          <input
            type="text"
            required
            className="w-full px-5 py-4 bg-slate-50 border border-slate-300 rounded-2xl outline-none"
            placeholder="Official Address"
            value={formData.address}
            onChange={(e) => setFormData({ ...formData, address: e.target.value })}
          />
          <button
            type="submit"
            disabled={isLoading}
            className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl shadow-xl uppercase text-xs tracking-widest flex items-center justify-center gap-3"
          >
            {isLoading ? 'Calibrating...' : 'Next: Configure Portal'}
          </button>
        </form>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { GeoLocation, GISLayerEndpoints } from '../types';

interface MapProps {
  location: GeoLocation;
  name: string;
  isExpanded?: boolean;
  gisLayers?: GISLayerEndpoints;
}

interface WeatherInfo {
  temp: number;
  windSpeed: number;
  conditionCode: number;
  conditionText: string;
}

type MapMode = 'street' | 'satellite' | 'topo';

export const Map: React.FC<MapProps> = ({ location, name, isExpanded, gisLayers }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const baseLayerRef = useRef<any>(null);

  // GIS Layer Groups
  const parcelsLayerRef = useRef<any>(null);
  const utilitiesLayerRef = useRef<any>(null);
  const greeneryLayerRef = useRef<any>(null);
  const householdLayerRef = useRef<any>(null);
  const heatmapLayerRef = useRef<any>(null);

  const [streetViewCoords, setStreetViewCoords] = useState<{lat: number, lng: number} | null>(null);
  const [weatherInfo, setWeatherInfo] = useState<WeatherInfo | null>(null);
  const [mapMode, setMapMode] = useState<MapMode>('street');
  const [isGisLoaded, setIsGisLoaded] = useState<Record<string, boolean>>({});

  const [layers, setLayers] = useState({
    parcels: true,
    utilities: true,
    greenery: true,
    households: true,
    heatmap: true
  });

  const getWeatherText = (code: number) => {
    if (code === 0) return 'Clear Sky';
    if (code <= 3) return 'Partly Cloudy';
    if (code <= 48) return 'Foggy';
    if (code <= 67) return 'Rain / Drizzle';
    if (code <= 77) return 'Snow';
    if (code <= 99) return 'Thunderstorm';
    return 'Overcast';
  };

  const fetchWeatherData = async () => {
    try {
      const response = await fetch(
        `https://api.open-meteo.com/v1/forecast?latitude=${location.lat}&longitude=${location.lng}&current_weather=true`
      );
      const data = await response.json();
      if (data.current_weather) {
        setWeatherInfo({
          temp: data.current_weather.temperature,
          windSpeed: data.current_weather.windspeed,
          conditionCode: data.current_weather.weathercode,
          conditionText: getWeatherText(data.current_weather.weathercode)
        });
      }
    } catch (err) {
      console.error("Weather sync failed", err);
    }
  };

  const updateBaseLayer = () => {
    if (!mapRef.current) return;
    const L = (window as any).L;
    if (!L) return;

    if (baseLayerRef.current) {
      mapRef.current.removeLayer(baseLayerRef.current);
    }

    let url = '';
    let options: any = { 
      maxZoom: 19,
      noWrap: false
    };

    switch (mapMode) {
      case 'satellite':
        url = 'https://{s}.google.com/vt/lyrs=y&x={x}&y={y}&z={z}';
        options = {
          ...options,
          subdomains: ['mt0', 'mt1', 'mt2', 'mt3'],
          attribution: 'Map data &copy; Google'
        };
        break;
      case 'topo':
        url = 'https://basemap.nationalmap.gov/arcgis/rest/services/USGSTopo/MapServer/tile/{z}/{y}/{x}';
        options = {
          ...options,
          maxZoom: 16,
          attribution: 'Tiles courtesy of the U.S. Geological Survey'
        };
        break;
      case 'street':
      default:
        url = 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png';
        options = {
          ...options,
          attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
        };
        break;
    }

    baseLayerRef.current = L.tileLayer(url, options).addTo(mapRef.current);
    baseLayerRef.current.bringToBack();
  };

  const loadDynamicGisLayer = async (url: string, layerRef: React.MutableRefObject<any>, style: any, name: string) => {
    if (!url || !mapRef.current) return;
    const L = (window as any).L;
    if (!L) return;

    try {
      const response = await fetch(url);
      if (!response.ok) throw new Error(`HTTP error ${response.status}`);
      const data = await response.json();

      // Clear previous content in this layer group
      layerRef.current.clearLayers();

      // Add GeoJSON to the group
      L.geoJSON(data, { style }).addTo(layerRef.current);
      setIsGisLoaded(prev => ({ ...prev, [name]: true }));
      console.log(`Successfully loaded dynamic GIS layer: ${name}`);
    } catch (err) {
      console.error(`Failed to load dynamic GIS layer: ${name}`, err);
    }
  };

  // 1. Initial Map Setup
  useEffect(() => {
    if (!mapContainerRef.current) return;
    const L = (window as any).L;
    if (!L) return;

    if (!mapRef.current) {
      const initMap = () => {
        if (!mapContainerRef.current) return;

        mapRef.current = L.map(mapContainerRef.current, {
          zoomControl: false,
          attributionControl: true,
          fadeAnimation: true,
          trackResize: true
        }).setView([location.lat, location.lng], 15);

        L.control.zoom({ position: 'bottomleft' }).addTo(mapRef.current);

        parcelsLayerRef.current = L.layerGroup();
        utilitiesLayerRef.current = L.layerGroup();
        greeneryLayerRef.current = L.layerGroup();
        householdLayerRef.current = L.layerGroup();

        // Load dynamic layers if URLs provided, otherwise use simulation
        if (gisLayers?.parcels) {
          loadDynamicGisLayer(gisLayers.parcels, parcelsLayerRef, { color: '#3b82f6', weight: 1, fillOpacity: 0.2 }, 'Parcels');
        } else {
          const parcelStyle = { color: '#3b82f6', weight: 1, fillOpacity: 0.1, fillColor: '#3b82f6' };
          for (let i = -2; i <= 2; i++) {
            for (let j = -2; j <= 2; j++) {
              L.rectangle([
                [location.lat + i * 0.001, location.lng + j * 0.0015],
                [location.lat + (i + 0.6) * 0.001, location.lng + (j + 0.8) * 0.0015]
              ], parcelStyle).addTo(parcelsLayerRef.current);
            }
          }
        }

        if (gisLayers?.utilities) {
          loadDynamicGisLayer(gisLayers.utilities, utilitiesLayerRef, { color: '#f59e0b', weight: 3, dashArray: '5, 5' }, 'Utilities');
        } else {
          const utilityStyle = { color: '#f59e0b', weight: 4, dashArray: '8, 8' };
          L.polyline([
            [location.lat - 0.004, location.lng - 0.004],
            [location.lat + 0.004, location.lng + 0.004]
          ], utilityStyle).addTo(utilitiesLayerRef.current);
        }

        if (gisLayers?.greenery) {
          loadDynamicGisLayer(gisLayers.greenery, greeneryLayerRef, { color: '#10b981', weight: 1, fillOpacity: 0.4, fillColor: '#10b981' }, 'Greenery');
        } else {
          // No default simulation for greenery currently, but prepared for layer group
        }

        const pings: [number, number, number][] = [
          [location.lat + 0.0005, location.lng + 0.0005, 1],
          [location.lat - 0.001, location.lng - 0.0005, 0.7],
          [location.lat + 0.001, location.lng - 0.001, 0.9]
        ];

        pings.forEach((p, idx) => {
          L.circleMarker([p[0], p[1]], { radius: 8, color: '#1e293b', fillColor: '#3b82f6', fillOpacity: 0.8 })
            .addTo(householdLayerRef.current)
            .bindPopup(`<b class="text-xs">Node CT-${idx + 101}</b><br/><span class="text-[10px] text-slate-500 font-bold">Active Mesh Relay</span>`);
        });

        if (L.heatLayer) {
          const initHeat = () => {
            if (!mapRef.current) return;
            const container = mapContainerRef.current;
            if (container && container.clientWidth > 0 && container.clientHeight > 0) {
              heatmapLayerRef.current = L.heatLayer(pings, { radius: 30, blur: 15 });
              if (layers.heatmap) heatmapLayerRef.current.addTo(mapRef.current);
            } else {
              setTimeout(initHeat, 250);
            }
          };
          initHeat();
        }

        updateBaseLayer();
        mapRef.current.invalidateSize();
      };

      if (mapContainerRef.current.clientWidth > 0) {
        initMap();
      } else {
        setTimeout(initMap, 100);
      }
    } else {
      mapRef.current.setView([location.lat, location.lng], mapRef.current.getZoom());
    }

    const handleSVOpen = (e: any) => setStreetViewCoords(e.detail);
    window.addEventListener('open-street-view', handleSVOpen);

    const observer = new ResizeObserver(() => {
      if (mapRef.current) {
        mapRef.current.invalidateSize();
      }
    });
    observer.observe(mapContainerRef.current);

    fetchWeatherData();

    return () => {
      window.removeEventListener('open-street-view', handleSVOpen);
      observer.disconnect();
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
      }
    };
  }, [location, gisLayers]);

  // 2. React to Map Mode and Layer Selection
  useEffect(() => {
    updateBaseLayer();
  }, [mapMode]);

  useEffect(() => {
    if (!mapRef.current) return;
    const overlayRefs = [
      { ref: parcelsLayerRef, active: layers.parcels },
      { ref: utilitiesLayerRef, active: layers.utilities },
      { ref: greeneryLayerRef, active: layers.greenery },
      { ref: householdLayerRef, active: layers.households },
      { ref: heatmapLayerRef, active: layers.heatmap }
    ];

    overlayRefs.forEach(item => {
      if (!item.ref.current) return;
      if (item.active) {
        if (!mapRef.current.hasLayer(item.ref.current)) item.ref.current.addTo(mapRef.current);
      } else {
        if (mapRef.current.hasLayer(item.ref.current)) mapRef.current.removeLayer(item.ref.current);
      }
    });
  }, [layers]);

  // 3. Size Invalidation for expansion animations
  useEffect(() => {
    if (mapRef.current) {
      const timers = [100, 300, 500, 800, 1200].map(ms => 
        setTimeout(() => {
          if (mapRef.current) mapRef.current.invalidateSize();
        }, ms)
      );
      return () => timers.forEach(clearTimeout);
    }
  }, [isExpanded]);

  const toggleLayer = (layer: keyof typeof layers) => {
    setLayers(prev => ({ ...prev, [layer]: !prev[layer] }));
  };

  return (
    <div className="w-full h-full relative bg-slate-200 transition-all duration-500 overflow-hidden">
      <div 
        ref={mapContainerRef} 
        className="w-full h-full absolute inset-0 z-0 bg-slate-200" 
      />

      {/* HUD Controls */}
      <div className="absolute top-4 left-4 z-[1000] flex flex-col gap-3 pointer-events-none max-w-[240px]">
        <div className="glass-panel px-4 py-3 rounded-2xl text-[11px] font-black text-slate-800 shadow-2xl border border-white/60 flex items-center gap-2.5 pointer-events-auto">
          <span className="w-2.5 h-2.5 bg-blue-600 rounded-full animate-pulse shadow-[0_0_8px_rgba(59,130,246,0.6)]"></span>
          GIS ACTIVE ENGINE
        </div>

        <div className="glass-panel p-2 rounded-2xl shadow-xl border border-white/60 pointer-events-auto bg-white/95 backdrop-blur-md flex flex-col gap-1.5">
          <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest px-2 leading-none">Perspective</p>
          <div className="flex flex-col gap-1">
            {[
              { id: 'street', label: 'OpenStreetMap', icon: '🏙️' },
              { id: 'satellite', label: 'Satellite', icon: '🌍' },
              { id: 'topo', label: 'USGS Topo', icon: '⛰️' }
            ].map((mode) => (
              <button
                key={mode.id}
                onClick={() => setMapMode(mode.id as MapMode)}
                className={`flex items-center gap-3 px-3 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all border ${mapMode === mode.id ? 'bg-slate-900 text-white border-slate-800' : 'bg-white text-slate-500 border-slate-200 hover:bg-slate-50'}`}
              >
                <span className="text-sm">{mode.icon}</span>
                <span className="truncate">{mode.label}</span>
                {mapMode === mode.id && <div className="ml-auto w-1.5 h-1.5 bg-blue-500 rounded-full"></div>}
              </button>
            ))}
          </div>
        </div>

        <div className="glass-panel p-3 rounded-2xl shadow-xl border border-white/60 pointer-events-auto bg-white/95 backdrop-blur-md flex flex-col gap-2">
           <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest px-1 leading-none">Spatial Overlays</p>
           {[
             { id: 'parcels', label: 'Parcels', icon: '📦', color: 'bg-blue-600', isLive: !!gisLayers?.parcels },
             { id: 'utilities', label: 'Utilities', icon: '⚡', color: 'bg-amber-500', isLive: !!gisLayers?.utilities },
             { id: 'greenery', label: 'Green Space', icon: '🌳', color: 'bg-emerald-500', isLive: !!gisLayers?.greenery },
             { id: 'households', label: 'Mesh Pings', icon: '🛰️', color: 'bg-indigo-500', isLive: false },
             { id: 'heatmap', label: 'Heatmap', icon: '🔥', color: 'bg-rose-500', isLive: false }
           ].map(layer => (
             <button
               key={layer.id}
               onClick={() => toggleLayer(layer.id as any)}
               className={`flex items-center gap-3 px-3 py-2 rounded-xl text-[10px] font-black uppercase transition-all border ${layers[layer.id as keyof typeof layers] ? 'bg-slate-100 text-slate-900 border-slate-300' : 'bg-white text-slate-400 border-slate-100 opacity-60'}`}
             >
               <div className={`w-2.5 h-2.5 rounded-full ${layers[layer.id as keyof typeof layers] ? layer.color : 'bg-slate-200'}`} />
               <span className="truncate flex-1 text-left">{layer.label}</span>
               {layer.isLive && (
                 <span className="text-[7px] bg-emerald-100 text-emerald-700 px-1 rounded-sm border border-emerald-200">LIVE</span>
               )}
             </button>
           ))}
        </div>

        {weatherInfo && (
          <div className="glass-panel px-4 py-3 rounded-2xl shadow-xl border border-white/60 flex flex-col gap-1 pointer-events-auto bg-white/90 backdrop-blur-md">
            <div className="flex items-center gap-3">
              <span className="text-xl">
                {weatherInfo.conditionCode < 3 ? '☀️' : weatherInfo.conditionCode < 50 ? '☁️' : '🌧️'}
              </span>
              <div>
                <p className="text-[10px] font-black text-slate-900 uppercase tracking-widest mb-0.5">{weatherInfo.conditionText}</p>
                <div className="flex items-baseline gap-1">
                  <span className="text-sm font-black text-slate-900">{weatherInfo.temp}°C</span>
                  <span className="text-[8px] font-bold text-slate-500 uppercase">Live</span>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {streetViewCoords && (
        <div className="absolute inset-0 z-[3000] bg-slate-900 animate-in fade-in zoom-in-95 duration-300">
          <header className="absolute top-4 left-4 right-4 z-[3100] flex justify-between items-center px-6 py-4 bg-white/95 backdrop-blur-md rounded-2xl border border-white/50 shadow-2xl">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white text-lg shadow-lg">👁️</div>
              <div>
                <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Digital Immersion</p>
                <h4 className="text-xs font-bold text-slate-900">Live Street Analysis Point</h4>
              </div>
            </div>
            <button 
              onClick={() => setStreetViewCoords(null)}
              className="w-10 h-10 flex items-center justify-center bg-slate-100 hover:bg-slate-200 text-slate-900 rounded-full font-black text-lg transition-all"
            >✕</button>
          </header>
          <iframe
            title="Google Street View"
            className="w-full h-full border-0"
            loading="lazy"
            allowFullScreen
            src={`https://www.google.com/maps/embed/v1/streetview?key=${process.env.API_KEY}&location=${streetViewCoords.lat},${streetViewCoords.lng}`}
          ></iframe>
        </div>
      )}
    </div>
  );
};

