import React, { useState, useEffect, useCallback } from 'react';
import { Layout } from './components/Layout';
import { Onboarding } from './components/Onboarding';
import { Dashboard } from './components/Dashboard';
import { GISAnalysis } from './components/GISAnalysis';
import { AdminSettings } from './components/AdminSettings';
import { Documentation } from './components/Documentation';
import { AIChatPanel } from './components/AIChatPanel';
import { LiveAudioPanel } from './components/LiveAudioPanel';
import { CIDLogin } from './components/CIDLogin';
import { TwinMetadata, SmartCityInsight, ViewType, ConnectivityStatus, CIDUser } from './types';
import { generateDigitalTwinInsights } from './services/geminiService';

const STORAGE_KEY = 'civic_twin_persistence';

const App: React.FC = () => {
  const [metadata, setMetadata] = useState<TwinMetadata | null>(null);
  const [user, setUser] = useState<CIDUser | null>(null);
  const [insights, setInsights] = useState<SmartCityInsight[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [connectivity, setConnectivity] = useState<ConnectivityStatus>('online');

  const [isChatOpen, setIsChatOpen] = useState(false);
  const [isVoiceOpen, setIsVoiceOpen] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const { metadata: savedMetadata, insights: savedInsights, view: savedView, user: savedUser } = JSON.parse(saved);
        if (savedMetadata) setMetadata(savedMetadata);
        if (savedInsights) setInsights(savedInsights);
        if (savedView) setCurrentView(savedView);
        if (savedUser) setUser(savedUser);
      } catch (e) {
        console.error("Persistence hydration failed", e);
      }
    }
  }, []);

  useEffect(() => {
    if (metadata) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({
        metadata,
        insights,
        view: currentView,
        user
      }));
    }
  }, [metadata, insights, currentView, user]);

  useEffect(() => {
    const updateStatus = () => setConnectivity(navigator.onLine ? 'online' : 'offline-fog');
    window.addEventListener('online', updateStatus);
    window.addEventListener('offline', updateStatus);
    updateStatus();
    return () => {
      window.removeEventListener('online', updateStatus);
      window.removeEventListener('offline', updateStatus);
    };
  }, []);

  const fetchInsights = useCallback(async (data: TwinMetadata) => {
    if (!navigator.onLine) return;
    setIsLoading(true);
    try {
      const results = await generateDigitalTwinInsights(data);
      setInsights(results);
    } catch (err) {
      console.error("Failed to load twin insights", err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleOnboardingComplete = (data: TwinMetadata) => {
    setMetadata(data);
    fetchInsights(data);
  };

  const handleMeshLogin = (userData: CIDUser) => {
    setUser(userData);
    setCurrentView('dashboard'); // Redirect to dashboard after login
  };

  const renderContent = () => {
    if (currentView === 'documentation') return <Documentation />;
    if (currentView === 'admin') return <AdminSettings metadata={metadata} />;

    // Step 1: Initialize GIS Core (Public Entry)
    if (!metadata) return <Onboarding onComplete={handleOnboardingComplete} />;

    // Dedicated Emergency Gateway Page
    if (currentView === 'mesh-gateway') {
      return <CIDLogin cids={metadata.cids} onLogin={handleMeshLogin} isOverlay={false} />;
    }

    // Main Demo Content
    switch (currentView) {
      case 'dashboard':
        return (
          <Dashboard 
            metadata={metadata} 
            insights={insights} 
            isLoading={isLoading} 
            onRefresh={() => fetchInsights(metadata)}
            connectivity={connectivity}
            user={user || { id: 'GUEST', role: 'RESIDENT', cid: 'PUBLIC', name: 'Public Guest' }}
            isTacticalLocked={false} // Demo is fully open now
          />
        );
      case 'gis-analysis':
        return <GISAnalysis metadata={metadata} connectivity={connectivity} />;
      default:
        return null;
    }
  };

  return (
    <Layout 
      currentView={currentView} 
      onViewChange={setCurrentView} 
      isMetadataSet={!!metadata}
      connectivity={connectivity}
    >
      {renderContent()}

      {metadata && (
        <div className="fixed bottom-6 right-6 z-[3000] flex flex-col gap-3">
          {user && user.role !== 'RESIDENT' && (
             <button 
              onClick={() => setIsVoiceOpen(true)}
              className="w-14 h-14 bg-emerald-600 text-white rounded-2xl shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all group"
            >
              <span className="text-2xl group-hover:animate-pulse">🎙️</span>
            </button>
          )}
          <button 
            onClick={() => setIsChatOpen(true)}
            className="w-14 h-14 bg-blue-600 text-white rounded-2xl shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all group"
          >
            <span className="text-2xl group-hover:animate-pulse">💬</span>
          </button>
        </div>
      )}

      {isChatOpen && <AIChatPanel metadata={metadata} onClose={() => setIsChatOpen(false)} />}
      {isVoiceOpen && <LiveAudioPanel metadata={metadata} onClose={() => setIsVoiceOpen(false)} />}
    </Layout>
  );
};

export default App;

