  const [prContent, setPrContent] = useState<{ title: string; body: string } | null>(null);
  const [isGeneratingPR, setIsGeneratingPR] = useState(false);

  // Main Repository Definition
  const MAIN_REPO = "ADD12/Civic-Twin-by-Angel-Sharks";

