    setIsLoadingPRs(true);
    try {
      const response = await fetch(`https://api.github.com/repos/${MAIN_REPO}/pulls`);
      if (response.ok) {
        const data = await response.json();
        setPullRequests(data);
        setLastPrUpdate(new Date().toLocaleTimeString());
