  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsConnecting(true);
    setConnectionLogs([]);
    setLoginError(false);

    const steps = [
      "Pinging A-LAN Tactical Gateway...",
      `Validating Target: ${MAIN_REPO}`,
      "Handshake: Success. Encryption: AES-4096 Active.",
      "Access Granted to Main Core Control."
    ];

    for (const step of steps) {
      setConnectionLogs(prev => [...prev, `[${new Date().toLocaleTimeString()}] ${step}`]);
      await new Promise(r => setTimeout(r, 500));
    }

    if (username === 'admin' && password === '!Asw1Nnw2@') {
      setIsAuthorized(true);
      setIsConnecting(false);
    } else {
      setIsConnecting(false);
      setLoginError(true);
      setTimeout(() => setLoginError(false), 2000);
    }
  };

  if (!isAuthorized) {
    return (
      <div className="flex-1 bg-slate-950 flex items-center justify-center p-6 relative overflow-hidden">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-blue-900/10 via-slate-950 to-slate-950 opacity-40"></div>
        <div className="w-full max-w-lg bg-slate-900 border border-slate-700 rounded-[3rem] p-10 shadow-2xl relative z-10">
          <div className="text-center mb-10">
            <div className="w-20 h-20 bg-emerald-700 rounded-3xl mx-auto flex items-center justify-center text-4xl mb-6 shadow-2xl shadow-emerald-950/40">🛰️</div>
            <h2 className="text-3xl font-black text-white tracking-tight uppercase">Admin Core Login</h2>
            <p className="text-[10px] font-black text-emerald-500 tracking-[0.3em] uppercase mt-3">Link Target: {MAIN_REPO}</p>
          </div>

          {!isConnecting ? (
            <form onSubmit={handleLogin} className="space-y-6">
              <div className="space-y-4">
                <input 
                  type="text" 
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="w-full px-6 py-5 bg-slate-950 border border-slate-700 rounded-2xl text-white outline-none font-bold focus:border-emerald-500 transition-colors"
                  placeholder="Admin ID"
                  required
                />
                <input 
                  type="password" 
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
