              <div className="relative z-10 space-y-8">
                <div className="flex items-center gap-6">
                  <div className="w-16 h-16 bg-rose-600 rounded-2xl flex items-center justify-center text-3xl shadow-xl shadow-rose-900/40">🛰️</div>
